    public bool isAddressVerified { get; set; }
    [DefaultValue(false)]
    public bool isPageEditEnabled { get; set; }
    private bool AddPatientControlNumberValidationErrorMessage(string msg)
    {
        CustomValidator val = new CustomValidator
        {
            IsValid = false,
            ForeColor = System.Drawing.Color.FromName("red"),
            ErrorMessage = msg,
            SetFocusOnError = true,
            Text = msg,
            ValidationGroup = "validateClaims"
        };
        this.Page.Validators.Add(val);

        return false;
    }
    public string IcnNumber = string.Empty;
    protected void btnSave_Click(object sender, EventArgs e)
    {
        try
        {
            if (ddlPrimaryDestinationPayer.SelectedIndex > 0)
            {
                SaveToDb(validationSummary, CON.ActionButtonType.Save);
            }
            OtherpayerInformationExpand();
            ucServiceInformationInstitutional.AdmitSourceEnableStatus();
            Helper.PurgeSessionData();
        }
        catch (Exception ex)
        {
            ThreadId = Guid.NewGuid();
            Logging log = new Logging(ThreadId, "Claim Save db Operation");
            log.CreateLogEntry(string.Format("{0} {1}", "Error occured while saving the claim DB with error" + ex.Message.ToString()), Logging.LogPriority.Error);
            lblglobalerror.Text = "An error has occurred while saving the claim in Db.";
        }
    }

    public string ICN
    {
        get
        {
            if (!string.IsNullOrWhiteSpace(IcnNumber))
                return IcnNumber;
            else
                return string.Empty;
        }
        set
        {
            if (!string.IsNullOrWhiteSpace(value))
                IcnNumber = value.Trim();
        }
    }
    protected DataSet FetchAdditionalProviderInformation()
    {
        DataSet dsAdditional = new DataSet();
        Dictionary<string, string> parms = new Dictionary<string, string>();
        parms.Add("Claim_id", hdnClaimId.Value);
        dsAdditional = svc.SelectPanelsData("claims_additional_provider_information_service", parms);
        return dsAdditional;
    }
