    private void SaveToDb(string validationGroup, int actionButtonType)
    {
        // To check Additional provider panel with all header panels.
        lblAdditionalPanelError.Text = "";
        if (FetchAdditionalProviderInformation().Tables.Count > 0)
        {
            DataTable dsAdditional = FetchAdditionalProviderInformation().Tables[0];

            DataRow[] renderingRow = dsAdditional.Select("Provider_Type ='" + CON.ClaimsAdditionalPanelProviderTypes.RenderingProvider + "'");
            if (renderingRow.Length > 0 && string.IsNullOrEmpty(ucRenderingProviderInformationPanel.RenderingProviderNPI) && string.IsNullOrEmpty(ucRenderingProviderInformationPanel.RenderingProvider_MedicaidID))
            {
                lblAdditionalPanelError.Text = "<div><a href='#ctl00_MainContent_uc5SubmitClaim_ucRenderingProviderInformationPanel_txtRenderingProvNPI' class='errorlist'>*Rendering Provider information should be reported in the header.</a></div>";
                TextBox txtRenderingProvNPI = (TextBox)ucRenderingProviderInformationPanel.FindControl("txtRenderingProvNPI");
                txtRenderingProvNPI.Style.Add("background-color", "gold");
                cpeRenderingProvider.Collapsed = false;
                cpeRenderingProvider.ClientState = "false";
                sepRenderingProvider.InnerText = "- Rendering Provider";
                return;
            }
            else
            {
                TextBox txtRenderingProvNPI = (TextBox)ucRenderingProviderInformationPanel.FindControl("txtRenderingProvNPI");
                txtRenderingProvNPI.Style.Add("background-color", "white");
            }
            DataRow[] assistantRow = dsAdditional.Select("Provider_Type ='" + CON.ClaimsAdditionalPanelProviderTypes.AssistantSurgeon + "'");
            if (assistantRow.Length > 0 && string.IsNullOrEmpty(ucAssistantSurgeon.AssistantSurgeonNPI) && string.IsNullOrEmpty(ucAssistantSurgeon.Assistant_MedicaidID))
            {
                lblAdditionalPanelError.Text = "<div><a href='#ctl00_MainContent_uc5SubmitClaim_ucAssistantSurgeon_txtAssistantSurgeonNPI' class='errorlist'>*Assistant Surgeon Provider information should be reported in the header.</a></div>";
                TextBox txtAssistantSurgeonNPI = (TextBox)ucAssistantSurgeon.FindControl("txtAssistantSurgeonNPI");
                txtAssistantSurgeonNPI.Style.Add("background-color", "gold");
                cpeAssistantSurgeon.Collapsed = false;
                cpeAssistantSurgeon.ClientState = "false";
                sepAssistantSurgeon.InnerText = "- Assistant Surgeon";
                return;
            }
            else
            {
                TextBox txtAssistantSurgeonNPI = (TextBox)ucAssistantSurgeon.FindControl("txtAssistantSurgeonNPI");
                txtAssistantSurgeonNPI.Style.Add("background-color", "white");
            }
            DataRow[] supervisingRow = dsAdditional.Select("Provider_Type ='" + CON.ClaimsAdditionalPanelProviderTypes.SupervisingProvider + "'");
            if (supervisingRow.Length > 0 && string.IsNullOrEmpty(ucSupervisingProviderPanel.SupervisingProviderNPI) && string.IsNullOrEmpty(ucSupervisingProviderPanel.SupervisingProvider_MedicaidID))
            {
                lblAdditionalPanelError.Text = "<div><a href='#ctl00_MainContent_uc5SubmitClaim_ucSupervisingProviderPanel_txtSupervisingProviderNPI' class='errorlist'>*Supervising Provider information should be reported in the header.</a></div>";
                TextBox txtSupervisingProviderNPI = (TextBox)ucSupervisingProviderPanel.FindControl("txtSupervisingProviderNPI");
                txtSupervisingProviderNPI.Style.Add("background-color", "gold");
                cpeSupervisingProvider.Collapsed = false;
                cpeSupervisingProvider.ClientState = "false";
                sepSupervisingProvider.InnerText = "- Supervising Provider";
                return;
            }
            else
            {
                TextBox txtSupervisingProviderNPI = (TextBox)ucSupervisingProviderPanel.FindControl("txtSupervisingProviderNPI");
                txtSupervisingProviderNPI.Style.Add("background-color", "white");
            }
            DataRow[] servicefacilityRow = dsAdditional.Select("Provider_Type ='" + CON.ClaimsAdditionalPanelProviderTypes.ServiceFacilityProvider + "'");
            if (servicefacilityRow.Length > 0 && string.IsNullOrEmpty(ucServiceFacility.NPIServiceFacilityInformation) && string.IsNullOrEmpty(ucServiceFacility.MedicaidIdServiceFacilityInformation))
            {
                lblAdditionalPanelError.Text = "<div><a href='#ctl00_MainContent_uc5SubmitClaim_ucServiceFacility_txtNPIServiceFacilityLocation' class='errorlist'>*Service Facility information should be reported in the header.</a></div>";
                TextBox txtNPIServiceFacilityLocation = (TextBox)ucServiceFacility.FindControl("txtNPIServiceFacilityLocation");
                txtNPIServiceFacilityLocation.Style.Add("background-color", "gold");
                CollapsiblePanelExtender cpeServiceFacility = (CollapsiblePanelExtender)ucServiceFacility.FindControl("cpeServiceFacility");
                cpeServiceFacility.Collapsed = false;
                cpeServiceFacility.ClientState = "false";
                var spanSerFac = (HtmlGenericControl)ucServiceFacility.FindControl("Span2");
                spanSerFac.InnerText = "- Service Facility Location Information";
                return;
            }
            else
            {
                TextBox txtNPIServiceFacilityLocation = (TextBox)ucServiceFacility.FindControl("txtNPIServiceFacilityLocation");
                txtNPIServiceFacilityLocation.Style.Add("background-color", "white");
            }
            DataRow[] referringRow = dsAdditional.Select("Provider_Type ='" + CON.ClaimsAdditionalPanelProviderTypes.ReferringProvider + "'");
            if (referringRow.Length > 0 && string.IsNullOrEmpty(ucReferringProvider.ReferringProviderNPI) && string.IsNullOrEmpty(ucReferringProvider.ReferringProvider_MedicaidID))
            {
                lblAdditionalPanelError.Text = "<div><a href='#ctl00_MainContent_uc5SubmitClaim_ucReferringProvider_txtReferringProviderNPI' class='errorlist'>*Referring Provider information should be reported in the header.</a></div>";
                TextBox txtReferringProviderNPI = (TextBox)ucReferringProvider.FindControl("txtReferringProviderNPI");
                txtReferringProviderNPI.Style.Add("background-color", "gold");
                cpeReferringProvider.Collapsed = false;
                cpeReferringProvider.ClientState = "false";
                sepReferringProvider.InnerText = "- Referring Provider";
                return;
            }
            else
            {
                TextBox txtReferringProviderNPI = (TextBox)ucReferringProvider.FindControl("txtReferringProviderNPI");
                txtReferringProviderNPI.Style.Add("background-color", "white");
            }
            DataRow[] primaryRow = dsAdditional.Select("Provider_Type ='" + CON.ClaimsAdditionalPanelProviderTypes.PrimaryCareProvider + "'");
            if (primaryRow.Length > 0 && string.IsNullOrEmpty(ucReferringProvider.PrimaryCareProviderNPI) && string.IsNullOrEmpty(ucReferringProvider.PrimaryCareProvider_MedicaidID))
            {
                lblAdditionalPanelError.Text = "<div><a href='#ctl00_MainContent_uc5SubmitClaim_ucReferringProvider_txtPrimaryCareProviderNPI' class='errorlist'>*Primary Care Provider information should be reported in the header.</a></div>";
                TextBox txtPrimaryCareProviderNPI = (TextBox)ucReferringProvider.FindControl("txtPrimaryCareProviderNPI");
                txtPrimaryCareProviderNPI.Style.Add("background-color", "gold");
                cpeReferringProvider.Collapsed = false;
                cpeReferringProvider.ClientState = "false";
                sepReferringProvider.InnerText = "- Referring Provider";
                return;
            }
            else
            {
                TextBox txtPrimaryCareProviderNPI = (TextBox)ucReferringProvider.FindControl("txtPrimaryCareProviderNPI");
                txtPrimaryCareProviderNPI.Style.Add("background-color", "white");
            }
            DataRow[] operatingRow = dsAdditional.Select("Provider_Type ='" + CON.ClaimsAdditionalPanelProviderTypes.OperatingPhysician + "'");
            if (operatingRow.Length > 0 && string.IsNullOrEmpty(ucSupervisingProviderPanel.SupervisingProviderNPI) && string.IsNullOrEmpty(ucSupervisingProviderPanel.SupervisingProvider_MedicaidID))
            {
                lblAdditionalPanelError.Text = "<div><a href='#ctl00_MainContent_uc5SubmitClaim_ucSupervisingProviderPanel_txtSupervisingProviderNPI' class='errorlist'>*Operating Physician Provider information should be reported in the header.</a></div>";
                TextBox txtSupervisingProviderNPI = (TextBox)ucSupervisingProviderPanel.FindControl("txtSupervisingProviderNPI");
                txtSupervisingProviderNPI.Style.Add("background-color", "gold");
                cpeSupervisingProvider.Collapsed = false;
                cpeSupervisingProvider.ClientState = "false";
                sepSupervisingProvider.InnerText = "- Operating Physician Information";
                return;
            }
            else
            {
                TextBox txtSupervisingProviderNPI = (TextBox)ucSupervisingProviderPanel.FindControl("txtSupervisingProviderNPI");
                txtSupervisingProviderNPI.Style.Add("background-color", "white");
            }
            DataRow[] otheroperatingRow = dsAdditional.Select("Provider_Type ='" + CON.ClaimsAdditionalPanelProviderTypes.OtherOperatingPhysician + "'");
            if (otheroperatingRow.Length > 0 && string.IsNullOrEmpty(ucAssistantSurgeon.AssistantSurgeonNPI) && string.IsNullOrEmpty(ucAssistantSurgeon.Assistant_MedicaidID))
            {
                lblAdditionalPanelError.Text = "<div><a href='#ctl00_MainContent_uc5SubmitClaim_ucAssistantSurgeon_txtAssistantSurgeonNPI' class='errorlist'>*Other Operating Physician Provider information should be reported in the header.</a></div>";
                TextBox txtAssistantSurgeonNPI = (TextBox)ucAssistantSurgeon.FindControl("txtAssistantSurgeonNPI");
                txtAssistantSurgeonNPI.Style.Add("background-color", "gold");
                cpeAssistantSurgeon.Collapsed = false;
                cpeAssistantSurgeon.ClientState = "false";
                sepAssistantSurgeon.InnerText = "- Other Operating Physician Information";
                return;
            }
            else
            {
                TextBox txtAssistantSurgeonNPI = (TextBox)ucAssistantSurgeon.FindControl("txtAssistantSurgeonNPI");
                txtAssistantSurgeonNPI.Style.Add("background-color", "white");
            }

            // Primary care panel css if referring is not yet enterred.

            if (string.IsNullOrEmpty(ucReferringProvider.ReferringProviderNPI))
            {
                TextBox txtPrimaryCareProviderNPI = (TextBox)ucReferringProvider.FindControl("txtPrimaryCareProviderNPI");
                txtPrimaryCareProviderNPI.Style.Add("background-color", "lightgray");
                txtPrimaryCareProviderNPI.Enabled = false;
            }
            else
            {
                TextBox txtPrimaryCareProviderNPI = (TextBox)ucReferringProvider.FindControl("txtPrimaryCareProviderNPI");
                txtPrimaryCareProviderNPI.Style.Add("background-color", "white");
                txtPrimaryCareProviderNPI.Enabled = true;
            }

            if (string.IsNullOrWhiteSpace(ddlDestinationPayerResponsibilitySequence.SelectedItem.Text))
            {
                AddPatientControlNumberValidationErrorMessage("<div>Destination payer responsibility sequence is required</div>");
                return;
            }
            if (string.IsNullOrWhiteSpace(ddlDestinationPayerID.SelectedItem.Text))
            {
                if (!string.IsNullOrWhiteSpace(ddlPrimaryDestinationPayer.SelectedItem.Text))
                {
                    //LoadDestinatinationPayerID();
                }
            }
            if (string.IsNullOrWhiteSpace(ddlPrimaryDestinationPayer.SelectedItem.Text))
            {
                AddPatientControlNumberValidationErrorMessage("<div>Destination payer is required</div>");
                return;
            }
            if (!string.IsNullOrWhiteSpace(ddlDestinationPayerResponsibilitySequence.SelectedItem.Text) && !string.IsNullOrWhiteSpace(ddlPrimaryDestinationPayer.SelectedItem.Text) && string.IsNullOrWhiteSpace(ucRecipientInformationPanel.PatientControlNumber))
            {
                AddPatientControlNumberValidationErrorMessage("<div>Patient control number is required</div>");
                if (rblClaimType.SelectedValue == CON.ClaimsType.Dental)
                {
                    updateClaimPredetermination();
                }
                return;
            }
            else
            {
                if (ucRecipientInformationPanel != null && ucRecipientInformationPanel.HasInputValue())
                {
                    ucRecipientInformationPanel.SaveRecipientInfo(validationSummary, actionButtonType);
                }

                if (ucAccidentInformation != null && ucAccidentInformation.HasInputValue())
                {
                    ucAccidentInformation.SaveAccidentInformation(validationSummary, actionButtonType);
                }
                if (ucOutpatientAdjudicationInformation != null && ucOutpatientAdjudicationInformation.HasInputValue())
                {
                    ucOutpatientAdjudicationInformation.SaveOutpatientAdjudicationDetails();
                }
                if (ucServiceFacility != null && (ucServiceFacility.HasInputValue() || ucServiceFacility.MedicaidIdServiceFacilityInformation != null))
                {
                    ucServiceFacility.SaveServiceFacilityLocation(validationSummary, actionButtonType);
                }
                if (ucPriorAuthorizationAndReferringPanel != null && ucPriorAuthorizationAndReferringPanel.HasInputValue())
                {
                    ucPriorAuthorizationAndReferringPanel.SavePriorAuthReferNumber();
                }
                if (ucRenderingProviderInformationPanel.RenderingProvider_MedicaidID != "" || ucRenderingProviderInformationPanel.RenderingProviderNPI != "")
                {
                    ucRenderingProviderInformationPanel.SaveRenderingInfo(validationSummary, ucRenderingProviderInformationPanel.RenderingProviderNPI, ucSupervisingProviderPanel.SupervisingProviderNPI, actionButtonType);
                }
                if (ucSupervisingProviderPanel.SupervisingProvider_MedicaidID != null || ucSupervisingProviderPanel.SupervisingProviderNPI != null)
                {
                    ucSupervisingProviderPanel.SaveSupervisingProviderInfo(validationSummary, ucRenderingProviderInformationPanel.RenderingProviderNPI, ucSupervisingProviderPanel.SupervisingProviderNPI, actionButtonType);
                }
                if (ucDelaySubmission != null && ucDelaySubmission.HasInputValue())
                {
                    ucDelaySubmission.SaveDelayedSubmissionResubmissionData(validationSummary, actionButtonType);
                }
                if (rblClaimType.SelectedValue == CON.ClaimsType.Institutional)
                {
                    if (ucServiceInformationInstitutional != null && ucServiceInformationInstitutional.HasInputValue())
                    {
                        ucServiceInformationInstitutional.SaveServiceInformation(validationSummary);
                    }

                    ucInPatientAdjudicationInformation.SaveInPatientAdjudicationInformation();

                    if (ucAssistantSurgeon != null && (ucAssistantSurgeon.Assistant_MedicaidID != "" || ucAssistantSurgeon.AssistantSurgeonNPI != ""))
                    {
                        ucAssistantSurgeon.SaveOtherOperatingPhysicianInfo(validationSummary, actionButtonType);
                    }
                    if (ucReferringProvider.ReferringProviderNPI != "" || ucReferringProvider.ReferringProvider_MedicaidID != "")
                    {
                        ucReferringProvider.SaveReferringProviderInfo(validationSummary, actionButtonType);
                    }
                    if (ucAttendingPhysicianInformation != null && (ucAttendingPhysicianInformation.AttendingPhysician_MedicaidID != "" || ucAttendingPhysicianInformation.AttendingPhysicianNPI != ""))
                    {
                        ucAttendingPhysicianInformation.SaveAttendingPhysicianInfo(validationSummary, actionButtonType);
                    }
                    ucOccurenceSpanInformation.GetOccurenceSpanInformationData(null);
                    ucSubmitClaimOccurrenceInformation1.SetOccurence(null);
                    ucConditionCodeInformation.GetConditionCodeInformation(null);
                    ucSubmitClaimICDProcedureCode.GetICDProcedureCodeData(null);
                    ucNDCDetails.BindNDCDetailGrid(null);

                }
                if (rblClaimType.SelectedValue == CON.ClaimsType.Professional)
                {

                    ucServiceInformationProfessional.SaveServiceInformation(validationSummary, actionButtonType);

                    if (ucAmbulanceInformation != null && ucAmbulanceInformation.HasInputValue())
                    {

                        //nishi6684
                        if (AmbulanceValidation())
                            ucAmbulanceInformation.SaveAmbulanceInformation(validationSummary, actionButtonType);
                    }
                    else
                    {
                        ClearAmbulanceInfoErrorMessage();
                    }
                    if (ucProviderNotes != null && ucProviderNotes.HasInputValue())
                    {
                        ucProviderNotes.btnSave_Click(actionButtonType);
                    }
                    ucNDCDetails.BindNDCDetailGrid(null);
                }
                if (rblClaimType.SelectedValue == CON.ClaimsType.Dental)
                {

                    ucServiceInformationDental.SaveServiceInformation(validationSummary, actionButtonType);

                    if (ucAssistantSurgeon != null && (ucAssistantSurgeon.Assistant_MedicaidID != "" || ucAssistantSurgeon.AssistantSurgeonNPI != ""))
                    {
                        ucAssistantSurgeon.SaveAssistantSurgeon(validationSummary, actionButtonType);
                    }
                    updateClaimPredetermination();
                    ucToothQuadrant.GetToothQuadrtantPanelInfo(null);
                }
                if ((rblClaimType.SelectedValue == CON.ClaimsType.Dental || rblClaimType.SelectedValue == CON.ClaimsType.Professional))
                {
                    if (ucReferringProvider.ReferringProviderNPI != "" || ucReferringProvider.ReferringProvider_MedicaidID != "" ||
                        ucReferringProvider.PrimaryCareProviderNPI != "" || ucReferringProvider.PrimaryCareProvider_MedicaidID != "")
                    {
                        ucReferringProvider.SaveReferringProviderInfo(validationSummary, actionButtonType);
                        ucReferringProvider.SavePrimaryCareInfo(validationSummary, actionButtonType);
                        ucReferringProvider.GetReferringProviderDetails();
                    }
                }
            }
        }
        SaveAdjudicationSummaryData();
        if (actionButtonType == 0)
        {
            MessageBox2.Show("This claim has successfully been saved to the database - to revisit, edit, or submit this over the next three days, you will need to search for and then reload the claim", "Sucess");
        }
    }
