            ucReferringProvider.RenderingProvider_MedicaidID = ucRenderingProviderInformationPanel.RenderingProvider_MedicaidID;
        GetRecipientInformationPanel();
        GetNPIForPopUp();
        ShowHideButtons();
        if (txtstatus2.Text.ToLower() == "pending submission")
        {
            if (rblClaimType.SelectedIndex == -1)
            {
