    private void LoadClaimInformation(string claimType, string claimId, DataSet claimsData)
    {
        if (claimType.ToUpper() == "DENTAL")
        {
            LoadSearchClaimDentalClaimsData(claimsData, claimId);
        }
        else if (claimType.ToUpper() == "INSTITUTIONAL")
        {
            LoadSearchInstitutionalClaimsData(claimsData, claimId);
        }
        else if (claimType.ToUpper() == "PROFESSIONAL")
        {
            LoadSearchProfessionalClaimsData(claimsData, claimId);
        }
    }

    #endregion

    private void ReadingQueryStringData()
    {

        string icn = default(string);
        string claimType = default(string);
        string payerType = default(string);
        string patientControlNumber = default(string);
        string patientAccountNumber = default(string);
        string claimId = default(string);

        try
        {
            if (Request.QueryString != null)
            {
                if (Request.QueryString.Count > 0)
                {
                    if (Request.QueryString.AllKeys.Contains("icn"))
                        icn = Helper.Decrypt(HttpUtility.UrlDecode(Convert.ToString(Request.QueryString["icn"]).TrimStart()));
                    if (Request.QueryString.AllKeys.Contains("ct"))
                        claimType = Helper.Decrypt(HttpUtility.UrlDecode(Convert.ToString(Request.QueryString["ct"]).TrimStart()));
                    if (Request.QueryString.AllKeys.Contains("pt"))
                        payerType = Helper.Decrypt(HttpUtility.UrlDecode(Convert.ToString(Request.QueryString["pt"]).TrimStart()));

                    if (Request.QueryString.AllKeys.Contains("pcn"))
                        patientControlNumber = Helper.Decrypt(HttpUtility.UrlDecode(Convert.ToString(Request.QueryString["pcn"]).TrimStart()));
                    if (Request.QueryString.AllKeys.Contains("pan"))
                        patientAccountNumber = Helper.Decrypt(HttpUtility.UrlDecode(Convert.ToString(Request.QueryString["pan"]).TrimStart()));
                    if (Request.QueryString.AllKeys.Contains("cid"))
                        claimId = Helper.Decrypt(HttpUtility.UrlDecode(Convert.ToString(Request.QueryString["cid"]).TrimStart()));

                }
                if (claimType != null)
                {
                    if (claimType.Equals("null"))
                    {
                        claimType = null;
                    }
                }
                if (icn != null)
                {
                    if (icn.Equals("null"))
                    {
                        icn = null;
                    }
                }
                if (payerType != null)
                {
                    if (payerType.Equals("null"))
                    {
                        payerType = null;
                    }
                }
                if (!string.IsNullOrEmpty(icn) && !string.IsNullOrEmpty(claimType) && !string.IsNullOrEmpty(payerType))
                {
                    if (claimType.ToUpper().Trim() == CON.ClaimType.DENTAL.ToString() || claimType.ToUpper().Trim() == "D" || claimType == "0")
                    {
                        GetDentalClaimInquiry(icn, payerType);
                    }
                    else if (claimType.ToUpper().Trim() == CON.ClaimType.INSTITUTIONAL.ToString() || claimType.ToUpper().Trim() == "I" || claimType == "1")
                    {
                        GetInstitutionalClaimInquiry(icn, payerType);
                    }
                    else if (claimType.ToUpper().Trim() == CON.ClaimType.PROFESSIONAL.ToString() || claimType.ToUpper().Trim() == "P" || claimType == "2")
                    {
                        GetProfessionalClaimInquiry(icn, payerType);
                    }
                }
                else if (!string.IsNullOrEmpty(claimType) && !string.IsNullOrEmpty(claimId))
                {
                    int intClaimId;
                    bool convertToInt = int.TryParse(claimId, out intClaimId);
                    if (convertToInt)
                    {
                        Dictionary<string, string> param = new Dictionary<string, string>();
                        DataSet ClaimsData = new DataSet();
                        string MedicaidID = this.WorkflowPage.MedicaidID;
                        param.Add("Medicaid_Id", MedicaidID);
                        param.Add("Claim_ID", claimId);

                        if (claimType.ToUpper().Trim() == "DENTAL" || claimType.ToUpper().Trim() == "D" || claimType == "0")
                            ClaimsData = svc.SelectPanelsData("claims_search_details", param);
                        else if (claimType.ToUpper() == "INSTITUTIONAL" || claimType.ToUpper().Trim() == "I" || claimType == "1")
                            ClaimsData = svc.SelectPanelsData("claims_search_details_inst", param);
                        else if (claimType.ToUpper() == "PROFESSIONAL" || claimType.ToUpper().Trim() == "P" || claimType == "2")
                            ClaimsData = svc.SelectPanelsData("claims_search_details_prof", param);

                        LoadClaimsFromDb(claimType, claimId, ClaimsData);
                    }
                    else
                    {
                        throw new Exception(String.Format("Error reading saved claim: ClaimType: {0}, claimId: {1}", claimType, claimId));
                    }
                }
            }
        } catch (Exception ex)
        {
            throw new Exception(String.Format("Error discerning payload: {0}", ex.Message));
        }
    }

