    private void ShowHideButtons()
    {
        if (!string.IsNullOrEmpty(txtstatus2.Text.ToString()))
        {
            Session["ClaimStatus"] = txtstatus2.Text.ToString();
        }
        ThreadId = Guid.NewGuid();
        Logging log = new Logging(ThreadId, "AddUpdateClaimsResponse XML Data reload all Dental panel data in ShowHideButtons method");
        log.CreateLogEntry(string.Format("{0} {1}", "Assign Claim id and Cliam type in all panel's for cliam id:", hdnClaimId.Value.ToString()), Logging.LogPriority.Information);
        if (txtstatus2.Text == "Pending Submission")
        {
            btnSave.Visible = true;
            btnSubmit.Visible = true;
            btncancel.Visible = true;
            //OHPNM-7920
            btnReSubmit.Visible = false;
            btnCopy.Visible = false;
            bntAdjust.Visible = false;
            btnVoid.Visible = false;

