    private void SetAdjudicationErrorInfoDent(Dental.AddUpdateClaimsResponse icr)
    {
        DataTable dtcr = GetAdjudicationErrorInfoDT();
        int i = 1;
        //Load Ajudication Details
        if (icr.ClaimLinesResponse != null)
        {
            foreach (Dental.ClaimLineDetailsType ct in icr.ClaimLinesResponse)
            {
                string linenumber = ct.DetailNumber;
                if (ct.ListOfEdits != null)
                {
                    foreach (Dental.EditType cp in ct.ListOfEdits)
                    {
                        dtcr.Rows.Add(linenumber, cp.RuleID, cp.EditDescription);
                        i++;
                    }
                }
            }
            //Load Ajudication Details
            AdjudicationError.ds = dtcr;
        }
    }

    private void SetAdjudicationErrorInfoDentInquiry(Dental.InquireClaimResponse icr)
    {
        DataTable dtcr = GetAdjudicationErrorInfoDT();
