            {
                log.CreateLogEntry(string.Format("{0} {1}", "Load  DestinationPayerResponsibilitySequence data for cliam id: ", hdnClaimId.Value.ToString()), Logging.LogPriority.Information);
                DataTable dt = new DataTable();
                if (dataSetPayerSequence.Tables.Count > 0)
                {
                    dt = dataSetPayerSequence.Tables[0];
                    selectedTable = dt.AsEnumerable()
                                            .Where(r => r.Field<string>("PRIOR_AUTH_SUBMIT_CLAIM_PAYERSEQUENCE_CODE") == dprs)
