        var dp = inquireDentalClaimReponse.DentalClaim837.BHTContainter.SubscriberDetails_2000B.PayerInfo_2010BB.PayerName_2010BB.NM103_SubmitterLastOrOrganizationName;
        if (!string.IsNullOrEmpty(dp) && ddlPrimaryDestinationPayer.Items.FindByText(dp) != null)
        {
            ddlPrimaryDestinationPayer.ClearSelection();
            ddlPrimaryDestinationPayer.Items.FindByText(dp).Selected = true;
        }
        var dprs = inquireDentalClaimReponse.DentalClaim837.BHTContainter.SubscriberDetails_2000B.SubscriberInformation_2000B.SBR01_PayerResponsibilitySequenceNumberCode;
        if (!string.IsNullOrEmpty(dprs))
        {
            ddlDestinationPayerResponsibilitySequence.ClearSelection();
            //ddlDestinationPayerResponsibilitySequence.SelectedValue = dprs;
            if (_spa == null)
            {
                _spa = new PDMSService.PDMSServiceClient();
            }
            DataSet dataSetPayerSequence = _spa.GetPayerSequence();
            DataTable selectedTable = new DataTable();
            if (Helper.HasRows(dataSetPayerSequence))
            {
                DataTable dt = new DataTable();
                dt = dataSetPayerSequence.Tables[0];
                selectedTable = dt.AsEnumerable()
                                        .Where(r => r.Field<string>("PRIOR_AUTH_SUBMIT_CLAIM_PAYERSEQUENCE_CODE") == dprs)
                                        .CopyToDataTable();
                ddlDestinationPayerResponsibilitySequence.Items.FindByText(selectedTable.Rows[0]["PRIOR_AUTH_SUBMIT_CLAIM_PAYERSEQUENCE_DESC"].ToString()).Selected = true;
            }
        }
        //string PayerId = inquireDentalClaimReponse.DentalClaim837.FunctionalGroupHeader.GS03_ApplicationReceiversCode;
        string PayerId = inquireDentalClaimReponse.DentalClaim837.BHTContainter.SubscriberDetails_2000B.PayerInfo_2010BB.PayerName_2010BB.NM109_SubmitterIdentifier;

        if (!string.IsNullOrEmpty(PayerId))
        {
            ddlDestinationPayerID.ClearSelection();
            ddlDestinationPayerID.SelectedValue = PayerId;
        }
        #region OHPNM-9153
        if (!string.IsNullOrEmpty(txtICN2.Text))
        {
            string medicaid = "";
            string npi = "";
            Dictionary<string, string> parms = new Dictionary<string, string>();
            parms = new Dictionary<string, string>();
            DataSet ds = LoadProviderInformation(this.WorkflowPage.MedicaidID);
