                SaveAdjudicationSummaryData();
                log.CreateLogEntry(string.Format("{0} {1}", "SaveAdjudicationSummaryData Method completed for cliam id:", hdnClaimId.Value.ToString()), Logging.LogPriority.Information);

            }
        }
        #endregion

    }

    private void SetDentalClaimsInfo(DataSet dentalClaimsData)
    {
        if (dentalClaimsData.Tables[1].Rows.Count > 0)
        {
            txtstatus2.Text = "Pending Submission";
            txtPaidAmount.Text = dentalClaimsData.Tables[1].Rows[0]["Amount_Paid"] != null ? dentalClaimsData.Tables[1].Rows[0]["Amount_Paid"].ToString() : "";
            txtAdjDate.Text = !string.IsNullOrEmpty(dentalClaimsData.Tables[1].Rows[0]["Adjudication_Date"].ToString()) ? Convert.ToDateTime(dentalClaimsData.Tables[1].Rows[0]["Adjudication_Date"].ToString()).ToString("MM/dd/yyyy") : "";
            rblClaimType.SelectedIndex = 0;
            rblClaimType_SelectedIndexChanged(null, null);
            if (!string.IsNullOrEmpty(dentalClaimsData.Tables[1].Rows[0]["Destination_Payer_ID"].ToString()))
            {
                ddlPrimaryDestinationPayer.ClearSelection();
                ddlPrimaryDestinationPayer.SelectedValue = dentalClaimsData.Tables[1].Rows[0]["Destination_Payer_ID"].ToString();
            }
            if (!string.IsNullOrEmpty(dentalClaimsData.Tables[1].Rows[0]["Destination_Payer_Res_Seq"].ToString()))
            {
                ddlDestinationPayerResponsibilitySequence.ClearSelection();
                ddlDestinationPayerResponsibilitySequence.SelectedValue = dentalClaimsData.Tables[1].Rows[0]["Destination_Payer_Res_Seq"].ToString();
            }
            if (!string.IsNullOrEmpty(dentalClaimsData.Tables[1].Rows[0]["payer_ID"].ToString()))
            {
                ddlDestinationPayerID.ClearSelection();
                LoadDestinatinationPayerID();
