                {
                    ddlDestinationPayerID.SelectedValue = dentalClaimsData.Tables[1].Rows[0]["payer_ID"].ToString();
                }
                catch (Exception ex)
                { }
            }
        }
    }
    private void SetRecipientInfoDental(Dental.AddUpdateClaimsResponse dentalClaimReponse)
    {
        ThreadId = Guid.NewGuid();
        Logging log = new Logging(ThreadId, "Dental XML Data reload form AddUpdate service for Recipient Dental panel");
        log.CreateLogEntry(string.Format("{0} {1}", "Calling   SetRecipientInfoDental  for cliam id: ", hdnClaimId.Value.ToString()), Logging.LogPriority.Information);

        if (dentalClaimReponse.DentalClaim837.BHTContainter != null)
        {
            var si = dentalClaimReponse.DentalClaim837.BHTContainter.SubscriberDetails_2000B.SubscriberInfo_2010BA;
            var cd = dentalClaimReponse.DentalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300[0];
            if (si != null && cd != null)
            {
                ucRecipientInformationPanel.MedicaidBillingNumber = si.SubscriberName_2010BA.NM109_SubmitterIdentifier;
                log.CreateLogEntry(string.Format("{0} {1}", "Binding MedicaidBillingNumber in RecipientInfoDental panel for cliam id: ", hdnClaimId.Value.ToString()), Logging.LogPriority.Information);
                //ucRecipientInformationPanel.BirthDate = si.SubscriberDemographicInformation_2010BA.DMG02_SubscriberBirthDate;
                ucRecipientInformationPanel.BirthDate = !string.IsNullOrEmpty(si.SubscriberDemographicInformation_2010BA.DMG02_SubscriberBirthDate.ToString()) ? DateTime.ParseExact(si.SubscriberDemographicInformation_2010BA.DMG02_SubscriberBirthDate, "yyyyMMdd", System.Globalization.CultureInfo.InvariantCulture).ToString("MM/dd/yyyy", System.Globalization.CultureInfo.InvariantCulture) : "";
                log.CreateLogEntry(string.Format("{0} {1}", "Binding BirthDate in RecipientInfoDental panel for cliam id: ", hdnClaimId.Value.ToString()), Logging.LogPriority.Information);
                //ucRecipientInformationPanel.BirthDate = !string.IsNullOrEmpty(si.SubscriberDemographicInformation_2010BA.DMG02_SubscriberBirthDate.ToString()) ? Convert.ToDateTime(si.SubscriberDemographicInformation_2010BA.DMG02_SubscriberBirthDate).ToString("MM/dd/yyyy") : "";
                ucRecipientInformationPanel.PatientControlNumber = cd.ClaimInformation_2300.CLM01_PatientControlNumber;
                log.CreateLogEntry(string.Format("{0} {1}", "Binding PatientControlNumber in RecipientInfoDental panel for cliam id: ", hdnClaimId.Value.ToString()), Logging.LogPriority.Information);
                ucRecipientInformationPanel.LastName = si.SubscriberName_2010BA.NM103_SubmitterLastOrOrganizationName;
                log.CreateLogEntry(string.Format("{0} {1}", "Binding LastName in RecipientInfoDental panel for cliam id: ", hdnClaimId.Value.ToString()), Logging.LogPriority.Information);
                ucRecipientInformationPanel.FirstName = si.SubscriberName_2010BA.NM104_SubmitterFirstName;
                log.CreateLogEntry(string.Format("{0} {1}", "Binding FirstName in RecipientInfoDental panel for cliam id: ", hdnClaimId.Value.ToString()), Logging.LogPriority.Information);
                ucRecipientInformationPanel.MiddleName = si.SubscriberName_2010BA.NM105_SubmitterMiddleName;
                log.CreateLogEntry(string.Format("{0} {1}", "Binding MiddleName in RecipientInfoDental panel for cliam id: ", hdnClaimId.Value.ToString()), Logging.LogPriority.Information);
                var gender = si.SubscriberDemographicInformation_2010BA.DMG03_SubscriberGenderCode;
                if (gender == "M")
                    ucRecipientInformationPanel.Gender = "Male";
                else if (gender == "F")
                    ucRecipientInformationPanel.Gender = "Female";
                else
                    ucRecipientInformationPanel.Gender = "Other";
                log.CreateLogEntry(string.Format("{0} {1}", "Binding Gender in RecipientInfoDental panel for cliam id: ", hdnClaimId.Value.ToString()), Logging.LogPriority.Information);
                ucRecipientInformationPanel.AddressLine = si.SubscriberAddress_2010BA == null ? "" : si.SubscriberAddress_2010BA.N301_BillingProviderAddressLine;
                ucRecipientInformationPanel.AddressLine2 = si.SubscriberAddress_2010BA == null ? "" : si.SubscriberAddress_2010BA.N302_BillingProviderAddressLine;
                ucRecipientInformationPanel.City = si.SubscriberCityStateZipCode_2010BA == null ? "" : si.SubscriberCityStateZipCode_2010BA.N401_BillingProviderCityName;
                ucRecipientInformationPanel.State = si.SubscriberCityStateZipCode_2010BA == null ? "" : si.SubscriberCityStateZipCode_2010BA.N402_BillingProviderStateOrProvinceCode;
                ucRecipientInformationPanel.ZipCode = si.SubscriberCityStateZipCode_2010BA == null ? "" : si.SubscriberCityStateZipCode_2010BA.N403_BillingProviderPostalZoneOrZipCode;
                log.CreateLogEntry(string.Format("{0} {1}", "Binding SetRecipientInfoDental in RecipientInfoDental panel for cliam id: ", hdnClaimId.Value.ToString()), Logging.LogPriority.Information);

            }
        }
    }

