    private void SetRecipientInfoDental(Dental.InquireClaimResponse inquireDentalClaimReponse)
    {
        ThreadId = Guid.NewGuid();
        Logging log = new Logging(ThreadId, "Dental XML Data reload form Inquire service for Recipient Dental panel");
        log.CreateLogEntry(string.Format("{0} {1}", "Calling   SetRecipientInfoDental  method form Inquire service for cliam id: ", hdnClaimId.Value.ToString()), Logging.LogPriority.Information);

        var si = inquireDentalClaimReponse.DentalClaim837.BHTContainter.SubscriberDetails_2000B.SubscriberInfo_2010BA;
        var cd = inquireDentalClaimReponse.DentalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300[0];
        if (si != null)
        {
            ucRecipientInformationPanel.MedicaidBillingNumber = si.SubscriberName_2010BA.NM109_SubmitterIdentifier;
            log.CreateLogEntry(string.Format("{0} {1}", "Calling   MedicaidBillingNumber  data form Inquire service for cliam id: ", hdnClaimId.Value.ToString()), Logging.LogPriority.Information);
            ucRecipientInformationPanel.BirthDate = !string.IsNullOrEmpty(si.SubscriberDemographicInformation_2010BA.DMG02_SubscriberBirthDate.ToString()) ? DateTime.ParseExact(si.SubscriberDemographicInformation_2010BA.DMG02_SubscriberBirthDate, "yyyyMMdd", System.Globalization.CultureInfo.InvariantCulture).ToString("MM/dd/yyyy", System.Globalization.CultureInfo.InvariantCulture) : "";
            log.CreateLogEntry(string.Format("{0} {1}", "Calling   BirthDate  data form Inquire service for cliam id: ", hdnClaimId.Value.ToString()), Logging.LogPriority.Information);
            ucRecipientInformationPanel.LastName = si.SubscriberName_2010BA.NM103_SubmitterLastOrOrganizationName;
            log.CreateLogEntry(string.Format("{0} {1}", "Calling   LastName  data form Inquire service for cliam id: ", hdnClaimId.Value.ToString()), Logging.LogPriority.Information);
            ucRecipientInformationPanel.FirstName = si.SubscriberName_2010BA.NM104_SubmitterFirstName;
            ucRecipientInformationPanel.MiddleName = si.SubscriberName_2010BA.NM105_SubmitterMiddleName;
            var gender = si.SubscriberDemographicInformation_2010BA.DMG03_SubscriberGenderCode;
            if (gender == "M")
                ucRecipientInformationPanel.Gender = "Male";
            else if (gender == "F")
                ucRecipientInformationPanel.Gender = "Female";
            else
                ucRecipientInformationPanel.Gender = "Other";
            if (si.SubscriberAddress_2010BA != null)
            {
                ucRecipientInformationPanel.AddressLine = si.SubscriberAddress_2010BA.N301_BillingProviderAddressLine;
                ucRecipientInformationPanel.AddressLine2 = si.SubscriberAddress_2010BA.N302_BillingProviderAddressLine;
            }
            if (si.SubscriberAddress_2010BA != null)
            {
                ucRecipientInformationPanel.City = si.SubscriberCityStateZipCode_2010BA.N401_BillingProviderCityName;
                ucRecipientInformationPanel.State = si.SubscriberCityStateZipCode_2010BA.N402_BillingProviderStateOrProvinceCode;
                ucRecipientInformationPanel.ZipCode = si.SubscriberCityStateZipCode_2010BA.N403_BillingProviderPostalZoneOrZipCode;
            }
            log.CreateLogEntry(string.Format("{0} {1}", "Loaded SetRecipientInfoDental  data form Inquire service for cliam id: ", hdnClaimId.Value.ToString()), Logging.LogPriority.Information);
        }
        if (cd != null)
        {
            ucRecipientInformationPanel.PatientControlNumber = cd.ClaimInformation_2300.CLM01_PatientControlNumber;

        }
    }
