    private void SetOtherPayerInfoDental(Dental.AddUpdateClaimsResponse dentalClaimReponse)
    {
        //--populate grid for Other Payers
        if (!string.IsNullOrEmpty(ddlDestinationPayerResponsibilitySequence.SelectedValue))
        {
            ucOtherPayerInformation.ClearData(ddlDestinationPayerResponsibilitySequence.SelectedValue);
        }
        DataTable dtop = GetOtherPayerInfoDT();
        int i = 1;
        foreach (Dental.ClaimDetails_2300Type cd in dentalClaimReponse.DentalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300)
        {
            if (cd.OtherPayer_2320 != null)
            {
                string hederType = null;
                foreach (Dental.ServiceLineDetails_2400Type sld in cd.ServiceLineDetails_2400)
                {
                    if (sld.LineAdjudicationDetails_2430 != null)
                    {
                        hederType = "Detail";
                        break;
                    }
                }
                foreach (Dental.OtherPayer_2320Type op in cd.OtherPayer_2320)
                {
                    if (op.OtherSubscriberInformation_2320 != null)
                    {
                        foreach (Dental.SBRType ost in op.OtherSubscriberInformation_2320)
                        {
                            dtop.Rows.Add(i.ToString(), op.PayerInfo_2330B.OtherPayerName_2330B.NM103_SubmitterLastOrOrganizationName,
                                op.PayerInfo_2330B.OtherPayerName_2330B.NM109_SubmitterIdentifier,
                                op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM103_SubmitterLastOrOrganizationName,
                                op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM104_SubmitterFirstName,
                                GetPayerResponsibility(ost.SBR01_PayerResponsibilitySequenceNumberCode),
                                         string.IsNullOrEmpty(hederType) ? "Header" : hederType
                               );
                            i++;
                        }
                    }
                }
            }
        }
        ViewState["otherPayerInformationDataTable"] = dtop;
        DataSet dsop = new DataSet();
        dsop.Tables.Add(dtop);
        ucOtherPayerInformation.dataSetOtherPayer = dsop;
        ucOtherPayerInformation.SubscribersState();
    }
    private void SetOtherPayerInfoDental(Dental.InquireClaimResponse inquireDentalClaimReponse)
    {
        //--populate grid for Other Payers
        if (!string.IsNullOrEmpty(ddlDestinationPayerResponsibilitySequence.SelectedValue))
        {
            ucOtherPayerInformation.ClearData(ddlDestinationPayerResponsibilitySequence.SelectedValue);
        }
        DataTable dtop = GetOtherPayerInfoDT();
        int i = 1;
        foreach (Dental.ClaimDetails_2300Type cd in inquireDentalClaimReponse.DentalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300)
        {

            if (cd.OtherPayer_2320 != null)
            {
                //string hederType = null;
                //foreach (Dental.ServiceLineDetails_2400Type sld in cd.ServiceLineDetails_2400)
                //{
                //    if (sld.LineAdjudicationDetails_2430 != null)
                //    {
                //        hederType = "Detail";
                //        break;
                //    }
                //}
                foreach (Dental.OtherPayer_2320Type op in cd.OtherPayer_2320)
                {
                    var ost = op.OtherSubscriberInformation_2320[0];//Per Dipendra 6086 use the first one from the list
                    if (op.ClaimLevelAdjustments_2320 != null && op.ClaimLevelAdjustments_2320.Length > 0)//CAS exist, then its a Header
                    {
                        dtop.Rows.Add(i.ToString(), op.PayerInfo_2330B.OtherPayerName_2330B.NM103_SubmitterLastOrOrganizationName,
                            op.PayerInfo_2330B.OtherPayerName_2330B.NM109_SubmitterIdentifier,
                            op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM103_SubmitterLastOrOrganizationName,
                            op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM104_SubmitterFirstName,
                            GetPayerResponsibility(ost.SBR01_PayerResponsibilitySequenceNumberCode),
                            "Header", op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM105_SubmitterMiddleName, ost.SBR09_ClaimFilingIndicatorCode, op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM109_SubmitterIdentifier,
                            ost.SBR03_SubscriberGroupOrPolicyNumber, ost.SBR04_SubscriberGroupName, ost.SBR05_InsuranceTypeCode, ost.SBR02_IndividualRelationshipCode,
                        op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A.N301_BillingProviderAddressLine,
                        op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A.N302_BillingProviderAddressLine, op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N401_BillingProviderCityName,
                        op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N402_BillingProviderStateOrProvinceCode,
                        op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N403_BillingProviderPostalZoneOrZipCode,
                        op.PayerInfo_2330B.OtherPayerClaimControlNumber_2330B == null ? "" : op.PayerInfo_2330B.OtherPayerClaimControlNumber_2330B.REF02_BillingProviderTaxIdentificationNumber,
                        op.PayerInfo_2330B.ClaimCheckOrRemittanceDate_2330B.DTP03_AccidentDate,
                        op.CobPayerPaidAmount_2320.AMT02_PatientAmountPaid, op.CobTotalNonCoveredAmount_2320 == null ? "" : op.CobTotalNonCoveredAmount_2320.AMT02_PatientAmountPaid, ost.SBR01_PayerResponsibilitySequenceNumberCode
                            );
                        i++;
                    }
                    else if (op.ClaimLevelAdjustments_2320 == null && cd.ServiceLineDetails_2400 != null && cd.ServiceLineDetails_2400.Length > 0)
                    {
                        var hasDetail = false;
                        foreach (Dental.ServiceLineDetails_2400Type sld in cd.ServiceLineDetails_2400)
                        {
                            if (sld.LineAdjudicationDetails_2430 != null)
                            {
                                foreach (Dental.LineAdjudicationDetails_2430Type lad in sld.LineAdjudicationDetails_2430)
                                {
                                    if (lad.LineAdjudicationInformation_2430.SVD01_OtherPayerPrimaryIdentifier == op.PayerInfo_2330B.OtherPayerName_2330B.NM109_SubmitterIdentifier)//we have a detail:)
                                    {
                                        hasDetail = true;
                                        break;
                                    }
                                }
                            }
                        }
                        if (hasDetail) //Its a Detail record
                        {
                            dtop.Rows.Add(i.ToString(), op.PayerInfo_2330B.OtherPayerName_2330B.NM103_SubmitterLastOrOrganizationName,
                                op.PayerInfo_2330B.OtherPayerName_2330B.NM109_SubmitterIdentifier,
                                op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM103_SubmitterLastOrOrganizationName,
                                op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM104_SubmitterFirstName,
                                GetPayerResponsibility(ost.SBR01_PayerResponsibilitySequenceNumberCode),
                                string.IsNullOrEmpty(ost.SBR01_PayerResponsibilitySequenceNumberCode) ? "" : "Detail", op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM105_SubmitterMiddleName,
                                ost.SBR09_ClaimFilingIndicatorCode, op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM109_SubmitterIdentifier,
                                ost.SBR03_SubscriberGroupOrPolicyNumber, ost.SBR04_SubscriberGroupName, ost.SBR05_InsuranceTypeCode, ost.SBR02_IndividualRelationshipCode, op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A.N301_BillingProviderAddressLine,
                                op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A.N302_BillingProviderAddressLine, op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N401_BillingProviderCityName,
                                op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N402_BillingProviderStateOrProvinceCode,
                                op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N403_BillingProviderPostalZoneOrZipCode,
                                op.PayerInfo_2330B.OtherPayerClaimControlNumber_2330B == null ? "" : op.PayerInfo_2330B.OtherPayerClaimControlNumber_2330B.REF02_BillingProviderTaxIdentificationNumber, op.PayerInfo_2330B.ClaimCheckOrRemittanceDate_2330B == null ? "" : op.PayerInfo_2330B.ClaimCheckOrRemittanceDate_2330B.DTP03_AccidentDate,
                                op.CobPayerPaidAmount_2320 == null ? "" : op.CobPayerPaidAmount_2320.AMT02_PatientAmountPaid, op.CobTotalNonCoveredAmount_2320 == null ? "" : op.CobTotalNonCoveredAmount_2320.AMT02_PatientAmountPaid, ost.SBR01_PayerResponsibilitySequenceNumberCode == null ? "" : ost.SBR01_PayerResponsibilitySequenceNumberCode
                                );
                            i++;
                        }
                        else //Neither Header not Detail record
                        {
                            dtop.Rows.Add(i.ToString(), op.PayerInfo_2330B.OtherPayerName_2330B == null ? "" : op.PayerInfo_2330B.OtherPayerName_2330B.NM103_SubmitterLastOrOrganizationName,
                                    op.PayerInfo_2330B.OtherPayerName_2330B == null ? "" : op.PayerInfo_2330B.OtherPayerName_2330B.NM109_SubmitterIdentifier,
                                op.SubscriberInfo_2330A.OtherSubscriberName_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM103_SubmitterLastOrOrganizationName,
                                op.SubscriberInfo_2330A.OtherSubscriberName_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM104_SubmitterFirstName,
                                GetPayerResponsibility(ost.SBR01_PayerResponsibilitySequenceNumberCode),
                                "",
                                op.SubscriberInfo_2330A.OtherSubscriberName_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM105_SubmitterMiddleName
                                , ost.SBR09_ClaimFilingIndicatorCode,
                                op.SubscriberInfo_2330A.OtherSubscriberName_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM109_SubmitterIdentifier,
                                ost.SBR03_SubscriberGroupOrPolicyNumber, ost.SBR04_SubscriberGroupName, ost.SBR05_InsuranceTypeCode, ost.SBR02_IndividualRelationshipCode,
                                op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A.N301_BillingProviderAddressLine,
                                op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A.N302_BillingProviderAddressLine,
                                op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N401_BillingProviderCityName,
                                op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N402_BillingProviderStateOrProvinceCode,
                                op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N403_BillingProviderPostalZoneOrZipCode,
                                op.PayerInfo_2330B.OtherPayerClaimControlNumber_2330B == null ? "" : op.PayerInfo_2330B.OtherPayerClaimControlNumber_2330B.REF02_BillingProviderTaxIdentificationNumber,
                                op.PayerInfo_2330B.ClaimCheckOrRemittanceDate_2330B == null ? "" : op.PayerInfo_2330B.ClaimCheckOrRemittanceDate_2330B.DTP03_AccidentDate,
                                op.CobPayerPaidAmount_2320 == null ? "" : op.CobPayerPaidAmount_2320.AMT02_PatientAmountPaid,
                                op.CobTotalNonCoveredAmount_2320 == null ? "" : op.CobTotalNonCoveredAmount_2320.AMT02_PatientAmountPaid,
                                ost.SBR01_PayerResponsibilitySequenceNumberCode == null ? "" : ost.SBR01_PayerResponsibilitySequenceNumberCode
                                );
                            i++;
                        }
                    }
                }
            }
        }
        ViewState["otherPayerInformationDataTable"] = dtop;
        DataSet dsop = new DataSet();
        dsop.Tables.Add(dtop);
        ucOtherPayerInformation.FromInquirySvc = true;
        ucOtherPayerInformation.dataSetOtherPayer = dsop;
