    private void SetDiagnosisClaimsInfoDental(DataSet dentalClaimsData)
    {
        if (dentalClaimsData.Tables[13].Rows.Count > 0)
        {
            DataTable dtd = GetDiagnosisInfoDT();
            int i = 1;
            foreach (DataRow dr in dentalClaimsData.Tables[13].Rows)
            {
                string PresentOnAdmission = "";
                if (dr["Present_On_Admission"].ToString().Equals("W"))
                {
                    PresentOnAdmission = "Not Applicable";
                }
                else if (dr["Present_On_Admission"].ToString().Equals("N"))
                {
                    PresentOnAdmission = "No";
                }
                else if (dr["Present_On_Admission"].ToString().Equals("Y"))
                {
                    PresentOnAdmission = "Yes";
                }
                else if (dr["Present_On_Admission"].ToString().Equals("U"))
                {
                    PresentOnAdmission = "Unknown";
                }
                else
                {
                    PresentOnAdmission = dr["Present_On_Admission"].ToString();
                }
                dtd.Rows.Add(dr["Claims_Diagnosis_Information_ID"] != null ? dr["Claims_Diagnosis_Information_ID"].ToString() : "", i, i.ToString(), dr["diag_code"] != null ? dr["diag_code"].ToString() : "",
                        dr["ICDVersion"] != null ? dr["ICDVersion"].ToString() : "", dr["Present_On_Admission"] != null ? PresentOnAdmission : "",
                        dr["diagnosisDescription"] != null ? dr["diagnosisDescription"].ToString() : "");
                i++;

            }
            DataSet dsd = new DataSet();
            dsd.Tables.Add(dtd);
            ucDiagnosisCodePanel.dataSetDiagnosisCode = dsd;
        }
    }
