                                sld.DentalService_2400.SV311_4_DiagnosisCodePointer,//DiagnosisPointer(4)
                                sld.DentalService_2400.SV304_1_OralCavityDesignationCode,//OralCavity(1)
                                sld.DentalService_2400.SV304_2_OralCavityDesignationCode,//OralCavity(2)
