                                string.IsNullOrEmpty(inquireDentalClaimReponse.ClaimLinesResponse[i - 1].LineStatus) ? "" : inquireDentalClaimReponse.ClaimLinesResponse[i - 1].LineStatus,
                                sld.DentalService_2400.SV302_LineItemChargeAmount,//Charges
