                                string.IsNullOrEmpty(inquireDentalClaimReponse.ClaimLinesResponse[i - 1].PaidServiceUnit) ? "" : inquireDentalClaimReponse.ClaimLinesResponse[i - 1].PaidServiceUnit,
                                string.IsNullOrEmpty(inquireDentalClaimReponse.ClaimLinesResponse[i - 1].PaidAmount) ? "" : inquireDentalClaimReponse.ClaimLinesResponse[i - 1].PaidAmount,
                                cd.ClaimInformation_2300.CLM02_TotalClaimChargeAmount,////TotalClaim
                                ""

                                );
                            totalChargesAmt = totalChargesAmt + (string.IsNullOrEmpty(sld.DentalService_2400.SV302_LineItemChargeAmount) ? 0 : Convert.ToDecimal(sld.DentalService_2400.SV302_LineItemChargeAmount));
                            if (inquireDentalClaimReponse.ClaimLinesResponse[i - 1] != null)
                                totalPaidAmt = totalPaidAmt + (string.IsNullOrEmpty(inquireDentalClaimReponse.ClaimLinesResponse[i - 1].PaidAmount) ? 0 : Convert.ToDecimal(inquireDentalClaimReponse.ClaimLinesResponse[i - 1].PaidAmount));
                            //ucServiceDetailsDental.SaveClaimsDentalServiceDetails(sld.ServiceLineNumber_2400.LX01_AssignedNumber, sld.DentalService_2400.SV301_2_ProcedureCode, sld.DentalService_2400.SV303_PlaceOfServiceCode,
