                            //     sld.DentalService_2400.SV304_4_OralCavityDesignationCode, sld.DentalService_2400.SV304_5_OralCavityDesignationCode, cd.ClaimInformation_2300.CLM02_TotalClaimChargeAmount, sld.DentalService_2400.SV306_ProcedureCount,
                            //    sld.ReferralNumber_2400 != null ? sld.ReferralNumber_2400[0].REF02_BillingProviderTaxIdentificationNumber : "",
