            Logging log = new Logging(ThreadId, "Dental XML Data reload for Claim search in SetServiceDetailInfoDental method");
            log.CreateLogEntry(string.Format("{0} {1}", "Dental Claim  claim search  reload XML data of Inquiry service  in SetServiceDetailInfoDental method for cliam id:",
                hdnClaimId.Value.ToString() + "and InquireDentalClaimReponse data" + inquireDentalClaimReponse.ToString() + "with error" + ex.Message.ToString()), Logging.LogPriority.Error);
            lblglobalerror.Text = "An error has occurred to display the claim response details,please inquire the claim again in some time.";


        }

    }
    private bool check(string inputString)
    {
        string[] formats = { "dd/MM/yyyy" };
        DateTime parsedDate;
        var isValidFormat = DateTime.TryParseExact(inputString, formats, new CultureInfo("en-US"), DateTimeStyles.None, out parsedDate);

        if (isValidFormat)
        {
            return true;
        }
        else
        {
            return false;
        }
    }
    private string DateOfService(Dental.InquireClaimResponse dentalClaimReponse)
    {
        string dateOfService = string.Empty;
        var cd = dentalClaimReponse.DentalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300[0];
        if (cd != null)
        {
            if (cd.DateServiceDate_2300.DTP03_AccidentDate != null && cd.DateServiceDate_2300.DTP02_DateTimePeriodFormatQualifier == "D8")
            {
                if (check(cd.DateServiceDate_2300.DTP03_AccidentDate))
                {
                    dateOfService = cd.DateServiceDate_2300.DTP03_AccidentDate;
                }
                else
                {
                    dateOfService = Convert.ToDateTime(cd.DateServiceDate_2300.DTP03_AccidentDate).ToString("MM/dd/yyyy");
                }
            }
        }
        return dateOfService;

    }
    private string DateOfServiceDetails(string DateofService)
    {

        if (DateofService != null)
        {
            if (!check(DateofService))
            {
                if (DateofService.Contains("-"))
                {
                    DateofService = DateofService.Split('-')[0];
                }
                DateofService =
                DateTime.ParseExact(DateofService, "yyyyMMdd", System.Globalization.CultureInfo.InvariantCulture).ToString("MM/dd/yyyy", System.Globalization.CultureInfo.InvariantCulture);
            }
        }
        return DateofService;

    }
    private string DateOfServiceAdd(Dental.AddUpdateClaimsResponse dentalClaimReponse)
    {
        string dateOfService = string.Empty;
        var cd = dentalClaimReponse.DentalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300[0];
