                if (sld.RenderingProviderDetails_2420A != null)
                {
                    var rpn = sld.RenderingProviderDetails_2420A.RenderingProviderName_2420A;
                    if (!string.IsNullOrEmpty(rpn.NM101_EntityIdentifierCode))
                    {
                        dtap.Rows.Add(i, (sld.ServiceLineNumber_2400.LX01_AssignedNumber.Length == 1 ? sld.ServiceLineNumber_2400.LX01_AssignedNumber : sld.ServiceLineNumber_2400.LX01_AssignedNumber),
