        foreach (Dental.ClaimDetails_2300Type cd in inquireDentalClaimReponse.DentalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300)
        {
            foreach (Dental.ServiceLineDetails_2400Type sld in cd.ServiceLineDetails_2400)
            {
