                        dtap.Rows.Add(i, (sld.ServiceLineNumber_2400.LX01_AssignedNumber.Length == 1 ? sld.ServiceLineNumber_2400.LX01_AssignedNumber : sld.ServiceLineNumber_2400.LX01_AssignedNumber),
                            "Supervising Provider",
                            spn.NM109_SubmitterIdentifier,
                            "",
                            spn.NM103_SubmitterLastOrOrganizationName,
                            spn.NM104_SubmitterFirstName,
                            spn.NM105_SubmitterMiddleName);
                        i++;
                    }
                }
            }
        }
        //Load Service Facility details
        foreach (Dental.ClaimDetails_2300Type cd in inquireDentalClaimReponse.DentalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300)
        {
            foreach (Dental.ServiceLineDetails_2400Type sld in cd.ServiceLineDetails_2400)
