    private void SetCARCandRARCInfoDental(Dental.AddUpdateClaimsResponse dentalClaimReponse)
    {
        try
        {
            DataTable dtcr = GetCARCAndRARCInfoDT();
            DataTable dtcrLine = GetCARCAndRARCInfoDTForLines();
            int i = 1;
            if (dentalClaimReponse.ClaimHeaderResponse.ListOfCARC != null)
            {
                //Load CARC Header Details
                foreach (Dental.CARCType ct in dentalClaimReponse.ClaimHeaderResponse.ListOfCARC)
                {
                    dtcr.Rows.Add("0", ct.CARCCode, ct.CARCAmount, ct.CARCDescription, "", "");
                    i++;
                }
            }
            int j = 0;
            if (dentalClaimReponse.ClaimHeaderResponse.ListOfRARC != null)
            {
                //Load RARC Header Details
                foreach (Dental.RARCType rt in dentalClaimReponse.ClaimHeaderResponse.ListOfRARC)
                {
                    if (j < i - 1)
                    {
                        dtcr.Rows[j]["RARC_NO"] = rt.RARCCode;
                        dtcr.Rows[j]["RARC_DESCRIPTION"] = rt.RARCDescription;
                    }
                    else
                    {
                        dtcr.Rows.Add("0", "", "", "", rt.RARCCode, rt.RARCDescription);
                    }
                    j++;
                }
            }
            if (dentalClaimReponse.ClaimLinesResponse != null)
            {
                i = 1;
                //Load CARC Line Details            
                foreach (Dental.ClaimLineDetailsType ct in dentalClaimReponse.ClaimLinesResponse)
                {
                    if (ct.ListOfCARC != null)
                    {
                        foreach (Dental.CARCType cp in ct.ListOfCARC)
                        {
                            dtcrLine.Rows.Add(i.ToString(), cp.CARCCode, cp.CARCAmount, cp.CARCDescription, "", "");
                            i++;
                        }
                    }
                }

            }

            if (dentalClaimReponse.ClaimLinesResponse != null)
            {
                j = 0;
                //Load RARC Line Details
                foreach (Dental.ClaimLineDetailsType rt in dentalClaimReponse.ClaimLinesResponse)
                {

                    if (rt.ListOfRARC != null)
                    {
                        foreach (Dental.RARCType rp in rt.ListOfRARC)
                        {
                            if (j < i - 1)
                            {
                                dtcrLine.Rows[j]["RARC_NO"] = rp.RARCCode;
                                dtcrLine.Rows[j]["RARC_DESCRIPTION"] = rp.RARCDescription;
                            }
                            else
                            {
                                dtcrLine.Rows.Add((j + 1).ToString(), "", "", "", rp.RARCCode, rp.RARCDescription);
                            }
                            j++;
                        }
                    }
                }
            }
            dtcr.Merge(dtcrLine);

            CARCRARCInformation.ds = dtcr;

        }
        catch (Exception ex)
        {
            ThreadId = Guid.NewGuid();
            Logging log = new Logging(ThreadId, "Dental Claim Inquiry XML Data reload after submit button");
            log.CreateLogEntry(string.Format("{0} {1}", "Dental Claim Inquiry Submit button reload XML data for CARC and RAC Information panel of  claim Id:",
            hdnClaimId.Value.ToString() + "and response data" + dentalClaimReponse.ToString() + "with error" + ex.Message.ToString()), Logging.LogPriority.Information);
        }
    }
