        //Select Destination payer
        if (addUpdateProClaimReponse.ProfessionalClaim837 != null && addUpdateProClaimReponse.ProfessionalClaim837.BHTContainter != null)
        {
            var sd = addUpdateProClaimReponse.ProfessionalClaim837.BHTContainter.SubscriberDetails_2000B;

            if (sd != null)
            {
                var dp = sd.PayerInfo_2010BB.PayerName_2010BB.NM103_SubmitterLastOrOrganizationName;
                if (!string.IsNullOrEmpty(dp) && ddlPrimaryDestinationPayer.Items.FindByText(dp) != null)
                {
                    ddlPrimaryDestinationPayer.ClearSelection();
                    ddlPrimaryDestinationPayer.Items.FindByText(dp).Selected = true;
                }
                var dprs = sd.SubscriberInformation_2000B.SBR01_PayerResponsibilitySequenceNumberCode;
                if (!string.IsNullOrEmpty(dprs))
                {
                    ddlDestinationPayerResponsibilitySequence.ClearSelection();
                    //ddlDestinationPayerResponsibilitySequence.SelectedValue = dprs;
                    if (_spa == null)
                    {
                        _spa = new PDMSService.PDMSServiceClient();
                    }
                    DataSet dataSetPayerSequence = _spa.GetPayerSequence();
                    DataTable selectedTable = new DataTable();
                    if (Helper.HasRows(dataSetPayerSequence))
                    {
                        DataTable dt = new DataTable();
                        dt = dataSetPayerSequence.Tables[0];
                        selectedTable = dt.AsEnumerable()
                                                .Where(r => r.Field<string>("PRIOR_AUTH_SUBMIT_CLAIM_PAYERSEQUENCE_CODE") == dprs)
                                                .CopyToDataTable();
                        if (selectedTable.Rows.Count > 0)
                        {
                            ddlDestinationPayerResponsibilitySequence.Items.FindByText(selectedTable.Rows[0]["PRIOR_AUTH_SUBMIT_CLAIM_PAYERSEQUENCE_DESC"].ToString()).Selected = true;
                        }
                    }
                }
            }
        }
