        {
            string PayerId = addUpdateProClaimReponse.ProfessionalClaim837.FunctionalGroupHeader.GS03_ApplicationReceiversCode;
            if (!string.IsNullOrEmpty(PayerId))
            {
                ddlDestinationPayerID.ClearSelection();
                LoadDestinatinationPayerID();
                ddlDestinationPayerID.Items.FindByValue(PayerId).Selected = true;
            }
        }
        #region OHPNM-9153
        if (!string.IsNullOrEmpty(txtICN2.Text))
        {
            string medicaid = "";
            string npi = "";
            Dictionary<string, string> parms = new Dictionary<string, string>();
            parms = new Dictionary<string, string>();
            DataSet ds = LoadProviderInformation(this.WorkflowPage.MedicaidID);
            if (Helper.HasRows(ds))
            {

                medicaid = Helper.GetString("MEDICAID_ID", ds.Tables[0].Rows[0]);
                npi = Helper.GetString("NPI", ds.Tables[0].Rows[0]);
            }
            string claimid = ClaimsController.GetClaimID(medicaid, npi, rblClaimType.SelectedValue.ToString(), txtICN2.Text);
            if (!string.IsNullOrEmpty(claimid))
            {
                hdnClaimId.Value = claimid;
            }
            else
            {
                SaveAdjudicationSummaryData();
            }
        }
