    private void SetRecipientInfoProfessional(Professional.AddUpdateClaimsResponse addUpdateClaimsResponse)
    {
        if (addUpdateClaimsResponse.ProfessionalClaim837 != null && addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter != null)
        {
            if (addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter.SubscriberDetails_2000B != null)
            {
                var si = addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter.SubscriberDetails_2000B.SubscriberInfo_2010BA;
                var cd = addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300[0];
                ucRecipientInformationPanel.MedicaidBillingNumber = si.SubscriberName_2010BA.NM109_SubmitterIdentifier;
                //ucRecipientInformationPanel.BirthDate = si.SubscriberDemographicInformation_2010BA.DMG02_SubscriberBirthDate;
                ucRecipientInformationPanel.BirthDate = !string.IsNullOrEmpty(si.SubscriberDemographicInformation_2010BA.DMG02_SubscriberBirthDate.ToString()) ? DateTime.ParseExact(si.SubscriberDemographicInformation_2010BA.DMG02_SubscriberBirthDate, "yyyyMMdd", System.Globalization.CultureInfo.InvariantCulture).ToString("MM/dd/yyyy", System.Globalization.CultureInfo.InvariantCulture) : "";

                var gender = si.SubscriberDemographicInformation_2010BA.DMG03_SubscriberGenderCode;
                if (gender == "M")
                    ucRecipientInformationPanel.Gender = "Male";
                else if (gender == "F")
                    ucRecipientInformationPanel.Gender = "Female";
                else
                    ucRecipientInformationPanel.Gender = "Other";
                ucRecipientInformationPanel.PatientControlNumber = cd.ClaimInformation_2300.CLM01_PatientControlNumber;
                if (si.SubscriberName_2010BA != null)
                {
                    ucRecipientInformationPanel.LastName = si.SubscriberName_2010BA.NM103_SubmitterLastOrOrganizationName;
                    ucRecipientInformationPanel.FirstName = si.SubscriberName_2010BA.NM104_SubmitterFirstName;
                    ucRecipientInformationPanel.MiddleName = si.SubscriberName_2010BA.NM105_SubmitterMiddleNameOrInitial;
                }
                if (cd.MedicalRecordNumber_2300 != null)
                {
                    ucRecipientInformationPanel.MedicalRecordNumber = cd.MedicalRecordNumber_2300.REF02_BillingProviderTaxIdentificationNumber;
                }
                //ucRecipientInformationPanel.PregnancyIndicatorValue = inquireProClaimReponse.ProfessionalClaim837.BHTContainter.SubscriberDetails_2000B.PatientInformation_2000B.PAT09_PregancyIndicator;
                if (si.SubscriberAddress_2010BA != null)
