    private void SetReferringProviderInfoProfessional(Professional.AddUpdateClaimsResponse addUpdateClaimsResponse)
    {
        try
        {
            //Load Referring / Primary based on the Qualifier
            if (addUpdateClaimsResponse.ProfessionalClaim837 != null)
            {
                if (addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter != null)
                {
                    if (addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter.PatientHierarchical_2000C != null)
                    {
                        if (addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300[0].ReferingProviderDetails_2310A != null)
                        {
                            foreach (Professional.ReferingProviderDetails_2310AType rpd in addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300[0].ReferingProviderDetails_2310A)
                            {
                                if (rpd.ReferringProviderName_2310A.NM101_EntityIdentifierCode == "DN")
                                {
                                    ucReferringProvider.ReferringProviderNPI = rpd.ReferringProviderName_2310A.NM109_SubmitterIdentifier;
                                    if (String.IsNullOrEmpty(ucReferringProvider.ReferringProviderNPI))
                                        ucReferringProvider.ReferringProvider_MedicaidID = lookupProviderMedicaidID(rpd.ReferringProviderName_2310A.NM109_SubmitterIdentifier, rpd.ReferringProviderName_2310A.NM103_SubmitterLastOrOrganizationName, rpd.ReferringProviderName_2310A.NM104_SubmitterFirstName);
                                    ucReferringProvider.ReferringProvider_LastName = rpd.ReferringProviderName_2310A.NM103_SubmitterLastOrOrganizationName;
                                    ucReferringProvider.ReferringProvider_FirstName = rpd.ReferringProviderName_2310A.NM104_SubmitterFirstName;
                                }
                                else if (rpd.ReferringProviderName_2310A.NM101_EntityIdentifierCode == "P3")
                                {
