                    if (apup != null)
                    {
                        if (apup.AmbulancePickUpLocationAddress_2310E != null)
                        {
                            ucAmbulanceInformation.AmbulanceInformationPickUpAddressLine1 = apup.AmbulancePickUpLocationAddress_2310E.N301_BillingProviderAddressLine;
                            ucAmbulanceInformation.AmbulanceInformationPickUpAddressLine2 = apup.AmbulancePickUpLocationAddress_2310E.N302_BillingProviderAddressLine;
                        }
                        if (apup.AmbulancePickUpLocationCityStateZipCode_2310E != null)
                        {
                            ucAmbulanceInformation.AmbulanceInformationPickUpCity = apup.AmbulancePickUpLocationCityStateZipCode_2310E.N401_BillingProviderCityName;
                            ucAmbulanceInformation.AmbulanceInformationPickUpState = apup.AmbulancePickUpLocationCityStateZipCode_2310E.N402_BillingProviderStateOrProvinceCode;
                            ucAmbulanceInformation.AmbulanceInformationPickUpZip = apup.AmbulancePickUpLocationCityStateZipCode_2310E.N403_BillingProviderPostalZoneOrZipCode;
                        }
                    }
                }

                //Dropoff info
                var adod = cd.AmbulanceDropOffDetails_2310F;
                if (adod != null)
                {
                    if (adod.AmbulanceDropOffLocation_2310F != null)
                        ucAmbulanceInformation.AmbulanceInformationDropOffLocationName = adod.AmbulanceDropOffLocation_2310F.NM103_SubmitterLastOrOrganizationName;
                    if (adod.AmbulanceDropOffLocationAddress_2310F != null)
                    {
                        ucAmbulanceInformation.AmbulanceInformationDropOffAddress1 = adod.AmbulanceDropOffLocationAddress_2310F.N301_BillingProviderAddressLine;
                        ucAmbulanceInformation.AmbulanceInformationDropOffAddress2 = adod.AmbulanceDropOffLocationAddress_2310F.N302_BillingProviderAddressLine;
                    }
                    if (adod.AmbulanceDropOffLocationCityStateZipCode_2310F != null)
                    {
                        ucAmbulanceInformation.AmbulanceInformationDropOffCity = adod.AmbulanceDropOffLocationCityStateZipCode_2310F.N401_BillingProviderCityName;
                        ucAmbulanceInformation.AmbulanceInformationDropOffState = adod.AmbulanceDropOffLocationCityStateZipCode_2310F.N402_BillingProviderStateOrProvinceCode;
                        ucAmbulanceInformation.AmbulanceInformationDropOffZip = adod.AmbulanceDropOffLocationCityStateZipCode_2310F.N403_BillingProviderPostalZoneOrZipCode;
                    }

                }

                //Transport info
                var ati = cd.AmbulanceTransportInformation_2300;
                if (ati != null)
                {
                    if (ati.CR102_PatientWeight != null)
                    {
                        ucAmbulanceInformation.AmbulanceInformationPatientWeight = ati.CR102_PatientWeight;
                    }
                    if (ati.CR104_AmbulanceTransportReasonCode != null)
                    {
                        ucAmbulanceInformation.AmbulanceInformationTransportationReasonCode = ati.CR104_AmbulanceTransportReasonCode;
                    }
                    if (ati.CR106_TransportDistance != null)
                    {
                        ucAmbulanceInformation.AmbulanceInformationTransportationDistance = ati.CR106_TransportDistance;
                    }
                    if (ati.CR109_RoundTripPurposeDescription != null)
                    {
                        ucAmbulanceInformation.AmbulanceInformationRoundTripPurpose = ati.CR109_RoundTripPurposeDescription;
                    }
                    if (ati.CR110_StretcherPurposeDescription != null)
                    {
                        ucAmbulanceInformation.AmbulanceInformationStretecherPurpose = ati.CR110_StretcherPurposeDescription;
                    }
                }
                var test = cd.AmbulanceCertification_2300;
                if (test != null)
                {
                    var act = cd.AmbulanceCertification_2300[0];
                    ucAmbulanceInformation.AmbulanceInformationConditionIndicator = act.CRC02_CertificationConditionIndicator == "Y" ? "1" : "0";
                    ucAmbulanceInformation.AmbulanceInformationConditionCode1 = act.CRC03_ConditionCode;
                    ucAmbulanceInformation.AmbulanceInformationConditionCode2 = act.CRC04_ConditionCode;
                    ucAmbulanceInformation.AmbulanceInformationConditionCode3 = act.CRC05_ConditionCode;
                    ucAmbulanceInformation.AmbulanceInformationConditionCode4 = act.CRC06_ConditionCode;
                    ucAmbulanceInformation.AmbulanceInformationConditionCode5 = act.CRC07_ConditionCode;
                }
            }
        }

        catch (Exception ex)
        {
            ThreadId = Guid.NewGuid();
            Logging log = new Logging(ThreadId, "Professional Claim XML Data reload after submit button for Ambulance panel  data");
            log.CreateLogEntry(string.Format("{0} {1}", "Professional Claim  Submit button reload XML data for Related ICN Information for claim Id:",
                hdnClaimId.Value.ToString() + "and response data" + addUpdateClaimsResponse.ToString() + "with error" + ex.Message.ToString()), Logging.LogPriority.Information);
        }
    }

