    private void SetOtherPayerInfoProfessional(Professional.AddUpdateClaimsResponse addUpdateClaimsResponse)
    {
        try
        {
            //--populate grid for Other Payers
            if (!string.IsNullOrEmpty(ddlDestinationPayerResponsibilitySequence.SelectedValue))
            {
                ucOtherPayerInformation.ClearData(ddlDestinationPayerResponsibilitySequence.SelectedValue);
            }
            DataTable dtop = GetOtherPayerInfoDT();
            int i = 1;
            if (addUpdateClaimsResponse.ProfessionalClaim837 != null && addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter != null &&
                addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter.PatientHierarchical_2000C != null &&
                addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300 != null)
            {
                foreach (Professional.ClaimDetails_2300Type cd in addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300)
                {
                    if (cd != null)
                    {
                        if (cd.OtherPayer_2320 != null)
                        {
                            string hederType = null;
                            foreach (Professional.ServiceLineDetails_2400Type sld in cd.ServiceLineDetails_2400)
                            {
                                if (sld.LineAdjudicationDetails_2430 != null)
                                {
                                    hederType = "Detail";
                                    break;
                                }
                            }
                            foreach (Professional.OtherPayer_2320Type op in cd.OtherPayer_2320)
                            {
                                dtop.Rows.Add(i.ToString(), op.PayerInfo_2330B.OtherPayerName_2330B.NM103_SubmitterLastOrOrganizationName,
                                    op.PayerInfo_2330B.OtherPayerName_2330B.NM109_SubmitterIdentifier,
                                    op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM103_SubmitterLastOrOrganizationName,
                                    op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM104_SubmitterFirstName,
                                    GetPayerResponsibility(op.OtherSubscriberInformation_2320.SBR01_PayerResponsibilitySequenceNumberCode),
                                    string.IsNullOrEmpty(hederType) ? "Header" : hederType);
                                i++;
                            }
                        }
                    }
                }
                ViewState["OtherPayerInformationProfessional"] = dtop;
                DataSet dsop = new DataSet();
                dsop.Tables.Add(dtop);
                ucOtherPayerInformation.dataSetOtherPayer = dsop;
            }
            ucOtherPayerInformation.SubscribersState();

        }

        catch (Exception ex)
        {
            ThreadId = Guid.NewGuid();
            Logging log = new Logging(ThreadId, "Professional Claim XML Data reload after submit button for OtherPayer panel  data");
            log.CreateLogEntry(string.Format("{0} {1}", "Professional Claim  Submit button reload XML data for Related ICN Information for claim Id:",
                hdnClaimId.Value.ToString() + "and response data" + addUpdateClaimsResponse.ToString() + "with error" + ex.Message.ToString()), Logging.LogPriority.Information);
        }
    }

    private void SetOtherPayerInfoProfessional(Professional.InquireClaimResponse inquireProClaimReponse)
    {
        try
        {
            //--populate grid for Other Payers
            if (!string.IsNullOrEmpty(ddlDestinationPayerResponsibilitySequence.SelectedValue))
            {
                ucOtherPayerInformation.ClearData(ddlDestinationPayerResponsibilitySequence.SelectedValue);
            }
            DataTable dtop = GetOtherPayerInfoDT();
            int i = 1;

            if (inquireProClaimReponse.ProfessionalClaim837 != null && inquireProClaimReponse.ProfessionalClaim837.BHTContainter != null &&
                inquireProClaimReponse.ProfessionalClaim837.BHTContainter.PatientHierarchical_2000C != null &&
                inquireProClaimReponse.ProfessionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300 != null)
            {

                foreach (Professional.ClaimDetails_2300Type cd in inquireProClaimReponse.ProfessionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300)
                {
                    if (cd.OtherPayer_2320 != null)
                    {
                        //string hederType = null;
                        //foreach (Professional.ServiceLineDetails_2400Type sld in cd.ServiceLineDetails_2400)
                        //{
                        //    if (sld.LineAdjudicationDetails_2430 != null)
                        //    {
                        //        hederType = "Detail";
                        //        break;
                        //    }
                        //}
                        foreach (Professional.OtherPayer_2320Type op in cd.OtherPayer_2320)
                        {
                            var ost = op.OtherSubscriberInformation_2320;//Per Dipendra 6086 use the first one from the list
                            if (op.ClaimLevelAdjustments_2320 != null && op.ClaimLevelAdjustments_2320.Length > 0)//CAS exist, then its a Header
                            {
                                dtop.Rows.Add(i.ToString(), op.PayerInfo_2330B.OtherPayerName_2330B.NM103_SubmitterLastOrOrganizationName,
                                    op.PayerInfo_2330B.OtherPayerName_2330B.NM109_SubmitterIdentifier,
                                    op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM103_SubmitterLastOrOrganizationName,
                                    op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM104_SubmitterFirstName,
                                    GetPayerResponsibility(ost.SBR01_PayerResponsibilitySequenceNumberCode),
                                    "Header", op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM105_SubmitterMiddleNameOrInitial, ost.SBR09_ClaimFilingIndicatorCode, op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM109_SubmitterIdentifier,
                                    ost.SBR03_SubscriberGroupOrPolicyNumber, ost.SBR04_SubscriberGroupName, ost.SBR05_InsuranceTypeCode, ost.SBR02_IndividualRelationshipCode,
                                op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A.N301_BillingProviderAddressLine,
                                op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A.N302_BillingProviderAddressLine, op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N401_BillingProviderCityName,
                                op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N402_BillingProviderStateOrProvinceCode,
                                op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N403_BillingProviderPostalZoneOrZipCode,
                                op.PayerInfo_2330B.OtherPayerClaimControlNumber_2330B == null ? "" : op.PayerInfo_2330B.OtherPayerClaimControlNumber_2330B.REF02_BillingProviderTaxIdentificationNumber,
                                op.PayerInfo_2330B.ClaimCheckOrRemittanceDate_2330B.DTP03_OnsetOfCurrentIllnessOrInjuryDate,
                                op.CoordinationOfBenefitsCobPayerPaidAmount_2320.AMT02_PatientAmountPaid, op.CoordinationOfBenefitsCobPayerPaidAmount_2320 == null ? "" : op.CoordinationOfBenefitsCobPayerPaidAmount_2320.AMT02_PatientAmountPaid, ost.SBR01_PayerResponsibilitySequenceNumberCode
                                    );
                                i++;
                            }
                            else if (op.ClaimLevelAdjustments_2320 == null && cd.ServiceLineDetails_2400 != null && cd.ServiceLineDetails_2400.Length > 0)
                            {
                                var hasDetail = false;
                                foreach (Professional.ServiceLineDetails_2400Type sld in cd.ServiceLineDetails_2400)
                                {
                                    if (sld.LineAdjudicationDetails_2430 != null)
                                    {
                                        foreach (Professional.LineAdjudicationDetails_2430Type lad in sld.LineAdjudicationDetails_2430)
                                        {
                                            if (lad.LineAdjudicationInformation_2430 != null)
                                            {
                                                if (lad.LineAdjudicationInformation_2430.SVD01_OtherPayerPrimaryIdentifier == op.PayerInfo_2330B.OtherPayerName_2330B.NM109_SubmitterIdentifier)//we have a detail:)
                                                {
                                                    hasDetail = true;
                                                    break;
                                                }
                                            }
                                        }
                                    }
                                }
                                if (hasDetail) //Its a Detail record
                                {
                                    dtop.Rows.Add(i.ToString(), op.PayerInfo_2330B.OtherPayerName_2330B.NM103_SubmitterLastOrOrganizationName,
                                        op.PayerInfo_2330B.OtherPayerName_2330B.NM109_SubmitterIdentifier,
                                        op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM103_SubmitterLastOrOrganizationName,
                                        op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM104_SubmitterFirstName,
                                        GetPayerResponsibility(ost.SBR01_PayerResponsibilitySequenceNumberCode),
                                        string.IsNullOrEmpty(ost.SBR01_PayerResponsibilitySequenceNumberCode) ? "" : "Detail", op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM105_SubmitterMiddleNameOrInitial, ost.SBR09_ClaimFilingIndicatorCode, op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM109_SubmitterIdentifier,
                                        ost.SBR03_SubscriberGroupOrPolicyNumber, ost.SBR04_SubscriberGroupName, ost.SBR05_InsuranceTypeCode, ost.SBR02_IndividualRelationshipCode, op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A.N301_BillingProviderAddressLine,
                                        op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A.N302_BillingProviderAddressLine, op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N401_BillingProviderCityName,
                                        op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N402_BillingProviderStateOrProvinceCode,
