    private void SetDiagnosisClaimsInfoProfessional(DataSet profClaimsData)
    {
        if (profClaimsData.Tables[12].Rows.Count > 0)
        {
            DataTable dtd = GetDiagnosisInfoDT();
            int i = 1;
            foreach (DataRow dr in profClaimsData.Tables[12].Rows)
            {
                string PresentOnAdmission = "";
                if (dr["Present_On_Admission"].ToString().Equals("W"))
                {
                    PresentOnAdmission = "Not Applicable";
                }
                else if (dr["Present_On_Admission"].ToString().Equals("N"))
                {
                    PresentOnAdmission = "No";
                }
                else if (dr["Present_On_Admission"].ToString().Equals("Y"))
                {
                    PresentOnAdmission = "Yes";
                }
                else if (dr["Present_On_Admission"].ToString().Equals("U"))
                {
                    PresentOnAdmission = "Unknown";
                }
                else
                {
                    PresentOnAdmission = dr["Present_On_Admission"].ToString();
                }
                dtd.Rows.Add(dr["Claims_Diagnosis_Information_ID"] != null ? dr["Claims_Diagnosis_Information_ID"].ToString() : "", i, i.ToString(), dr["diag_code"] != null ? dr["diag_code"].ToString() : "",
                        dr["ICDVersion"] != null ? dr["ICDVersion"].ToString() : "", dr["Present_On_Admission"] != null ? PresentOnAdmission : "",
                        dr["diagnosisDescription"] != null ? dr["diagnosisDescription"].ToString() : "");
                i++;

            }
            DataSet dsd = new DataSet();
            dsd.Tables.Add(dtd);
            ucDiagnosisCodePanel.dataSetDiagnosisCode = dsd;
        }
    }
    private void SetOutpatientAdjudicationInfoProfessional(Professional.AddUpdateClaimsResponse addUpdateClaimsResponse)
    {
        if (addUpdateClaimsResponse.ProfessionalClaim837 != null && addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter != null &&
            addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter.PatientHierarchical_2000C != null &&
            addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300 != null &&
            addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300[0] != null)
        {
            if (addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300[0].OtherPayer_2320 != null)
            {
                var op = addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300[0].OtherPayer_2320[0].OutpatientAdjudicationInformation_2320;

                if (op != null)
                {
                    if (op.MOA01_ReimbursementRate != null)
                    {
                        ucOutpatientAdjudicationInformation.ReimbursementRate = op.MOA01_ReimbursementRate;
                    }
                    if (op.MOA02_HcpcsPayableAmount != null)
                    {
                        ucOutpatientAdjudicationInformation.HCPCSPayableAmount = op.MOA02_HcpcsPayableAmount;
                    }
                    if (op.MOA03_ClaimPaymentRemarkCode != null)
                    {
                        ucOutpatientAdjudicationInformation.ClaimRemarkCodeMOA03 = op.MOA03_ClaimPaymentRemarkCode;
                        ucOutpatientAdjudicationInformation.ClaimRemarkCodeMOA04 = op.MOA04_ClaimPaymentRemarkCode;
                    }
                }
            }

        }
    }

