    private void SetServiceLineDetailInfoProfessional(Professional.AddUpdateClaimsResponse addUpdateClaimsResponse)
    {
        DataTable dtsld = new DataTable();
        dtsld.Columns.Add("Claims_Service_Details_ID");
        dtsld.Columns.Add("Service_Line");
        dtsld.Columns.Add("Procedure_code");
        dtsld.Columns.Add("Place_of_Service");
        dtsld.Columns.Add("Billed_Units");
        dtsld.Columns.Add("Unit_of_Measurement");
        dtsld.Columns.Add("Date_of_Service");
        dtsld.Columns.Add("Charges");
        dtsld.Columns.Add("Paid_Units");
        dtsld.Columns.Add("Paid_Amount");
        dtsld.Columns.Add("Status");
        //Added columns
        dtsld.Columns.Add("Line_Control_Number");
        dtsld.Columns.Add("Prior_Authorization_Number");
        dtsld.Columns.Add("Referral_Number");
        dtsld.Columns.Add("Modifier1");
        dtsld.Columns.Add("Modifier2");
        dtsld.Columns.Add("Modifier3");
        dtsld.Columns.Add("Modifier4");
        dtsld.Columns.Add("Diagnosis_Pointer1");
        dtsld.Columns.Add("Diagnosis_Pointer2");
        dtsld.Columns.Add("Diagnosis_Pointer3");
        dtsld.Columns.Add("Diagnosis_Pointer4");
        dtsld.Columns.Add("Referred_EPSDT_Service");
        dtsld.Columns.Add("Family_Planning");
        dtsld.Columns.Add("Emergency");
        dtsld.Columns.Add("DME_Cert_Type");
        dtsld.Columns.Add("Final_EAPG");
        dtsld.Columns.Add("Payment_Action");
        //dtsld.Columns.Add("Billed_Units");
        dtsld.Columns.Add("DME_Duration");
        dtsld.Columns.Add("Cert_Revision");
        int i = 1;
        decimal totalChargesAmt = 0;
        decimal totalPaidAmt = 0;

        if (addUpdateClaimsResponse.ProfessionalClaim837 != null && addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter != null &&
            addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter.PatientHierarchical_2000C != null &&
            addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300 != null)
        {
            addUpdateClaimsResponse.ClaimLinesResponse = addUpdateClaimsResponse.ClaimLinesResponse.ToArray(); //.Where(x => x.DetailNumber.ToString() != "0").ToArray();
            foreach (Professional.ClaimDetails_2300Type cd in addUpdateClaimsResponse.ProfessionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300)
            {
                if (cd.ServiceLineDetails_2400 != null)
                {
                    foreach (Professional.ServiceLineDetails_2400Type sld in cd.ServiceLineDetails_2400)
                    {
                        dtsld.Rows.Add(i, sld.ServiceLineNumber_2400.LX01_AssignedNumber,
                        sld.ProfessionalService_2400 != null ? sld.ProfessionalService_2400.SV1012_ProcedureCode : "",
                        sld.ProfessionalService_2400.SV105_PlaceOfServiceCode,
                        sld.ProfessionalService_2400.SV104_ServiceUnitCount,
                        sld.ProfessionalService_2400.SV103_UnitOrBasisForMeasurementCode,
                        sld.DateServiceDate_2400.DTP03_OnsetOfCurrentIllnessOrInjuryDate == null ? "" : DateOfServiceDetails(sld.DateServiceDate_2400.DTP03_OnsetOfCurrentIllnessOrInjuryDate),
                        sld.ProfessionalService_2400.SV102_LineItemChargeAmount,
                       addUpdateClaimsResponse.ClaimLinesResponse[i - 1] == null ? "" : addUpdateClaimsResponse.ClaimLinesResponse[i - 1].PaidServiceUnit,
                       addUpdateClaimsResponse.ClaimLinesResponse[i - 1] == null ? "" : addUpdateClaimsResponse.ClaimLinesResponse[i - 1].PaidAmount,//Paid Amount per Dipendra
                       addUpdateClaimsResponse.ClaimLinesResponse[i - 1] == null ? "" : addUpdateClaimsResponse.ClaimLinesResponse[i - 1].LineStatus,//Status
                        sld.LineItemControlNumber_2400 == null ? "" : sld.LineItemControlNumber_2400.REF02_BillingProviderTaxIdentificationNumber,
                        sld.PriorAuthorization_2400 == null ? "" : sld.PriorAuthorization_2400[0].REF02_BillingProviderTaxIdentificationNumber,
                        sld.ReferralNumber_2400 == null ? "" : sld.ReferralNumber_2400[0].REF02_BillingProviderTaxIdentificationNumber,
                        sld.ProfessionalService_2400.SV1013_ProcedureModifier,
                        sld.ProfessionalService_2400.SV1014_ProcedureModifier,
                        sld.ProfessionalService_2400.SV1015_ProcedureModifier,
                        sld.ProfessionalService_2400.SV1016_ProcedureModifier,
                        sld.ProfessionalService_2400.SV1071_DiagnosisCodePointer,
                        sld.ProfessionalService_2400.SV1072_DiagnosisCodePointer == null ? "" : sld.ProfessionalService_2400.SV1072_DiagnosisCodePointer,
                        sld.ProfessionalService_2400.SV1073_DiagnosisCodePointer == null ? "" : sld.ProfessionalService_2400.SV1073_DiagnosisCodePointer,
                        sld.ProfessionalService_2400.SV1074_DiagnosisCodePointer == null ? "" : sld.ProfessionalService_2400.SV1074_DiagnosisCodePointer,
                        sld.ProfessionalService_2400.SV111_YesNoConditionOrResponseCode == null ? "" : sld.ProfessionalService_2400.SV111_YesNoConditionOrResponseCode,
                        sld.ProfessionalService_2400.SV112_YesNoConditionOrResponseCode == null ? "" : sld.ProfessionalService_2400.SV112_YesNoConditionOrResponseCode,
                        sld.ProfessionalService_2400.SV109_EmergencyIndicator == null ? "" : sld.ProfessionalService_2400.SV109_EmergencyIndicator,
                        sld.DurableMedicalEquipmentCertification_2400 == null ? "" : sld.DurableMedicalEquipmentCertification_2400.CR301_CertificationTypeCode,
                        null, null,
                        //sld.ProfessionalService_2400.SV104_ServiceUnitCount == null? "" : sld.ProfessionalService_2400.SV104_ServiceUnitCount,
                        sld.DurableMedicalEquipmentCertification_2400 == null ? "" : sld.DurableMedicalEquipmentCertification_2400.CR303_DurableMedicalEquipmentDuration,
                        sld.DateCertificationRevisionRecertificationDate_2400 == null ? "" : sld.DateCertificationRevisionRecertificationDate_2400.DTP03_OnsetOfCurrentIllnessOrInjuryDate
                        );
                        totalChargesAmt = totalChargesAmt + (string.IsNullOrEmpty(sld.ProfessionalService_2400.SV102_LineItemChargeAmount) ? 0 : Convert.ToDecimal(sld.ProfessionalService_2400.SV102_LineItemChargeAmount));
                        if (addUpdateClaimsResponse.ClaimLinesResponse != null)
                            totalPaidAmt = totalPaidAmt + (string.IsNullOrEmpty(addUpdateClaimsResponse.ClaimLinesResponse[i - 1].PaidAmount) ? 0 : Convert.ToDecimal(addUpdateClaimsResponse.ClaimLinesResponse[i - 1].PaidAmount));
                        i++;
                    }
                }
            }
        }
        ViewState["ProfessionalServiceDetailsTable"] = dtsld;
        ProfessionalServiceLineDetails.TotalCharges = totalChargesAmt.ToString();
        ProfessionalServiceLineDetails.TotalAmountPaid = totalPaidAmt.ToString();
        DataSet dssd = new DataSet();
        dssd.Tables.Add(dtsld);
        ProfessionalServiceLineDetails.dataSetServiceDetails = dssd;

    }
