    private void SetServiceLineDetailClaimsInfoProfessional(DataSet profClaimsData)
    {
        if (profClaimsData.Tables[14].Rows.Count > 0)
        {
            DataTable dtsld = new DataTable();
            dtsld.Columns.Add("Claims_Service_Details_ID");
            dtsld.Columns.Add("Service_Line");
            dtsld.Columns.Add("Procedure_code");
            dtsld.Columns.Add("Place_of_Service");
            dtsld.Columns.Add("Billed_Units");
            dtsld.Columns.Add("Unit_of_Measurement");
            dtsld.Columns.Add("Date_of_Service");
            dtsld.Columns.Add("Charges");
            dtsld.Columns.Add("Paid_Units");
            dtsld.Columns.Add("Paid_Amount");
            dtsld.Columns.Add("Status");
            int i = 1;
            decimal totalChargesAmt = 0;
            decimal totalPaidAmt = 0;

            foreach (DataRow dr in profClaimsData.Tables[14].Rows)
            {
                dtsld.Rows.Add(i, dr["Service_Line"] != null ? dr["Service_Line"].ToString() : "",
                        dr["Procedure_Code"] != null ? dr["Procedure_Code"].ToString() : "",
                        dr["Place_of_Service"] != null ? dr["Place_of_Service"].ToString() : "",
                        dr["Billed_Units"] != null ? dr["Billed_Units"].ToString() : "",
                        dr["Unit_of_Measurement"] != null ? dr["Unit_of_Measurement"].ToString() : "",
                        !string.IsNullOrEmpty(dr["Date_of_Service"].ToString()) ? Convert.ToDateTime(dr["Date_of_Service"].ToString()).ToString("MM/dd/yyyy") : "",
                        dr["Charges"] != null ? dr["Charges"].ToString() : "",
                        dr["Paid_Units"] != null ? dr["Paid_Units"].ToString() : "",
                        dr["Paid_Amount"] != null ? dr["Paid_Amount"].ToString() : "",
                        dr["Status"] != null ? dr["Status"].ToString() : ""
                        );
                totalChargesAmt = totalChargesAmt + (!string.IsNullOrEmpty(dr["Charges"].ToString()) ? Convert.ToDecimal(dr["Charges"].ToString()) : 0);
                totalPaidAmt = totalPaidAmt + (!string.IsNullOrEmpty(dr["Paid_Amount"].ToString()) ? Convert.ToDecimal(dr["Paid_Amount"].ToString()) : 0);
                i++;
            }

            ProfessionalServiceLineDetails.gvServiceLineDetails = dtsld;
            ProfessionalServiceLineDetails.TotalCharges = totalChargesAmt.ToString();
            ProfessionalServiceLineDetails.TotalAmountPaid = totalPaidAmt.ToString();
        }
    }
