                }
            }
            if (inquireProClaimReponse.ClaimLinesResponse != null)
            {
                i = 1;
                //Load CARC Line Details            
                foreach (Professional.ClaimLineDetailsType ct in inquireProClaimReponse.ClaimLinesResponse)
                {
                    if (ct.ListOfCARC != null)
                    {
                        foreach (Professional.CARCType cp in ct.ListOfCARC)
                        {
                            dtcrLine.Rows.Add(i.ToString(), cp.CARCCode, cp.CARCAmount, cp.CARCDescription, "", "");
                            i++;
                        }
                    }
                }

            }

            if (inquireProClaimReponse.ClaimLinesResponse != null)
            {
                j = 0;
                //Load RARC Line Details
                foreach (Professional.ClaimLineDetailsType rt in inquireProClaimReponse.ClaimLinesResponse)
                {

                    if (rt.ListOfRARC != null)
                    {
                        foreach (Professional.RARCType rp in rt.ListOfRARC)
                        {
                            if (j < i - 1)
                            {
                                dtcrLine.Rows[j]["RARC_NO"] = rp.RARCCode;
                                dtcrLine.Rows[j]["RARC_DESCRIPTION"] = rp.RARCDescription;
                            }
                            else
                            {
                                dtcrLine.Rows.Add((j + 1).ToString(), "", "", "", rp.RARCCode, rp.RARCDescription);
                            }
                            j++;
                        }
                    }
                }
            }
            dtcr.Merge(dtcrLine);
            CARCRARCInformation.ds = dtcr;
        }

        catch (Exception ex)
        {
            ThreadId = Guid.NewGuid();
            Logging log = new Logging(ThreadId, "Professional Claim Inquiry XML Data reload after submit button");
            log.CreateLogEntry(string.Format("{0} {1}", "Professional Claim Inquiry Submit button reload XML data for CARC and RAC Information panel of  claim Id:",
            hdnClaimId.Value.ToString() + "and response data" + inquireProClaimReponse.ToString() + "with error" + ex.Message.ToString()), Logging.LogPriority.Information);
        }
    }
