    private void SetServiceInfoInst(Inst.AddUpdateClaimsResponse icr)
    {
        if (icr.InstitutionalClaim837.BHTContainter.PatientHierarchical_2000C != null)
        {
            var cd = icr.InstitutionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300[0];
            if (cd != null)
            {
                if (!cd.ClaimInformation_2300.CLM051_FacilityTypeCode.ToString().StartsWith("0"))
                {
                    ucServiceInformationInstitutional.TypeofBill = "0" + cd.ClaimInformation_2300.CLM051_FacilityTypeCode + cd.ClaimInformation_2300.CLM053_ClaimFrequencyCode;
                }
                if ((cd.ClaimInformation_2300.CLM053_ClaimFrequencyCode != null) && (cd.ClaimInformation_2300.CLM053_ClaimFrequencyCode != ""))
                {
                    ucServiceInformationInstitutional.ClaimFrequencyCode = cd.ClaimInformation_2300.CLM053_ClaimFrequencyCode;
                }

                //ucServiceInformationInstitutional.TypeofBill = cd.ClaimInformation_2300.CLM051_FacilityTypeCode != null ? cd.ClaimInformation_2300.CLM051_FacilityTypeCode : "";
                ucServiceInformationInstitutional.PatientStatus = cd.InstitutionalClaimCode_2300.CL103_PatientStatusCode != null ? cd.InstitutionalClaimCode_2300.CL103_PatientStatusCode : "";
                if (cd.PatientEstimatedAmountDue_2300 != null)
                {
                    ucServiceInformationInstitutional.PatientPaidAmount = cd.PatientEstimatedAmountDue_2300.AMT02_PatientResponsibilityAmount != null ? cd.PatientEstimatedAmountDue_2300.AMT02_PatientResponsibilityAmount : "";
                }
                ucServiceInformationInstitutional.ReleaseofInformation = cd.ClaimInformation_2300.CLM09_RelaseOfInformationCode != null ? cd.ClaimInformation_2300.CLM09_RelaseOfInformationCode : "";
                if (cd.AdmissionDateHour_2300 != null)
                {
                    if (!string.IsNullOrEmpty(cd.AdmissionDateHour_2300.DTP03_DischargeHour))
                    {
                        var admissionDate = "";
                        var admissionHour = "";
                        if (cd.AdmissionDateHour_2300.DTP03_DischargeHour.Length == 12)
                        {
                            var parsedDate = DateTime.ParseExact(cd.AdmissionDateHour_2300.DTP03_DischargeHour, "yyyyMMddHHmm", System.Globalization.CultureInfo.InvariantCulture);
                            admissionDate = parsedDate.ToString("yyyyMMdd", System.Globalization.CultureInfo.InvariantCulture);
                            admissionHour = cd.AdmissionDateHour_2300.DTP03_DischargeHour.Substring(8, 4);
                            admissionDate = !string.IsNullOrEmpty(admissionDate) ? DateTime.ParseExact(admissionDate, "yyyyMMdd", System.Globalization.CultureInfo.InvariantCulture).ToString("MM/dd/yyyy", System.Globalization.CultureInfo.InvariantCulture) : "";

                        }
                        ucServiceInformationInstitutional.AdmissionDate = admissionDate;
                        ucServiceInformationInstitutional.AdmissionHour = admissionHour;
                    }
                }
                if (cd.DiagnosisRelatedGroupInformation_2300 != null)
                    ucServiceInformationInstitutional.SubmittedDRG = cd.DiagnosisRelatedGroupInformation_2300.HI01_Healthnformation.IndustryCode;

                var dateQualifier = cd.StatementDates_2300.DTP02_DateTimePeriodFormatQualifier;
                string fromDate = "";
                string toDate = "";
                if (dateQualifier == "RD8" && !string.IsNullOrEmpty(cd.StatementDates_2300.DTP03_DischargeHour))
                {
                    var dates = cd.StatementDates_2300.DTP03_DischargeHour.Split('-');
                    if (dates.Length > 0)
                    {
                        if (dates[0].Trim().Length == 8)
                        {
                            var parsedDate = DateTime.ParseExact(dates[0].Trim(), "yyyyMMdd", System.Globalization.CultureInfo.InvariantCulture);
                            fromDate = parsedDate.ToString("yyyyMMdd", System.Globalization.CultureInfo.InvariantCulture);
                            fromDate = !string.IsNullOrEmpty(fromDate) ? DateTime.ParseExact(fromDate, "yyyyMMdd", System.Globalization.CultureInfo.InvariantCulture).ToString("MM/dd/yyyy", System.Globalization.CultureInfo.InvariantCulture) : "";
                        }
                    }
                    if (dates.Length > 1)
                    {
                        if (dates[1].Trim().Length == 8)
                        {
