                    var parsedDate = DateTime.ParseExact(cd.AdmissionDateHour_2300.DTP03_DischargeHour, "yyyyMMddHHmm", System.Globalization.CultureInfo.InvariantCulture);
                    admissionDate = parsedDate.ToString("MM/dd/yyyy", System.Globalization.CultureInfo.InvariantCulture);
                    admissionHour = cd.AdmissionDateHour_2300.DTP03_DischargeHour.Substring(8, 4);
                }
                ucServiceInformationInstitutional.AdmissionDate = admissionDate;
                ucServiceInformationInstitutional.AdmissionHour = admissionHour;
