            ucServiceInformationInstitutional.SubmittedDRG = cd.DiagnosisRelatedGroupInformation_2300.HI01_Healthnformation.IndustryCode;

        var dateQualifier = cd.StatementDates_2300.DTP02_DateTimePeriodFormatQualifier;
        string fromDate = "";
        string toDate = "";
        if (dateQualifier == "RD8" && !string.IsNullOrEmpty(cd.StatementDates_2300.DTP03_DischargeHour))
        {
            var dates = cd.StatementDates_2300.DTP03_DischargeHour.Split('-');
            if (dates.Length > 0)
            {
                if (dates[0].Trim().Length == 8)
                {
                    var parsedDate = DateTime.ParseExact(dates[0].Trim(), "yyyyMMdd", System.Globalization.CultureInfo.InvariantCulture);
                    fromDate = parsedDate.ToString("yyyyMMdd", System.Globalization.CultureInfo.InvariantCulture);
                    fromDate = !string.IsNullOrEmpty(fromDate) ? DateTime.ParseExact(fromDate, "yyyyMMdd", System.Globalization.CultureInfo.InvariantCulture).ToString("MM/dd/yyyy", System.Globalization.CultureInfo.InvariantCulture) : "";

                }
            }
            if (dates.Length > 1)
            {
                if (dates[1].Trim().Length == 8)
                {
                    var parsedDate = DateTime.ParseExact(dates[1].Trim(), "yyyyMMdd", System.Globalization.CultureInfo.InvariantCulture);
                    toDate = parsedDate.ToString("yyyyMMdd", System.Globalization.CultureInfo.InvariantCulture);
                    toDate = !string.IsNullOrEmpty(toDate) ? DateTime.ParseExact(toDate, "yyyyMMdd", System.Globalization.CultureInfo.InvariantCulture).ToString("MM/dd/yyyy", System.Globalization.CultureInfo.InvariantCulture) : "";
                }
            }
        }
        else if (dateQualifier == "D8" && !string.IsNullOrEmpty(cd.StatementDates_2300.DTP03_DischargeHour))
        {
            var parsedDate = DateTime.ParseExact(cd.StatementDates_2300.DTP03_DischargeHour, "yyyyMMdd", System.Globalization.CultureInfo.InvariantCulture);
            fromDate = parsedDate.ToString("MMddyyyyHHmm", System.Globalization.CultureInfo.InvariantCulture); ;
        }
        ucServiceInformationInstitutional.FromDate = fromDate;
        ucServiceInformationInstitutional.Todate = toDate;
        if (cd.DischargeHour_2300 != null)
        {
            ucServiceInformationInstitutional.DischargeHour = cd.DischargeHour_2300.DTP03_DischargeHour;
        }
        ucServiceInformationInstitutional.FinalDRG = icr.ClaimHeaderResponse.DRGCode;
        ucServiceInformationInstitutional.AdmissionType = cd.InstitutionalClaimCode_2300.CL101_AdmissionTypeCode;
        ucServiceInformationInstitutional.AdmitSource = cd.InstitutionalClaimCode_2300.CL102_AdmissionSourceCode;
