    private void SetOtherPayerInfoInst(Inst.AddUpdateClaimsResponse icr)
    {
        if (!string.IsNullOrEmpty(ddlDestinationPayerResponsibilitySequence.SelectedValue))
        {
            ucOtherPayerInformation.ClearData(ddlDestinationPayerResponsibilitySequence.SelectedValue);
        }
        //--populate grid for Other Payers
        DataTable dtop = GetOtherPayerInfoDT();
        int i = 1;
        if (icr.InstitutionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300 != null)
        {
            foreach (Inst.ClaimDetails_2300Type cd in icr.InstitutionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300)
            {
                if (cd.OtherPayer_2320 != null)
                {
                    string hederType = null;
                    foreach (Inst.ServiceLineDetails_2400Type sld in cd.ServiceLineDetails_2400)
                    {
                        if (sld.LineAdjudicationDetails_2430 != null)
                        {
                            hederType = "Details";
                            break;
                        }
                    }
                    foreach (Inst.OtherPayer_2320Type op in cd.OtherPayer_2320)
                    {
                        var seqNo = op.OtherSubscriberInformation_2320.SBR01_PayerResponsibilitySequenceNumberCode;
                        dtop.Rows.Add(i.ToString(), op.PayerInfo_2330B.OtherPayerName_2330B.NM103_SubmitterLastOrOrganizationName,
                            op.PayerInfo_2330B.OtherPayerName_2330B.NM109_SubmitterIdentifier,
                            op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM103_SubmitterLastOrOrganizationName,
                            op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM104_SubmitterFirstName,
                            GetPayerResponsibility(op.OtherSubscriberInformation_2320.SBR01_PayerResponsibilitySequenceNumberCode),
                            string.IsNullOrEmpty(hederType) ? "Header" : hederType);
                        i++;
                    }
                }
            }
        }
        ViewState["OtherPayerInformationInstitutional"] = dtop;
        DataSet dsop = new DataSet();
        dsop.Tables.Add(dtop);
        ucOtherPayerInformation.dataSetOtherPayer = dsop;
        ucOtherPayerInformation.SubscribersState();
    }
    private void SetOtherPayerInfoInst(Inst.InquireClaimResponse icr)
    {
        //--populate grid for Other Payers
        if (!string.IsNullOrEmpty(ddlDestinationPayerResponsibilitySequence.SelectedValue))
        {
            ucOtherPayerInformation.ClearData(ddlDestinationPayerResponsibilitySequence.SelectedValue);
        }
        DataTable dtop = GetOtherPayerInfoDT();
        int i = 1;
        if (icr.InstitutionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300 != null)
        {
            foreach (Inst.ClaimDetails_2300Type cd in icr.InstitutionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300)
            {
                //string hederType = null;
                //if (cd.ServiceLineDetails_2400 != null)
                //{
                //    foreach (Inst.ServiceLineDetails_2400Type sld in cd.ServiceLineDetails_2400)
                //    {
                //        if (sld.LineAdjudicationDetails_2430 != null)
                //        {
                //            hederType = "Detail";
                //            break;
                //        }
                //    }
                //}
                if (cd.OtherPayer_2320 != null)
                {

                    foreach (Inst.OtherPayer_2320Type op in cd.OtherPayer_2320)
                    {
                        var ost = op.OtherSubscriberInformation_2320;//Per Dipendra 6086 use the first one from the list
                        if (op.ClaimLevelAdjustments_2320 != null && op.ClaimLevelAdjustments_2320.Length > 0)//CAS exist, then its a Header
                        {

                            if (op.SubscriberInfo_2330A != null)
                            {
                                dtop.Rows.Add(i.ToString(), op.PayerInfo_2330B.OtherPayerName_2330B.NM103_SubmitterLastOrOrganizationName,
                                    op.PayerInfo_2330B.OtherPayerName_2330B.NM109_SubmitterIdentifier,
                                    op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM103_SubmitterLastOrOrganizationName,
                                    op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM104_SubmitterFirstName,
                                    GetPayerResponsibility(op.OtherSubscriberInformation_2320.SBR01_PayerResponsibilitySequenceNumberCode),
                                    "Header", op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM105_SubmitterMiddleNameOrInitial,
                                    op.OtherSubscriberInformation_2320.SBR09_ClaimFilingIndicatorCode, op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM109_SubmitterIdentifier,
                                    op.OtherSubscriberInformation_2320.SBR03_SubscriberGroupOrPolicyNumber, op.OtherSubscriberInformation_2320.SBR04_SubscriberGroupName,
                                    op.OtherSubscriberInformation_2320.SBR05_InsuranceTypeCode, op.OtherSubscriberInformation_2320.SBR02_IndividualRelationshipCode,
                                    op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A == null ? " " : op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A.N301_BillingProviderAddressLine,
                                    op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A.N302_BillingProviderAddressLine,
                                    op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N401_BillingProviderCityName,
                                    op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N402_BillingProviderStateOrProvinceCode,
                                    op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N403_BillingProviderPostalZoneOrZipCode,
                                    op.PayerInfo_2330B.OtherPayerClaimControlNumber_2330B == null ? "" : op.PayerInfo_2330B.OtherPayerClaimControlNumber_2330B.REF02_BillingProviderTaxIdentificationNumber,
                                    op.PayerInfo_2330B.ClaimCheckOrRemittanceDate_2330B.DTP03_DischargeHour, op.CoordinationOfBenefitsPayerPaidAmount_2320 == null ? "0" : op.CoordinationOfBenefitsPayerPaidAmount_2320.AMT02_PatientResponsibilityAmount,
                                    op.CoordinationOfBenefitsTotalNonCoveredAmount_2320 == null ? "0" : op.CoordinationOfBenefitsTotalNonCoveredAmount_2320.AMT02_PatientResponsibilityAmount, op.OtherSubscriberInformation_2320.SBR01_PayerResponsibilitySequenceNumberCode);
                                i++;
                            }
                        }
                        else if (op.ClaimLevelAdjustments_2320 == null && cd.ServiceLineDetails_2400 != null && cd.ServiceLineDetails_2400.Length > 0)
                        {
                            var hasDetail = false;
                            foreach (Inst.ServiceLineDetails_2400Type sld in cd.ServiceLineDetails_2400)
                            {
                                if (sld.LineAdjudicationDetails_2430 != null)
                                {
                                    foreach (Inst.LineAdjudicationDetails_2430Type lad in sld.LineAdjudicationDetails_2430)
                                    {
                                        if (lad.LineAdjudicationInformation_2430 != null)
                                        {
                                            if (lad.LineAdjudicationInformation_2430.SVD01_OtherPayerPrimaryIdentifier == op.PayerInfo_2330B.OtherPayerName_2330B.NM109_SubmitterIdentifier)//we have a detail:)
                                            {
                                                hasDetail = true;
                                                break;
                                            }
                                        }
                                    }
                                }
                            }
                            if (hasDetail) //Its a Detail record
                            {
                                dtop.Rows.Add(i.ToString(), op.PayerInfo_2330B.OtherPayerName_2330B.NM103_SubmitterLastOrOrganizationName,
                                    op.PayerInfo_2330B.OtherPayerName_2330B.NM109_SubmitterIdentifier,
                                    op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM103_SubmitterLastOrOrganizationName,
                                    op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM104_SubmitterFirstName,
                                    GetPayerResponsibility(ost.SBR01_PayerResponsibilitySequenceNumberCode),
                                    string.IsNullOrEmpty(ost.SBR01_PayerResponsibilitySequenceNumberCode) ? "" : "Detail",
                                    op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM105_SubmitterMiddleNameOrInitial,
                                    ost.SBR09_ClaimFilingIndicatorCode, op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM109_SubmitterIdentifier,
                                    ost.SBR03_SubscriberGroupOrPolicyNumber, ost.SBR04_SubscriberGroupName,
                                    ost.SBR05_InsuranceTypeCode, ost.SBR02_IndividualRelationshipCode,
                                    op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A.N301_BillingProviderAddressLine,
                                    op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A.N302_BillingProviderAddressLine,
                                    op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N401_BillingProviderCityName,
                                    op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N402_BillingProviderStateOrProvinceCode,
                                    op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N403_BillingProviderPostalZoneOrZipCode,
                                    op.PayerInfo_2330B.OtherPayerClaimControlNumber_2330B == null ? "" : op.PayerInfo_2330B.OtherPayerClaimControlNumber_2330B.REF02_BillingProviderTaxIdentificationNumber,
                                    op.PayerInfo_2330B.ClaimCheckOrRemittanceDate_2330B.DTP03_DischargeHour, op.CoordinationOfBenefitsPayerPaidAmount_2320 == null ? "0" : op.CoordinationOfBenefitsPayerPaidAmount_2320.AMT02_PatientResponsibilityAmount,
                                    op.CoordinationOfBenefitsTotalNonCoveredAmount_2320 == null ? "0" : op.CoordinationOfBenefitsTotalNonCoveredAmount_2320.AMT02_PatientResponsibilityAmount, op.OtherSubscriberInformation_2320.SBR01_PayerResponsibilitySequenceNumberCode);
                                i++;
                            }
                            else //Neither Header not Detail record
                            {
                                dtop.Rows.Add(i.ToString(), op.PayerInfo_2330B.OtherPayerName_2330B.NM103_SubmitterLastOrOrganizationName,
                                    op.PayerInfo_2330B.OtherPayerName_2330B.NM109_SubmitterIdentifier,
                                    op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM103_SubmitterLastOrOrganizationName,
                                    op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM104_SubmitterFirstName,
                                    GetPayerResponsibility(ost.SBR01_PayerResponsibilitySequenceNumberCode),
                                    "",
                                    op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM105_SubmitterMiddleNameOrInitial,
                                    ost.SBR09_ClaimFilingIndicatorCode, op.SubscriberInfo_2330A.OtherSubscriberName_2330A.NM109_SubmitterIdentifier,
                                    ost.SBR03_SubscriberGroupOrPolicyNumber, ost.SBR04_SubscriberGroupName,
                                    ost.SBR05_InsuranceTypeCode, ost.SBR02_IndividualRelationshipCode,
                                    op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A.N301_BillingProviderAddressLine,
                                    op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberAddress_2330A.N302_BillingProviderAddressLine,
                                    op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N401_BillingProviderCityName,
                                    op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N402_BillingProviderStateOrProvinceCode,
                                    op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A == null ? "" : op.SubscriberInfo_2330A.OtherSubscriberCityStateZipCode_2330A.N403_BillingProviderPostalZoneOrZipCode,
                                    op.PayerInfo_2330B.OtherPayerClaimControlNumber_2330B == null ? "" : op.PayerInfo_2330B.OtherPayerClaimControlNumber_2330B.REF02_BillingProviderTaxIdentificationNumber,
                                    op.PayerInfo_2330B.ClaimCheckOrRemittanceDate_2330B.DTP03_DischargeHour, op.CoordinationOfBenefitsPayerPaidAmount_2320 == null ? "0" : op.CoordinationOfBenefitsPayerPaidAmount_2320.AMT02_PatientResponsibilityAmount,
