    private void SetOtherPayerClaimsInfoInst(DataSet instClaimsData)
    {
        if (!string.IsNullOrEmpty(ddlDestinationPayerResponsibilitySequence.SelectedValue))
        {
            ucOtherPayerInformation.ClearData(ddlDestinationPayerResponsibilitySequence.SelectedValue);
        }

        if (instClaimsData.Tables[11].Rows.Count > 0)
        {
            DataTable dtop = GetOtherPayerInfoDT();
            int i = 1;
            foreach (DataRow dr in instClaimsData.Tables[11].Rows)
            {
                dtop.Rows.Add(dr["Claims_Other_Payer_Information_ID"] != null ? dr["Claims_Other_Payer_Information_ID"].ToString() : ""
                    , dr["Other_Payer_Name"] != null ? dr["Other_Payer_Name"].ToString() : "", dr["Health_Plan_ID"] != null ? dr["Health_Plan_ID"].ToString() : "",
                    dr["Subscriber_Last_Name"] != null ? dr["Subscriber_Last_Name"].ToString() : "", dr["Subscriber_First_Name"] != null ? dr["Subscriber_First_Name"].ToString() : "",
                    dr["PRIOR_AUTH_SUBMIT_CLAIM_PAYERSEQUENCE_DESC"] != null ? dr["PRIOR_AUTH_SUBMIT_CLAIM_PAYERSEQUENCE_DESC"].ToString() : "",
                    dr["PRIOR_AUTH_SUBMIT_CLAIM_ADJUDICATION_LEVEL_DESC"] != null ? dr["PRIOR_AUTH_SUBMIT_CLAIM_ADJUDICATION_LEVEL_DESC"].ToString() : "",
                    dr["Payer_Responsibility_Sequence"] != null ? dr["Payer_Responsibility_Sequence"].ToString() : "",
                    dr["Claim_Filing_Indicator"] != null ? dr["Claim_Filing_Indicator"].ToString() : "",
                    dr["Policy_Number"] != null ? dr["Policy_Number"].ToString() : "",
                    dr["Group_Name"] != null ? dr["Group_Name"].ToString() : "",
                    dr["Subscriber_Subscriber_Number"] != null ? dr["Subscriber_Subscriber_Number"].ToString() : "",
                    dr["Paid_Date"] != null ? dr["Paid_Date"].ToString() : "",
                    dr["Insurance_Type_Code"] != null ? dr["Insurance_Type_Code"].ToString() : "",
                dr["PRIOR_AUTH_SUBMIT_CLAIM_ADJUDICATION_LEVEL_DESC"] != null ? dr["PRIOR_AUTH_SUBMIT_CLAIM_ADJUDICATION_LEVEL_DESC"].ToString() : "");
                i++;

            }
            DataSet dsop = new DataSet();
            dsop.Tables.Add(dtop);
            ucOtherPayerInformation.dataSetOtherPayer = dsop;
            if (!string.IsNullOrEmpty(ddlDestinationPayerResponsibilitySequence.SelectedValue))
            {
                ucOtherPayerInformation.ClearData(ddlDestinationPayerResponsibilitySequence.SelectedValue);
            }
        }
        ucOtherPayerInformation.SubscribersState();
    }
    private void SetHeaderOtherPayerAdjustmentInfoInst(Inst.AddUpdateClaimsResponse icr, string claimId)
    {
        //--populate grid for Header-Other Payer adjustments
        DataTable dthopa = GetHeaderOtherPayerAdjustmentInfoDT();
        int i = 1;
        if (icr.InstitutionalClaim837.BHTContainter.PatientHierarchical_2000C != null)
        {
            foreach (Inst.ClaimDetails_2300Type cd in icr.InstitutionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300)
            {
                if (cd.OtherPayer_2320 != null)
                {
                    foreach (Inst.OtherPayer_2320Type op in cd.OtherPayer_2320)
                    {
                        if (op.ClaimLevelAdjustments_2320 != null)
                        {
                            foreach (Inst.CASType clat in op.ClaimLevelAdjustments_2320)
                            {
                                dthopa.Rows.Add(i.ToString(),
                                op.PayerInfo_2330B.OtherPayerName_2330B.NM109_SubmitterIdentifier,
                                clat.CAS01_ClaimAdjustmentGroupCode,
