                    if (!string.IsNullOrEmpty(cd.PrincipalDiagnosis_2300.HI01_Healthnformation.HealthCareCodeInformation))
                    {
                        dtd.Rows.Add(i, i, CON.Sequences.Principal, cd.PrincipalDiagnosis_2300.HI01_Healthnformation.HealthCareCodeInformation,
