    private String getDiagnosisDescription(String DiagnosisCode, String ICDVersion)
    {
        String DiagnosisDescription = String.Empty;
        DataSet ds = LookupTableController.GetICDDiagnosisCode(DiagnosisCode, ICDVersion, "");
        if (Helper.HasRows(ds))
        {
            DiagnosisDescription = Helper.GetString("DiagDesc", ds.Tables[0].Rows[0]);
        }
        return DiagnosisDescription;
    }
    private string getPresentOnAdmissionIndicator(string presentOnAdmissionIndicatorShortName)
    {
        String DiagnosisInformation = String.Empty;
        if (!string.IsNullOrEmpty(presentOnAdmissionIndicatorShortName))
        {
            if (presentOnAdmissionIndicatorShortName == "Y")
            {
                DiagnosisInformation = "Yes";
            }
            else if (presentOnAdmissionIndicatorShortName == "N")
            {
                DiagnosisInformation = "No";

            }
            else if (presentOnAdmissionIndicatorShortName == "U")
            {
                DiagnosisInformation = "Unknown";
            }
            else if (presentOnAdmissionIndicatorShortName == "W")
            {
                DiagnosisInformation = "Not Applicable";
            }
        }
        return DiagnosisInformation;
    }
    private string GetDiagnosisSequenceDesc(string sequence)
    {
        if (sequence == "01")
        {
            sequence = CON.Sequences.Principal;
        }
        else if (sequence == "02")
        {
            sequence = CON.Sequences.Admitting;
        }
        else if (sequence == "03")
        {
            sequence = CON.Sequences.Other;
        }
        else if (sequence == "04")
        {
            sequence = CON.Sequences.PatientReasonforVisit;
        }
        else if (sequence == "05")
        {
            sequence = CON.Sequences.ExternalCauseofInjury;
        }
        return sequence;
    }
    private void SetDiagnosisClaimsInfoInst(DataSet instClaimsData)
    {
        if (instClaimsData.Tables[13].Rows.Count > 0)
        {
            DataTable dtd = GetDiagnosisInfoDT();
            int i = 1;
            foreach (DataRow dr in instClaimsData.Tables[13].Rows)
            {
                string PresentOnAdmission = "";
                if (dr["Present_On_Admission"].ToString().Equals("W"))
                {
                    PresentOnAdmission = "Not Applicable";
                }
                else if (dr["Present_On_Admission"].ToString().Equals("N"))
                {
                    PresentOnAdmission = "No";
                }
                else if (dr["Present_On_Admission"].ToString().Equals("Y"))
                {
                    PresentOnAdmission = "Yes";
                }
                else if (dr["Present_On_Admission"].ToString().Equals("U"))
                {
                    PresentOnAdmission = "Unknown";
                }
                else
                {
                    PresentOnAdmission = dr["Present_On_Admission"].ToString();
                }
                dtd.Rows.Add(dr["Claims_Diagnosis_Information_ID"] != null ? dr["Claims_Diagnosis_Information_ID"].ToString() : "", i, GetDiagnosisSequenceDesc(i.ToString()), dr["diag_code"] != null ? dr["diag_code"].ToString() : "",
                        dr["ICDVersion"] != null ? dr["ICDVersion"].ToString() : "", dr["Present_On_Admission"] != null ? PresentOnAdmission : "",
                        dr["diagnosisDescription"] != null ? dr["diagnosisDescription"].ToString() : "");
                i++;

            }
            DataSet dsd = new DataSet();
            dsd.Tables.Add(dtd);
            ucDiagnosisCodePanel.dataSetDiagnosisCode = dsd;
        }
    }
