    private String GetICDProcedureCodeDescription(String ICDCode, String ICDVersion)
    {
        String ICDProcedureCodeDesc = string.Empty;
        DataTable dt = LookupTableController.GetICDProcedureCode(ICDCode, "", ICDVersion);
        if (Helper.HasRows(dt))
        {
            var value = (from myrow in dt.AsEnumerable()
                         where myrow.Field<String>("CLAIMS_ICD_PROCEDURE_CODE") == ICDCode
                         select myrow.Field<String>("LONG_DESC")).Take(1);

            ICDProcedureCodeDesc = Convert.ToString(value.FirstOrDefault());
        }
        return ICDProcedureCodeDesc;
    }
