    private void SetICDProcedureCodesClaimsInst(DataSet instClaimsData, string claimId)
    {
        if (instClaimsData.Tables[14].Rows.Count > 0)
        {
            DataTable dti = new DataTable();
            dti.Columns.Add("Claims_ICD_Procedure_Code_Sequence_ID");
            dti.Columns.Add("Sequence_NO");
            dti.Columns.Add("Claim_ID");
            dti.Columns.Add("ICD_Procedure_Code");
            dti.Columns.Add("ICD_Version");
            dti.Columns.Add("ICD_Date");
            dti.Columns.Add("Procedure_Code_Description");
            dti.Columns.Add("PRIOR_AUTH_CLAIM_SEQUENCE_Desc");
            int i = 1;
            //Principal Diagnosis code
            foreach (DataRow dr in instClaimsData.Tables[14].Rows)
            {
                if (!string.IsNullOrEmpty(dr["ICD_Procedure_Code"].ToString()))
                {
                    dti.Rows.Add(dr["Claims_ICD_Procedure_Code_Sequence_ID"] != null ? dr["Claims_ICD_Procedure_Code_Sequence_ID"].ToString() : "",
                        dr["Sequence_NO"] != null ? dr["Sequence_NO"].ToString() : "", claimId,
                        dr["ICD_Procedure_Code"] != null ? dr["ICD_Procedure_Code"].ToString() : "",
                        dr["ICD_Version"] != null ?

                        dr["ICD_Version"].ToString() : "",
                        !string.IsNullOrEmpty(dr["ICD_Date"].ToString()) ? Convert.ToDateTime(dr["ICD_Date"].ToString()).ToString("MM/dd/yyyy") : "",
                        dr["Procedure_Code_Description"] != null ? dr["Procedure_Code_Description"].ToString() : "",
                        dr["PRIOR_AUTH_CLAIM_SEQUENCE_Desc"] != null ? dr["PRIOR_AUTH_CLAIM_SEQUENCE_Desc"].ToString() : "");
                    i++;
                }
            }

            DataSet dsi = new DataSet();
            dsi.Tables.Add(dti);
            ucSubmitClaimICDProcedureCode.dataSetICDProdureCodeInfo = dsi;
        }
    }
