    private String GetOccurenceCodeDescription(String OccurenceCode)
    {
        DataSet ds = LookupTableController.GetOccurreneceCode(OccurenceCode, "");
        var val = (from myrow in ds.Tables[0].AsEnumerable()
                   where myrow.Field<String>("CLAIMS_OCCURRENCE_CODE") == OccurenceCode
                   select myrow.Field<String>("CLAIMS_OCCURRENCE_CODE_DESC")).Take(1);

        String OccurenceCodeDesc = Convert.ToString(val.FirstOrDefault());
        return OccurenceCodeDesc;
    }

    private void SetOccurrenceClaimsInfoInst(DataSet instClaimsData)
    {
        if (instClaimsData.Tables[15].Rows.Count > 0)
        {
            DataTable dtu = new DataTable();
