            {
                if (dr["OccurrenceCode"] != null)
                {
                    dtu.Rows.Add(dr["ClaimsOccurrenceInformationID"] != null ? dr["ClaimsOccurrenceInformationID"].ToString() : "", i,
                        dr["OccurrenceCode"] != null ? dr["OccurrenceCode"].ToString() : "",
                        dr["OccurrenceDate"] != null ? Convert.ToDateTime(dr["OccurrenceDate"].ToString()).ToString("MM/dd/yyyy") : "",
