    private void SetOccurrenceSpanClaimsInfoInst(DataSet instClaimsData)
    {
        if (instClaimsData.Tables[16].Rows.Count > 0)
        {
            DataTable dtus = new DataTable();
            dtus.Columns.Add("Claims_Occurrence_Code_Span_Information_ID");
            dtus.Columns.Add("Line");
            dtus.Columns.Add("Occurrence_Code_Span");
            dtus.Columns.Add("FromDate");
            dtus.Columns.Add("ToDate");
            dtus.Columns.Add("CLAIMS_OCCURRENCE_CODE_DESC");
            int i = 1;

            foreach (DataRow dr in instClaimsData.Tables[16].Rows)
            {
                if (!string.IsNullOrEmpty(dr["Occurrence_Code_Span"].ToString()))
                {
                    dtus.Rows.Add(dr["Claims_Occurrence_Code_Span_Information_ID"] != null ? dr["Claims_Occurrence_Code_Span_Information_ID"].ToString() : "", i, dr["Occurrence_Code_Span"].ToString(), Convert.ToDateTime(dr["FromDate"].ToString()).ToString("MM/dd/yyyy"), Convert.ToDateTime(dr["ToDate"].ToString()).ToString("MM/dd/yyyy"), dr["CLAIMS_OCCURRENCE_CODE_DESC"].ToString());
                    i++;
                }
            }

            DataSet dsus = new DataSet();
            dsus.Tables.Add(dtus);
            ucOccurenceSpanInformation.OccurenceSpanInformation = dsus;
        }
    }
