    private String GetConditionCodeDescription(String ConditionCode)
    {
        String ConditionCodedescription = String.Empty;
        DataSet ds = svc.GetConditionCodeDescription(ConditionCode);
        ConditionCodedescription = Helper.HasRows(ds) ? Helper.GetString("CLAIMS_CONDITION_CODE_DESCRIPTION", ds.Tables[0].Rows[0]) : "";
        return ConditionCodedescription;
    }

    private void SetConditionCodeClaimsInfoInst(DataSet instClaimsData, string claimId)
    {
        if (instClaimsData.Tables[17].Rows.Count > 0)
        {
            DataTable dtcc = new DataTable();
            dtcc.Columns.Add("Claims_Condition_Code_Information_ID");
            dtcc.Columns.Add("line");
            dtcc.Columns.Add("Condition_Code");
            dtcc.Columns.Add("CLAIMS_CONDITION_CODE_DESCRIPTION");
            dtcc.Columns.Add("Claim_ID");
            int i = 1;

            foreach (DataRow dr in instClaimsData.Tables[17].Rows)
            {
                if (!string.IsNullOrEmpty(dr["Condition_Code"].ToString()))
                {
                    dtcc.Rows.Add(dr["Claims_Condition_Code_Information_ID"] != null ? dr["Claims_Condition_Code_Information_ID"] : "", i.ToString(), dr["Condition_Code"] != null ? dr["Condition_Code"].ToString() : "", dr["CLAIMS_CONDITION_CODE_DESCRIPTION"] != null ? dr["CLAIMS_CONDITION_CODE_DESCRIPTION"].ToString() : "", claimId);
                    i++;
                }
            }

            DataSet dscc = new DataSet();
            dscc.Tables.Add(dtcc);
            ucConditionCodeInformation.datasetConditionCode = dscc;
        }
