    private String GetValueCodeDescription(String valueCode)
    {
        String valueCodeDescription = string.Empty;
        DataSet ds = svc.GetValueCodeDescription(valueCode);
        if (Helper.HasRows(ds))
        {
            valueCodeDescription = Helper.GetString("CLAIMS_VALUE_CODE_DESC", ds.Tables[0].Rows[0]);
        }
        return valueCodeDescription;
    }

