    private void SetServiceDetailInfoInst(Inst.AddUpdateClaimsResponse icr)
    {
        try
        {
            DataTable dtsd = new DataTable();
            dtsd.Columns.Add("Service_Line");
            dtsd.Columns.Add("Revenue_Code");
            dtsd.Columns.Add("Procedure_Type");
            dtsd.Columns.Add("Procedure_code");
            dtsd.Columns.Add("Billed_Units");
            dtsd.Columns.Add("Unit_Of_Measurement");
            dtsd.Columns.Add("Date_of_Service");
            dtsd.Columns.Add("To_Date_of_Service");
            dtsd.Columns.Add("Total_Charges");
            dtsd.Columns.Add("Paid_Amount");
            dtsd.Columns.Add("Status");
            //Adding columns
            //dtsd.Columns.Add("Line_Control_Number");
            //dtsd.Columns.Add("Modifier1");
            //dtsd.Columns.Add("Modifier2");
            //dtsd.Columns.Add("Modifier3");
            //dtsd.Columns.Add("Modifier4");
            //dtsd.Columns.Add("Non_Covered_Charges");
            decimal totalChargesAmt = 0;
            decimal totalPaidAmt = 0;
            int i = 1;
            foreach (Inst.ClaimDetails_2300Type cd in icr.InstitutionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300)
            {
                icr.ClaimLinesResponse = icr.ClaimLinesResponse.ToArray(); // icr.ClaimLinesResponse.Where(x => x.DetailNumber.ToString() != "0").ToArray();
                if (cd.ServiceLineDetails_2400 != null)
                {
                    foreach (Inst.ServiceLineDetails_2400Type sld in cd.ServiceLineDetails_2400)
                    {
                        string fromDate = "";
                        string toDate = "";
                        if (sld.DateServiceDate_2400 != null)
