    private void SetServiceDetailInfoInst(Inst.InquireClaimResponse icr)
    {
        try
        {
            DataTable dtsd = new DataTable();
            dtsd.Columns.Add("Service_Line");
            dtsd.Columns.Add("Revenue_Code");
            dtsd.Columns.Add("Procedure_Type");
            dtsd.Columns.Add("Procedure_code");
            dtsd.Columns.Add("Billed_Units");
            dtsd.Columns.Add("Unit_Of_Measurement");
            dtsd.Columns.Add("Date_of_Service");
            dtsd.Columns.Add("To_Date_of_Service");
            dtsd.Columns.Add("Total_Charges");
            dtsd.Columns.Add("Paid_Amount");
            dtsd.Columns.Add("Status");
            //Adding columns
            dtsd.Columns.Add("Line_Control_Number");
            dtsd.Columns.Add("Modifier1");
            dtsd.Columns.Add("Modifier2");
            dtsd.Columns.Add("Modifier3");
            dtsd.Columns.Add("Modifier4");
            dtsd.Columns.Add("Non_Covered_Charges");
            decimal totalChargesAmt = 0;
            decimal totalPaidAmt = 0;
            int i = 1;
            foreach (Inst.ClaimDetails_2300Type cd in icr.InstitutionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300)
            {
                icr.ClaimLinesResponse = icr.ClaimLinesResponse.ToArray(); // .Where(x => x.DetailNumber.ToString() != "0").ToArray();
                if (cd.ServiceLineDetails_2400 != null)
                {
                    foreach (Inst.ServiceLineDetails_2400Type sld in cd.ServiceLineDetails_2400)
                    {
                        string fromDate = "";
                        string toDate = "";
                        if (sld.DateServiceDate_2400 != null)
                            GetFromToDates(sld.DateServiceDate_2400.DTP02_DateTimePeriodFormatQualifier, sld.DateServiceDate_2400.DTP03_DischargeHour, ref fromDate, ref toDate);

                        dtsd.Rows.Add(sld.ServiceLineNumber_2400.LX01_AssignedNumber,//Service_Line
                            sld.InstitutionalServiceLine_2400.SV201_ServiceLineRevenueCode,//RevenueCode
                                                                                           //sld.InstitutionalServiceLine_2400.SV2021_ProductOrServiceIdQualifier,//Procedure_type
                             "HCPCS",
                            sld.InstitutionalServiceLine_2400.SV2022_ProcedureCode,//Procedure_code
                            sld.InstitutionalServiceLine_2400.SV205_ServiceUnitCount, //Billed_Units
                            sld.InstitutionalServiceLine_2400.SV204_UnitOrBasisForMeasurementCode,//Unit_Of_Measurement
                            fromDate,//Date_of_Service
                            toDate,//To_Date_of_Service
                            sld.InstitutionalServiceLine_2400.SV203_LineItemChargeAmount, //Total_Charges
                            icr.ClaimLinesResponse[i - 1] == null ? "" : icr.ClaimLinesResponse[i - 1].PaidAmount,//Paid Amount per Dipendra
                            icr.ClaimLinesResponse[i - 1] == null ? "" : icr.ClaimLinesResponse[i - 1].LineStatus,//Status
                            sld.LineItemControlNumber_2400,//Line Control Number
                            sld.InstitutionalServiceLine_2400.SV2023_ProcedureModifier,//Modifier 1
                            sld.InstitutionalServiceLine_2400.SV2024_ProcedureModifier,//Modifier 2
                            sld.InstitutionalServiceLine_2400.SV2025_ProcedureModifier,//Modifier 3
                            sld.InstitutionalServiceLine_2400.SV2026_ProcedureModifier,//Modifier 4
                            sld.InstitutionalServiceLine_2400.SV207_LineItemDeniedChargeOrNonCoveredChargeAmount//Non Covered charges
                            );

                        totalChargesAmt = totalChargesAmt + (string.IsNullOrEmpty(sld.InstitutionalServiceLine_2400.SV203_LineItemChargeAmount) ? 0 : Convert.ToDecimal(sld.InstitutionalServiceLine_2400.SV203_LineItemChargeAmount));
                        if (icr.ClaimLinesResponse[i - 1] != null)
                            totalPaidAmt = totalPaidAmt + (string.IsNullOrEmpty(icr.ClaimLinesResponse[i - 1].PaidAmount) ? 0 : Convert.ToDecimal(icr.ClaimLinesResponse[i - 1].PaidAmount));
                        i++;
                    }
                }
            }
            ViewState["ServiceLineDetailsInstitutional"] = dtsd;
            DataSet dssd = new DataSet();
            dssd.Tables.Add(dtsd);
            InstitutionalServiceDetails.TotalAmountBilled = totalChargesAmt.ToString();
            InstitutionalServiceDetails.TotalAmountPaid = totalPaidAmt.ToString();
            InstitutionalServiceDetails.FromInquirySvc = true;
            InstitutionalServiceDetails.dataSetServiceDetails = dssd;

        }
        catch (Exception ex)
        { }
    }

    private void SetServiceDetailClaimsInfoInst(DataSet instClaimsData)
    {
        if (instClaimsData.Tables[21].Rows.Count > 0)
        {
            DataTable dtsd = new DataTable();
            dtsd.Columns.Add("Service_Line");
            dtsd.Columns.Add("Revenue_Code");
            dtsd.Columns.Add("Procedure_Type");
            dtsd.Columns.Add("Procedure_code");
            dtsd.Columns.Add("Billed_Units");
            dtsd.Columns.Add("Unit_Of_Measurement");
            dtsd.Columns.Add("Date_of_Service");
            dtsd.Columns.Add("To_Date_of_Service");
            dtsd.Columns.Add("Total_Charges");
            dtsd.Columns.Add("Paid_Amount");
            dtsd.Columns.Add("Status");
            decimal totalChargesAmt = 0;
            decimal totalPaidAmt = 0;
            int i = 1;
            foreach (DataRow dr in instClaimsData.Tables[21].Rows)
            {
                dtsd.Rows.Add(dr["Service_Line"] != null ? dr["Service_Line"].ToString() : "",//Service_Line
                                       dr["Revenue_Code"] != null ? dr["Revenue_Code"].ToString() : "",//RevenueCode
                                       dr["Procedure_Type"] != null ? dr["Procedure_Type"].ToString() : "",//Procedure_type
                                       dr["Procedure_code"] != null ? dr["Procedure_code"].ToString() : "",//Procedure_code
                                       dr["Billed_Units"] != null ? dr["Billed_Units"].ToString() : "", //Billed_Units
                                       dr["Unit_Of_Measurement"] != null ? dr["Unit_Of_Measurement"].ToString() : "",//Unit_Of_Measurement
                                       !string.IsNullOrEmpty(dr["Date_of_Service"].ToString()) ? Convert.ToDateTime(dr["Date_of_Service"].ToString()).ToString("MM/dd/yyyy") : "",//Date_of_Service
                                       !string.IsNullOrEmpty(dr["To_Date_of_Service"].ToString()) ? Convert.ToDateTime(dr["To_Date_of_Service"].ToString()).ToString("MM/dd/yyyy") : "",//To_Date_of_Service
                                       dr["Total_Charges"] != null ? dr["Total_Charges"].ToString() : "", //Total_Charges
                                       dr["Paid_Amount"] != null ? dr["Paid_Amount"].ToString() : "",//Paid Amount per Dipendra
                                       "Pending Submission"//Status
                                       );

                totalChargesAmt = totalChargesAmt + (!string.IsNullOrEmpty(dr["Total_Charges"].ToString()) ? Convert.ToDecimal(dr["Total_Charges"].ToString()) : 0);
                totalPaidAmt = totalPaidAmt + (!string.IsNullOrEmpty(dr["Paid_Amount"].ToString()) ? Convert.ToDecimal(dr["Paid_Amount"].ToString()) : 0);
                i++;
            }
            DataSet dssd = new DataSet();
            dssd.Tables.Add(dtsd);
            InstitutionalServiceDetails.gvServiceLineDetails = dssd;
            InstitutionalServiceDetails.TotalAmountBilled = totalChargesAmt.ToString();
            InstitutionalServiceDetails.TotalAmountPaid = totalPaidAmt.ToString();
        }
    }
    private void SetNDCDetailInfoInst(Inst.AddUpdateClaimsResponse icr, string claimId)
    {
