        dtndc.Columns.Add("Prescription_Number");
        dtndc.Columns.Add("Total_Unit");
        dtndc.Columns.Add("Claim_ID");
        int i = 1;
        if (icr.InstitutionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300 != null)
        {
            foreach (Inst.ClaimDetails_2300Type cd in icr.InstitutionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300)
            {
                if (cd.ServiceLineDetails_2400 != null)
                {
                    foreach (Inst.ServiceLineDetails_2400Type sld in cd.ServiceLineDetails_2400)
