    private void SetAdditionalProviderInfoInst(Inst.AddUpdateClaimsResponse icr)
    {
        DataTable dtap = GetAdditionalProviderDT();
        int i = 1;
        //Load Operating physician details
        foreach (Inst.ClaimDetails_2300Type cd in icr.InstitutionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300)
        {
            foreach (Inst.ServiceLineDetails_2400Type sd in cd.ServiceLineDetails_2400)
            {
                if (sd.OperatingPhysicianDetails_2420A != null)
                {
                    //i.ToString(),
                    dtap.Rows.Add(i, (sd.ServiceLineNumber_2400.LX01_AssignedNumber.Length == 1 ? sd.ServiceLineNumber_2400.LX01_AssignedNumber : sd.ServiceLineNumber_2400.LX01_AssignedNumber),
                        "Other Operating Physician",
                        sd.OperatingPhysicianDetails_2420A.OperatingPhysicianName_2420A.NM109_SubmitterIdentifier,
                        "",
                        sd.OperatingPhysicianDetails_2420A.OperatingPhysicianName_2420A.NM103_SubmitterLastOrOrganizationName,
                        sd.OperatingPhysicianDetails_2420A.OperatingPhysicianName_2420A.NM104_SubmitterFirstName,
                        sd.OperatingPhysicianDetails_2420A.OperatingPhysicianName_2420A.NM105_SubmitterMiddleNameOrInitial);
                    i++;
                }
            }
        }
        //Load Other Operating physician details
        foreach (Inst.ClaimDetails_2300Type cd in icr.InstitutionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300)
        {
            foreach (Inst.ServiceLineDetails_2400Type sd in cd.ServiceLineDetails_2400)
            {
                if (sd.OtherOperatingPhysicianDetails_2420B != null)
                {
                    dtap.Rows.Add(i, (sd.ServiceLineNumber_2400.LX01_AssignedNumber.Length == 1 ? sd.ServiceLineNumber_2400.LX01_AssignedNumber : sd.ServiceLineNumber_2400.LX01_AssignedNumber),
                        "Other Operating Physician",
                        sd.OtherOperatingPhysicianDetails_2420B.OtherOperatingPhysicianName_2420B.NM109_SubmitterIdentifier,
                        "",
                        sd.OtherOperatingPhysicianDetails_2420B.OtherOperatingPhysicianName_2420B.NM103_SubmitterLastOrOrganizationName,
                        sd.OtherOperatingPhysicianDetails_2420B.OtherOperatingPhysicianName_2420B.NM104_SubmitterFirstName,
                        sd.OtherOperatingPhysicianDetails_2420B.OtherOperatingPhysicianName_2420B.NM105_SubmitterMiddleNameOrInitial);
                    i++;
                }
            }
        }
        //Load Rendering provider details
        foreach (Inst.ClaimDetails_2300Type cd in icr.InstitutionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300)
        {
            foreach (Inst.ServiceLineDetails_2400Type sd in cd.ServiceLineDetails_2400)
            {
                if (sd.RenderingProviderDetails_2420C != null)
                {
                    dtap.Rows.Add(i, (sd.ServiceLineNumber_2400.LX01_AssignedNumber.Length == 1 ? sd.ServiceLineNumber_2400.LX01_AssignedNumber : sd.ServiceLineNumber_2400.LX01_AssignedNumber),
                        "Rendering Provider",
                        sd.RenderingProviderDetails_2420C.RenderingProviderName_2420C.NM109_SubmitterIdentifier,
                        "",
                        sd.RenderingProviderDetails_2420C.RenderingProviderName_2420C.NM103_SubmitterLastOrOrganizationName,
                        sd.RenderingProviderDetails_2420C.RenderingProviderName_2420C.NM104_SubmitterFirstName,
                        sd.RenderingProviderDetails_2420C.RenderingProviderName_2420C.NM105_SubmitterMiddleNameOrInitial);
                    i++;
                }
            }
        }
        //Load Referring/Primary Care Provider Details
        foreach (Inst.ClaimDetails_2300Type cd in icr.InstitutionalClaim837.BHTContainter.PatientHierarchical_2000C.ClaimDetails_2300)
        {
            foreach (Inst.ServiceLineDetails_2400Type sd in cd.ServiceLineDetails_2400)
            {
                if (sd.ReferringProviderDetails_2420D != null)
                {
                    dtap.Rows.Add(i, (sd.ServiceLineNumber_2400.LX01_AssignedNumber.Length == 1 ? sd.ServiceLineNumber_2400.LX01_AssignedNumber : sd.ServiceLineNumber_2400.LX01_AssignedNumber),
                        sd.ReferringProviderDetails_2420D.ReferringProviderName_2420D.NM101_EntityIdentifierCode == "DN" ? "Referring Provider" : "Primary Care Provider",
                        sd.ReferringProviderDetails_2420D.ReferringProviderName_2420D.NM109_SubmitterIdentifier,
                        "",
                        sd.ReferringProviderDetails_2420D.ReferringProviderName_2420D.NM103_SubmitterLastOrOrganizationName,
                        sd.ReferringProviderDetails_2420D.ReferringProviderName_2420D.NM104_SubmitterFirstName,
                        sd.ReferringProviderDetails_2420D.ReferringProviderName_2420D.NM105_SubmitterMiddleNameOrInitial);
                    i++;
                }
            }
        }
        ViewState["AdditionalProviderInformationInstituional"] = dtap;
        DataSet dsap = new DataSet();
        dsap.Tables.Add(dtap);
        ucAdditionalProviderInfoPanel.AdditionalProviderinfo = dsap;
    }
