    private void SetCARCandRARCInfoInst(Inst.AddUpdateClaimsResponse icr)
    {
        try
        {
            DataTable dtcr = GetCARCAndRARCInfoDT();
            DataTable dtcrLine = GetCARCAndRARCInfoDTForLines();
            int i = 1;
            if (icr.ClaimHeaderResponse.ListOfCARC != null)
            {
                //Load CARC Header Details
                foreach (Inst.CARCType ct in icr.ClaimHeaderResponse.ListOfCARC)
                {
                    dtcr.Rows.Add("0", ct.CARCCode, ct.CARCAmount, ct.CARCDescription, "", "");
                    i++;
                }
            }
            int j = 0;
            if (icr.ClaimHeaderResponse.ListOfRARC != null)
            {
                //Load RARC Header Details
                foreach (Inst.RARCType rt in icr.ClaimHeaderResponse.ListOfRARC)
                {
                    if (j < i - 1)
                    {
                        dtcr.Rows[j]["RARC_NO"] = rt.RARCCode;
                        dtcr.Rows[j]["RARC_DESCRIPTION"] = rt.RARCDescription;
                    }
                    else
                    {
                        dtcr.Rows.Add("0", "", "", "", rt.RARCCode, rt.RARCDescription);
                    }
                    j++;
                }
            }
            if (icr.ClaimLinesResponse != null)
            {
                i = 1;
                //Load CARC Line Details            
                foreach (Inst.ClaimLineDetailsType ct in icr.ClaimLinesResponse)
                {
                    if (ct.ListOfCARC != null)
                    {
                        foreach (Inst.CARCType cp in ct.ListOfCARC)
                        {
                            dtcrLine.Rows.Add(i.ToString(), cp.CARCCode, cp.CARCAmount, cp.CARCDescription, "", "");
                            i++;
                        }
                    }
                }

            }

            if (icr.ClaimLinesResponse != null)
            {
                j = 0;
                //Load RARC Line Details
                foreach (Inst.ClaimLineDetailsType rt in icr.ClaimLinesResponse)
                {

                    if (rt.ListOfRARC != null)
                    {
                        foreach (Inst.RARCType rp in rt.ListOfRARC)
                        {
                            if (j < i - 1)
                            {
                                dtcrLine.Rows[j]["RARC_NO"] = rp.RARCCode;
                                dtcrLine.Rows[j]["RARC_DESCRIPTION"] = rp.RARCDescription;
                            }
                            else
                            {
                                dtcrLine.Rows.Add((j + 1).ToString(), "", "", "", rp.RARCCode, rp.RARCDescription);
                            }
                            j++;
                        }
                    }
                }
            }
            dtcr.Merge(dtcrLine);
            CARCRARCInformation.ds = dtcr;
        }


        catch (Exception ex)
        {
            ThreadId = Guid.NewGuid();
            Logging log = new Logging(ThreadId, "InstitutionalClaim XML Data reload after submit button");
            log.CreateLogEntry(string.Format("{0} {1}", "Institutional Claim  Submit button reload XML data for CARC and RAC Information panel of  claim Id:",
                hdnClaimId.Value.ToString() + "and response data" + icr.ToString() + "with error" + ex.Message.ToString()), Logging.LogPriority.Information);


        }
    }
