    private string GetPayerResponsibility(string seqNo)
    {
        var seqVal = "Unknown";
        switch (seqNo)
        {
            case "P":
                seqVal = "Primary";
                break;
            case "S":
                seqVal = "Secondary";
                break;
            case "T":
                seqVal = "Tertiary";
                break;
            case "A":
                seqVal = "Payer Four";
                break;
            case "B":
                seqVal = "Payer Five";
                break;
            case "C":
                seqVal = "Payer Six";
                break;
            case "D":
                seqVal = "Payer Seven";
                break;
            case "EB":
                seqVal = "Payer Eight";
                break;
            case "F":
                seqVal = "Payer Nine";
                break;
            case "G":
                seqVal = "Payer Ten";
                break;
            case "H":
                seqVal = "Payer Eleven";
                break;
            default:
                seqVal = "Unknown";
                break;
        }
        return seqVal;
    }

    private string forceDatePartsToTwoCharacters(string date)
    {
        var dateParts = date.Split('/');
        if ((dateParts[0].Trim().Length == 1) && (dateParts[1].Trim().Length == 1))
        {
            date = "0" + dateParts[0] + "/" + "0" + dateParts[1] + "/" + dateParts[2];
        }
        else if ((dateParts[0].Trim().Length == 1) && (dateParts[1].Trim().Length != 1))
        {
            date = "0" + dateParts[0] + "/" + dateParts[1] + "/" + dateParts[2];
        }
        else if ((dateParts[1].Trim().Length != 1) && (dateParts[1].Trim().Length == 1))
        {
            date = dateParts[0] + "/" + "0" + dateParts[1] + "/" + dateParts[2];
        }
        return date;
    }

    private void GetFromToDates(string dateQualifier, string datePeriod, ref string fromDate, ref string toDate)
    {
        if (dateQualifier == "RD8" && !string.IsNullOrEmpty(datePeriod))
        {
            var dates = datePeriod.Split('-');
            if (dates.Length > 0)
            {
                var parsedDate = DateTime.ParseExact(dates[0].Trim(), "yyyyMMdd", System.Globalization.CultureInfo.InvariantCulture);
                fromDate = forceDatePartsToTwoCharacters(parsedDate.ToString("MM/dd/yyyy", System.Globalization.CultureInfo.InvariantCulture));

            }
            if (dates.Length > 1)
            {
                var parsedDate = DateTime.ParseExact(dates[1].Trim(), "yyyyMMdd", System.Globalization.CultureInfo.InvariantCulture);
                toDate = forceDatePartsToTwoCharacters(parsedDate.ToString("MM/dd/yyyy", System.Globalization.CultureInfo.InvariantCulture));
            }
        }
        else if (dateQualifier == "D8" && !string.IsNullOrEmpty(datePeriod))
        {
            if (!string.IsNullOrEmpty(datePeriod))
            {
                var parsedDate = DateTime.ParseExact(datePeriod, "yyyyMMdd", System.Globalization.CultureInfo.InvariantCulture);
                fromDate = forceDatePartsToTwoCharacters(parsedDate.ToString("MM/dd/yyyy", System.Globalization.CultureInfo.InvariantCulture));
            }
        }
    }
    private string GetDate(string date)
    {
        if (!string.IsNullOrEmpty(date))
        {
            var parsedDate = DateTime.ParseExact(date, "yyyyMMdd", System.Globalization.CultureInfo.InvariantCulture);
            return forceDatePartsToTwoCharacters(parsedDate.ToString("MM/dd/yyyy", System.Globalization.CultureInfo.InvariantCulture));
        }
        return null;
    }
