    private bool AddValidationErrorMessage(string msg)
    {
        CustomValidator val = new CustomValidator();
        val.IsValid = false;
        val.ErrorMessage = msg;
        val.ValidationGroup = "valOwnerInfo";
        this.Page.Validators.Add(val);
        //isGood = false;
        return false;
    }


    protected void btnCancel_Click(object sender, EventArgs e)
    {
        try
        {
            hdnPreviousClaimId.Value = string.Empty;
            hdnFrequencyCode.Value = CON.claimFrequencyCodes.standardClaim; //"7";
            if (!string.IsNullOrWhiteSpace(hdnClaimId.Value))
            {
                DataSet dsClaimsdata = new DataSet();
                if (rblClaimType.SelectedIndex == 0)
                    dsClaimsdata = ClaimsController.GetClaimsDentalDataDetails(Convert.ToInt32(hdnClaimId.Value));
                else if (rblClaimType.SelectedIndex == 1)
                    dsClaimsdata = ClaimsController.GetClaimsInstDataDetails(Convert.ToInt32(hdnClaimId.Value));
                else if (rblClaimType.SelectedIndex == 2)
                    dsClaimsdata = ClaimsController.GetClaimsProfDataDetails(Convert.ToInt32(hdnClaimId.Value));

                if (!Helper.HasRows(dsClaimsdata))
                {
                    Dictionary<string, string> parms = new Dictionary<string, string>();
                    parms.Add("Claim_Id", hdnClaimId.Value);
                    parms.Add("IS_deleted", "1");
                    parms.Add("Claim_Status", CON.ClaimStatus.Delete);


                    svc.UpdatePanelsData("claim_Adjudication_Summary_Status_Screen", parms);
                    rblClaimType.ClearSelection();
                    divallPanels.Visible = false;
                    ClearAll();
                    RefreshFilteredDropDown();
                    GetAdjustmentGroup();
                    //LoadclaimAdjudicationSummaryStatusScreen();
                    ViewState["CurrentTable"] = null;
                    divallPanels.Visible = false;
                    payerID.Value = "";
                    rblClaimType.ClearSelection();
                    ucOtherPayerPaidAmountServiceDetail.ClaimId = "";
                }
                else
                {
                    Dictionary<string, string> parms = new Dictionary<string, string>();
                    parms.Add("Claim_Id", hdnClaimId.Value);
                    parms.Add("Claim_Status", CON.ClaimStatus.Update);

                    svc.UpdatePanelsData("claim_Adjudication_Summary_Status_Screen", parms);
                    rblClaimType.ClearSelection();

                    divallPanels.Visible = false;
                    ClearAll();

                    RefreshFilteredDropDown();
                    // LoadclaimAdjudicationSummaryStatusScreen();
                    ViewState["CurrentTable"] = null;
                    divallPanels.Visible = false;
                    payerID.Value = "";
                }
            }
            else
            {
                rblClaimType.ClearSelection();

                divallPanels.Visible = false;
                ClearAll();
                RefreshFilteredDropDown();
                // LoadclaimAdjudicationSummaryStatusScreen();
                ViewState["CurrentTable"] = null;
                divallPanels.Visible = false;
                payerID.Value = "";
            }
            lblServiceDetailsError.Text = "";
            lblglobalerror.Text = "";
            lblServiceDetailICDError.Text = "";
            lblServiceDetailICDProcedureError.Text = "";
            ClearClaimScreenValuesToUserControls();
            clearSubmitfields();
            ClearPayerSequenceErrormessage();
            ClearAmbulanceInfoErrorMessage();
            Helper.PurgeSessionData();

            Response.Redirect("~/Process/SubmitClaim.aspx");
        }
        catch (Exception ex)
        {
            Logging log = new Logging(ThreadId, "Issue in Cancel button Click");
            log.CreateLogEntry(string.Format("{0} {1}", "Cancel button Click Related claim Id: ",
                hdnClaimId.Value.ToString() + "; having error: " + ex.Message.ToString() + " with stack trace: " + ex.StackTrace.ToString()), Logging.LogPriority.Error);
            //lblglobalerror.Text = "An error has occurred, please save your claim to submit it later";
        }
    }
