    private DataTable GetDiagSequences()
    {

        DataSet dataSet = _spa.GetSequenceType();
        DataTable dt = dataSet.Tables[0];

        var row_DaigSequences = from row in dt.AsEnumerable()
                                where row.Field<int>("PRIOR_AUTH_CLAIM_SEQUENCE_ID") == 1
               || row.Field<int>("PRIOR_AUTH_CLAIM_SEQUENCE_ID") == 2
                || row.Field<int>("PRIOR_AUTH_CLAIM_SEQUENCE_ID") == 4 || row.Field<int>("PRIOR_AUTH_CLAIM_SEQUENCE_ID") == 5
                                select row;

        DataTable dt_DaigSequences = row_DaigSequences.CopyToDataTable();
        return dt_DaigSequences;
        // Helper.LoadList(ddlDiaSequence, dt_DaigSequences, "PRIOR_AUTH_CLAIM_SEQUENCE_DESC", "PRIOR_AUTH_CLAIM_SEQUENCE_ID", true);
    }

