    protected void lnkSearch_Click(object sender, EventArgs e)
    {
        this.LoadData(null);
        lblSubmitClaimSearchPage.Text = "*Search";
        mltSubmitClaimSearchPage.ActiveViewIndex = 0;
        mpeSubmitClaimSearchPage.Show();


        LinkButton btn = (LinkButton)sender;
        string cmdName = btn.CommandArgument;

        if (cmdName == "cde_party_id")
        {
            var listData = new List<ReferringProviderSearch>();
            var referringproviderSearch = new ReferringProviderSearch
            {
                id_perf_prov = txtnpiReferringProvidersearch.Text,
                cde_party_id = txtmedicaididReferringProvidersearch.Text,
                nam_first = txtbussinReferringProvidersearch.Text,
                nam_last = txtfirstnamerefferingsearch.Text
            };
            if (ViewState["ReferringproviderSearch"] == null)
            {
                listData = new List<ReferringProviderSearch>();
                listData.Add(referringproviderSearch);
                ViewState["Supervisingprovidersearch"] = listData;
            }
            else
            {
                listData = (List<ReferringProviderSearch>)ViewState["ReferringproviderSearch"];
                if (listData != null)
                {
                    listData.Add(referringproviderSearch);
                    ViewState["ReferringproviderSearch"] = listData;
                }
            }

            gvSupervisingProvidersearch.DataSource = listData;
            gvSupervisingProvidersearch.DataBind();
        }
        else if (cmdName == "id_perf_prov")
        {
            var listData = new List<SupervisingProviderSearch>();
