            {
                id_perf_prov = txtnpiSupervisingProvidersearch.Text,

                cde_party_id = txtmedicaidSupervisingProvidersearch.Text,
                nam_first = txtbussinessSupervisingProvidersearch.Text,
                nam_last = txtfirsSupervisingProvidersearch.Text
            };
            if (ViewState["Supervisingprovidersearch"] == null)
            {
                listData = new List<SupervisingProviderSearch>();
                listData.Add(supervisingprovidersearch);
                ViewState["Supervisingprovidersearch"] = listData;
            }
            else
            {
                listData = (List<SupervisingProviderSearch>)ViewState["Supervisingprovidersearch"];
                if (listData != null)
                {
                    listData.Add(supervisingprovidersearch);
                    ViewState["Supervisingprovidersearch"] = listData;
                }
            }

            gvSupervisingProvidersearch.DataSource = listData;
            gvSupervisingProvidersearch.DataBind();
        }
        else if (cmdName == "id_perf_prov")
        {
            var listData = new List<RenderingProviderSearch>();
            var renderingprovidersearch = new RenderingProviderSearch
            {
                id_perf_prov = txtnpiRenderingSearch.Text,

                cde_party_id = txtmedicaidRenderingSearch.Text,
                nam_first = TextBox3.Text,
                nam_last = txtfirstRenderingSearch.Text
            };
