    public static string GetnpiCount(string RefNpi, string RefMedId, string ClaimType)
    {
        var data = string.Empty;

        DataTable dt = Claims.GetData(RefNpi, "", "", "");
        if (Helper.HasRows(dt))
        {
            if (dt.Rows.Count >= 2)
            {
                data = JsonConvert.SerializeObject("2");

            }

            else
            {
                data = Claims.NPITextChangedTest(RefNpi, RefMedId);

                if (!string.IsNullOrEmpty(RefMedId.ToString()))
                {
                    DataSet dsProviderInformation = Claims.LoadProviderInformation(RefMedId.ToString());
                    if (Helper.HasRows(dsProviderInformation.Tables[0]))
                    {
                        string entityTypeId = Helper.GetString("ENTITY_TYPE_ID", dsProviderInformation.Tables[0].Rows[0]).Trim();

                        if (entityTypeId != "1")
                        {
                            if (ClaimType.ToString() == CON.ClaimsType.Dental || ClaimType.ToString() == CON.ClaimsType.Professional || ClaimType.ToString() == CON.ClaimsType.Institutional)
                            {
                                data = JsonConvert.SerializeObject("Non-individual provider cannot be entered as referring provider");
                            }
                        }
                    }
                }
            }

        }
        return data;
    }

    protected void btnSubmit_Click(object sender, EventArgs e)
    {
        lblglobalerror.Text = "";
        if (rblClaimType.Text == "1")
        {
            var nnpi = ucAttendingPhysicianInformation.AttendingPhysicianNPI;
            if (!string.IsNullOrEmpty(nnpi))
            {
                if (GetnpiCount(nnpi, "", "") == "")
                {
                    lblglobalerror.Text = "*Incorrect NPI for Attending Physician Information";
                    ucAttendingPhysicianInformation.AttendingPhysician_MedicaidID = "";
                    ucAttendingPhysicianInformation.AttendingPhysician_FirstName = "";
                    ucAttendingPhysicianInformation.AttendingPhysician_LastName = "";
                    return;
                }
            }
        }
        Logging log = new Logging(ThreadId, "Issue in Submit button Click");
        log.CreateLogEntry(string.Format("{0} {1}", "Submit button Click Related claim Id:",
            hdnClaimId.Value.ToString() + "Started Submit operation"), Logging.LogPriority.Information);
        ExpandConditionBasePanels();
        log.CreateLogEntry(string.Format("{0} {1}", "Submit button Click Related claim Id:",
            hdnClaimId.Value.ToString() + "Completed ExpandConditionBasePanels method"), Logging.LogPriority.Information);
        SaveToDb(validationSummary, CON.ActionButtonType.Submit);
        log.CreateLogEntry(string.Format("{0} {1}", "Submit button Click Related claim Id:",
            hdnClaimId.Value.ToString() + "Completed SaveToDB method"), Logging.LogPriority.Information);
        Page.ClientScript.RegisterStartupScript(GetType(), "", "ValidateSubmit();", true);
        log.CreateLogEntry(string.Format("{0} {1}", "Submit button Click Related claim Id:",
            hdnClaimId.Value.ToString() + "Completed RegisterStartupScript method"), Logging.LogPriority.Information);
        Page.Validate("validateClaims");
        log.CreateLogEntry(string.Format("{0} {1}", "Submit button Click Related claim Id:",
            hdnClaimId.Value.ToString() + "Completed Validate method for validateClaims "), Logging.LogPriority.Information);
        if (!string.IsNullOrEmpty(hdnddlDestinationPayerID.Value.ToString()))
        {
            if (hdnddlDestinationPayerID.Value.Contains("-"))
            {
                ddlDestinationPayerID.SelectedIndex = ddlDestinationPayerID.Items.IndexOf(ddlDestinationPayerID.Items.FindByText(hdnddlDestinationPayerID.Value.ToString()));
            }
            else
            {
                ddlDestinationPayerID.SelectedIndex = ddlDestinationPayerID.Items.IndexOf(ddlDestinationPayerID.Items.FindByValue(hdnddlDestinationPayerID.Value.ToString()));
            }

        }
        bool validateRequiredfields = validateRequireFields();

        log.CreateLogEntry(string.Format("{0} {1}", "Submit button Click Related claim Id:",
           hdnClaimId.Value.ToString() + "Completed validateRequireFields method"), Logging.LogPriority.Information);
        if (ValidateClaimsData() && Page.IsValid && validateRequiredfields && (hdnErrorMsg.Value == "false"))
        {
            log.CreateLogEntry(string.Format("{0} {1}", "Submit button Click Related claim Id:",
                hdnClaimId.Value.ToString() + "Completed to check  ValidateClaimsData method,IsValid,validateRequiredfields"), Logging.LogPriority.Information);
            if (validateRequiredfields == true)
            {
                log.CreateLogEntry(string.Format("{0} {1}", "Submit button Click Related claim Id:",
                   hdnClaimId.Value.ToString() + "Completed to check  File status for SendClaimAttachment method"), Logging.LogPriority.Information);
                if (hdnFrequencyCode.Value != CON.claimFrequencyCodes.adjustClaim && hdnFrequencyCode.Value != CON.claimFrequencyCodes.voidClaim)
                {
                    hdnFrequencyCode.Value = CON.claimFrequencyCodes.standardClaim; //"1";
                }
                OtherpayerInformationExpand();
                SubmitClaim("P");
                if (!string.IsNullOrEmpty(txtICN2.Text) && txtstatus2.Text != "PENDING SUBMISSION")
                {
                    DeletClaimID(hdnClaimId.Value);
                }
            }
        }
        ucServiceInformationInstitutional.AdmitSourceEnableStatus();
    }
    protected void btnReSubmit_Click(object sender, EventArgs e)
    {
        try
        {
            hdnddlDestinationPayerID.Value = ddlDestinationPayerID.SelectedValue.ToString();
            lblglobalerror.Text = "";
            if (rblClaimType.SelectedValue == CON.ClaimsType.Dental)
            {
                updateClaimPredetermination();
            }
            if (!ValidateData()) return;
            DeletClaimID(hdnClaimId.Value);
            isPageEditEnabled = true;
            lblServiceDetailsError.Text = "";
            clearInfoForCopy();
            ShowHideButtons();
            CARCRARCInformation.ClearGrid();
            RelatedICNScreen.ClearGrid();
            ReviewNotes.ClearGrid();
            txtCaimStatus2.Text = string.Empty;
            txtICN.Text = string.Empty;
            txtTotalPaidAmount.Text = string.Empty;
            txtAdjudicationDate.Text = string.Empty;
            txtClaimSubmissionDate.Text = string.Empty;
            txtTotalCharges1.Text = string.Empty;
            txtClaimPaidDate.Text = string.Empty;
            txtCopayAmount.Text = string.Empty;
            btnSave.Visible = true;
            btnSubmit.Visible = true;
            btncancel.Visible = true;
            bntAdjust.Visible = false;
            btnCopy.Visible = false;
            btnVoid.Visible = false;
            txtPaidAmount.Text = string.Empty;
            hdnClaimId.Value = string.Empty;
            if (!string.IsNullOrEmpty(txtstatus2.Text.ToString()))
            {
                Session["ClaimStatus"] = txtstatus2.Text.ToString();
            }
            SaveAdjudicationSummaryData();
            LoadclaimAdjudicationSummaryStatusScreen();
            SaveToDbOnAdjust();
            txtPaidAmount.Text = string.Empty;
            ddlDestinationPayerResponsibilitySequence.Enabled = true;
            ddlPrimaryDestinationPayer.Enabled = true;
            rblClaimType.Enabled = false;
            if (!string.IsNullOrEmpty(ddlDestinationPayerResponsibilitySequence.SelectedValue))
            {
                ucOtherPayerInformation.ClearData(ddlDestinationPayerResponsibilitySequence.SelectedValue);
            }
            AdjudicationError.ClearGrid();
            ucServiceDetailsDental.HideDivsForReSubmitCopyandAdjust();
            InstitutionalServiceDetails.HideDivsForReSubmitCopyandAdjust();
            ProfessionalServiceLineDetails.HideDivsForReSubmitCopyandAdjust();
            ucServiceInformationInstitutional.HideDivsForReSubmitCopyandAdjust();
            divClaimAdjudication.Visible = false;
            OtherpayerInformationExpand();
            ucServiceInformationInstitutional.AdmitSourceEnableStatus();
            //OHPNM-13495
            ResetTypeofBill();

        }
        catch (Exception ex)
        {
            Logging log = new Logging(ThreadId, "Issue in Submit button Click");
            log.CreateLogEntry(string.Format("{0} {1}", "Submit button Click Related claim Id: ",
                hdnClaimId.Value.ToString() + "; having error: " + ex.Message.ToString() + " with stack trace: " + ex.StackTrace.ToString()), Logging.LogPriority.Error);
        }

    }

