    public void ResetTypeofBill()
    {
        string lastDigtOfTypeofBill = ucServiceInformationInstitutional.TypeofBill;
        if (!string.IsNullOrEmpty(lastDigtOfTypeofBill))
        {
            string frequencycode = lastDigtOfTypeofBill[lastDigtOfTypeofBill.Length - 1].ToString();
            if (lastDigtOfTypeofBill.EndsWith("7") || lastDigtOfTypeofBill.EndsWith("8"))
            {
                lastDigtOfTypeofBill = lastDigtOfTypeofBill.Remove(lastDigtOfTypeofBill.Length - 1, 1);
                lastDigtOfTypeofBill = lastDigtOfTypeofBill + "1";
                ucServiceInformationInstitutional.TypeofBill = lastDigtOfTypeofBill;
            }
        }
    }
