        //Tooth & Surface Info
        datatable = new DataTable();
        datatable.Columns.Add("Claims_Tooth_and_Surface_Information_Id");
        datatable.Columns.Add("Service_Line");
        datatable.Columns.Add("Tooth_Number");
        datatable.Columns.Add("Toothsurface1");
        datatable.Columns.Add("Toothsurface2");
        datatable.Columns.Add("Toothsurface3");
        datatable.Columns.Add("Toothsurface4");
        datatable.Columns.Add("Toothsurface5");
