        foreach (XElement xelement in response.Root.Element(soapenv + "Body").Element(xnamespace + "AddUpdateClaimsResponse").Element(xnamespace + claimElementName).Element(xnamespace + "BHTContainter").Element(xnamespace + "PatientHierarchical_2000C").Element(xnamespace + "ClaimDetails_2300").Element("ServiceLineDetails_2400").Elements())
        {
            datatable.Rows.Add(i.ToString(), xelement.Element(xnamespace + "ServiceLineNumber_2400").Element(xnamespace + "LX01_AssignedNumber").Value.ToString(), //Service_Line
                        xelement.Descendants(xnamespace + "TOO02_ToothCode").FirstOrDefault().Value.ToString(), //Tooth_Number
