                        xelement.Descendants(xnamespace + "TOO03_3_ToothSurfaceCode").FirstOrDefault().Value.ToString(),
                        xelement.Descendants(xnamespace + "TOO03_4_ToothSurfaceCode").FirstOrDefault().Value.ToString(),
                        xelement.Descendants(xnamespace + "TOO03_5_ToothSurfaceCode").FirstOrDefault().Value.ToString());
            i++;
        }
        dataset = new DataSet();
        dataset.Tables.Add(datatable);
        ucToothQuadrant.ClaimId = hdnClaimId.Value;
        ucToothQuadrant.dataSetToothQuadrant = dataset;
    }

