    public DataSet GetAttach()
    {
        DataSet dsAttachmnets = new DataSet();
        if (!string.IsNullOrEmpty(hdnClaimId.Value))
        {
            Dictionary<string, string> parms = new Dictionary<string, string>();
            parms.Add("Claim_ID", hdnClaimId.Value);
            parms.Add("Claim_Type_ID", rblClaimType.SelectedValue.ToString());
            dsAttachmnets = spa.SelectPanelsData("Claims_OutBound_Document_Uploads", parms);

        }
        return dsAttachmnets;
    }

    public DataSet GetDoc(string DocId)
    {
        DataSet dsAttachmnets = new DataSet();
        Dictionary<string, string> parms = new Dictionary<string, string>();
        if (rblClaimType.SelectedValue == "0")
        {
            parms.Add("DOCUMENT_CLAIM_DESC", "Dental");
        }
        else if (rblClaimType.SelectedValue == "1")
        {
            parms.Add("DOCUMENT_CLAIM_DESC", "Institutional");
        }
        else if (rblClaimType.SelectedValue == "2")
        {
            parms.Add("DOCUMENT_CLAIM_DESC", "Professional");
        }
        parms.Add("DOCUMENT_TYPE_ID", DocId);
        dsAttachmnets = spa.SelectPanelsData("Claim_Attachment_Type", parms);

        return dsAttachmnets;
    }

    private String translateResponsibilityCode(String tableIndex)
    {
        String responsibilityCode = "";
        switch (tableIndex)
        {
            case "1":
                // Primary
                responsibilityCode = "P";
                break;
            case "2":
                // Secondary
                responsibilityCode = "S";
                break;
            case "3":
                // Tertiary
                responsibilityCode = "T";
                break;
            case "4":
                responsibilityCode = "A";
                break;
            case "5":
                responsibilityCode = "B";
                break;
            case "6":
                responsibilityCode = "C";
                break;
            case "7":
                responsibilityCode = "D";
                break;
            case "8":
                responsibilityCode = "E";
                break;
            case "9":
                responsibilityCode = "F";
                break;
            default:
                // Unknown
                responsibilityCode = tableIndex;
                break;
        }
        return responsibilityCode;
    }
    private string selectEntityTypefromNPI(string NPI)
    {
        DataSet dsrend = new DataSet();
        List<SqlParameter> rendparams = new List<SqlParameter>();
        string renderingEntityTypeIdNPI = string.Empty;
        rendparams.Add(SqlParms.CreateParameter("NPI", DbType.String, NPI, false));
        dsrend = DataAccess.ExecuteStoredProcedure("usp_SelectEntityTypeFromNPI", rendparams, "selectEntityTypefromNPI");
        if (Helper.HasRows(dsrend))
        {
            renderingEntityTypeIdNPI = Helper.GetString("ENTITY_TYPE_ID", dsrend.Tables[0].Rows[0]).Trim();
            return renderingEntityTypeIdNPI;
        }
        return renderingEntityTypeIdNPI;

    }
    private string selectEntityTypefromMedicaidID(string MedicaidID)
    {
        DataSet dsRenderingInformation = LoadProviderInformation(MedicaidID);
        string renderingEntityTypeId = string.Empty;
        if (Helper.HasRows(dsRenderingInformation))
        {
            renderingEntityTypeId = Helper.GetString("ENTITY_TYPE_ID", dsRenderingInformation.Tables[0].Rows[0]).Trim();
            return renderingEntityTypeId;
        }
        return renderingEntityTypeId;
    }

    private XDocument BuildDentalSoapEnvelope()
    {
        String namespacePrefix = "den";
        XNamespace xnamespace = den;
        String claimElementName = "DentalClaim837";

        XDocument soapEnvelopeDocument = new XDocument(
            new XDeclaration("1.0", "utf-8", "yes"));

        XElement Envelope = new XElement(soapenv + "Envelope");
        Envelope.Add(new XAttribute(XNamespace.Xmlns + "soapenv", soapenv.ToString()));
        Envelope.Add(new XAttribute(XNamespace.Xmlns + namespacePrefix, xnamespace.ToString()));
        Envelope.Add(new XAttribute(XNamespace.Xml + "space", "preserve"));

        XElement Header = new XElement(soapenv + "Header");

        int TRANSACTION_TYPE_ID = 1;
        int TRANSACTION_SUB_TYPE_ID = 1;
        long TRANSACTION_CONTROL_ID = 0;

        List<SqlParameter> parameters = new List<SqlParameter>();
        DataSet transaction_control = new DataSet();
        string transaction_result;
        parameters.Add(SqlParms.CreateParameter("TRANSACTION_TYPE_ID", DbType.Int64, TRANSACTION_TYPE_ID, false));
        parameters.Add(SqlParms.CreateParameter("TRANSACTION_SUB_TYPE_ID", DbType.Int64, TRANSACTION_SUB_TYPE_ID, false));
        parameters.Add(SqlParms.CreateParameter("DT_ASSIGNED", DbType.DateTime, DateTime.Now.ToString(), true));
        parameters.Add(SqlParms.CreateParameter("CREATED_ON_DATE_TIME", DbType.DateTime, DateTime.Now.ToString(), true));
        parameters.Add(SqlParms.CreateParameter("CREATED_BY_USER", DbType.Guid, Helper.GetUserId(HttpContext.Current.User.Identity.Name).ToString(), false));
        parameters.Add(SqlParms.CreateParameter("LAST_MODIFIED_DATE_TIME", DbType.DateTime, DateTime.Now.ToString(), true));
        parameters.Add(SqlParms.CreateParameter("LAST_MODIFIED_USER", DbType.Guid, Helper.GetUserId(HttpContext.Current.User.Identity.Name).ToString(), false));
        transaction_control = DataAccess.ExecuteStoredProcedure("usp_InsertSelectTransactionControlData", parameters, "TRANSACTION_CONTROL_ID_VALUE", SqlDbType.Int, out transaction_result, 0);

        if (!string.IsNullOrEmpty(transaction_result))
        {
            TRANSACTION_CONTROL_ID = Convert.ToInt64(transaction_result);

            int leading_zeros = 9 - transaction_result.Length;
            if (leading_zeros > 0)
            {
                transaction_result = transaction_result.PadLeft(9, '0');
            }
        }

        XElement Security = new XElement(wsse + "Security");
        Security.Add(new XAttribute(XNamespace.Xmlns + "wsse", wsse.ToString()));
        Security.Add(new XAttribute(XNamespace.Xmlns + "wsu", wsu.ToString()));

        XElement UsernameToken = new XElement(wsse + "UsernameToken");
        UsernameToken.Add(new XAttribute(wsu + "Id", "SecurityToken-514dc28b-a876-40a4-89d3-17a81724400c"));

        XElement Username = new XElement(wsse + "Username", AppSettings.Get("ClaimsWSUserName"));
        string client_secret = "";
        string secretName = "ClaimsWSPassword_OH_PNM_";
        try
        {
            var secret = new SecretsManager(AppSettings.Get("SecretsRegion"));
            string environmentName = AppSettings.Get("EnvironmentName").Replace("OH_PNM_", "");
            var secretResult = secret.GetSuperSecretPassword(String.Concat(environmentName, "/WebService/DBPassword"));
            secretResult.Wait();

            client_secret = secretResult.Result[String.Concat(secretName, environmentName)];
        }
        catch (Exception ex)
        {
            ThreadId = Guid.NewGuid();
            Logging log = new Logging(ThreadId, "Secret Retrieval");
            client_secret = "NO SECRET CONNECTIVITY";
            client_secret += " ~|~ ";
            client_secret += AppSettings.Get("SecretsRegion");
            client_secret += " ~|~ ";
            client_secret += String.Concat(AppSettings.Get("EnvironmentName").Replace("OH_PNM_", ""), "/WebService/DBPassword");
            client_secret += " ~|~ ";
            client_secret += String.Concat(secretName, AppSettings.Get("EnvironmentName").Replace("OH_PNM_", ""));
            client_secret += " ~|~ ";
            client_secret += ex.Message;
            log.CreateLogEntry(string.Format("Failure Gathering Secret: Region: {0}; Environment {1}; Dictionary: {2}; Secret: {3}; ErrorMessage: {4}; Stack Trace: {5}", AppSettings.Get("SecretsRegion"), AppSettings.Get("EnvironmentName").Replace("OH_PNM_", ""), String.Concat(AppSettings.Get("EnvironmentName").Replace("OH_PNM_", ""), "/WebService/DBPassword"), String.Concat(secretName, AppSettings.Get("EnvironmentName").Replace("OH_PNM_", "")), ex.Message, ex.StackTrace), Logging.LogPriority.Error);
        }
        XElement Password = new XElement(wsse + "Password", client_secret);
        Password.Add(new XAttribute("Type", "http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-username-token-profile-1.0#PasswordText"));

        XElement Nonce = new XElement(wsse + "Nonce", "zZvdpyeVSy/WJCJm2Ydnrw==");
        Nonce.Add(new XAttribute("EncodingType", "http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-soap-message-security-1.0#Base64Binary"));
        XElement Created = new XElement(wsu + "Created", DateTime.Now.ToString("yyyyMMddHHmmss"));
        UsernameToken.Add(Username);
        UsernameToken.Add(Password);
        UsernameToken.Add(Nonce);
        UsernameToken.Add(Created);
        Security.Add(UsernameToken);
        Header.Add(Security);
        Envelope.Add(Header);

        XElement Body = new XElement(soapenv + "Body");
        XElement AddUpdateClaimsRequest = new XElement(xnamespace + "AddUpdateClaimsRequest");
        string billingmedicaid = this.WorkflowPage.MedicaidID; //((Label)Parent.FindControl("lblProMedicaidID2")).Text;

        // JLB Adding Nested if statements to allow for easier reading while also working outside of an XDocument constructor
        XElement MessageHeader = new XElement(xnamespace + "MessageHeader");
        if (true) // MessageHeader 
        {
            MessageHeader.Add(new XElement(xnamespace + "BusinessFlow", "AddUpdateClaims"));
            MessageHeader.Add(new XElement(xnamespace + "StateCode", "OH"));
            MessageHeader.Add(new XElement(xnamespace + "RequestorSystem", "PNM"));
            XElement SubscriberSystem = new XElement(xnamespace + "SubscriberSystem");
            XElement ErrorCode = new XElement(xnamespace + "ErrorCode");
            if (ddlPrimaryDestinationPayer.SelectedItem.Text == "Ohio Department of Medicaid")
            {
                SubscriberSystem.Add(new XElement(xnamespace + "Subscriber", "FI"));
            }
            else
            {
                SubscriberSystem.Add(new XElement(xnamespace + "Subscriber", "EDI"));
            }
            MessageHeader.Add(SubscriberSystem);
            MessageHeader.Add(new XElement(xnamespace + "ModuleTransactionId", billingmedicaid.PadRight(9, '0')));
            MessageHeader.Add(new XElement(xnamespace + "AdditionalModuleTransactionId", Guid.NewGuid().ToString()));
            MessageHeader.Add(new XElement(xnamespace + "RequestTimestamp", Convert.ToDateTime(DateTime.Now.ToString("yyyy-MM-ddTHH:mm:ss"))));
            MessageHeader.Add(new XElement(xnamespace + "SITransactionKey", ProviderManagementHelper.GetUniqueKey(32)));

        }
        AddUpdateClaimsRequest.Add(MessageHeader);

        DataSet dsTaxonomyCode = new DataSet();
        Dictionary<string, string> parms = new Dictionary<string, string>();
        parms.Add("REG_ID", this.WorkflowPage.RegistrationId.ToString());
        dsTaxonomyCode = svc.SelectPanelsData("taxonomycodeforbillingprovider", parms);
        DataSet dsProviderInformation = LoadProviderInformation(this.WorkflowPage.MedicaidID);
        string entityTypeId = Helper.GetString("ENTITY_TYPE_ID", dsProviderInformation.Tables[0].Rows[0]).Trim();
        DataTable dtTradingPartnerIDDental = FetchTradingPartnerID().Tables[0];
        XElement Claim = new XElement(xnamespace + claimElementName);
        if (true) // Claim
        {
            XElement InterchangeControlHeader = new XElement(xnamespace + "InterchangeControlHeader");
            if (true) // InterchangeControlHeader
            {
                InterchangeControlHeader.Add(new XElement(xnamespace + "ISA01_AuthorizationInformationQualifier", "00"));
                XElement ISA01_AuthoriztionInformation = new XElement(xnamespace + "ISA02_AuthorizationInformation");
                InterchangeControlHeader.Add(new XElement(xnamespace + "ISA02_AuthorizationInformation", "          "));
                InterchangeControlHeader.Add(new XElement(xnamespace + "ISA03_SecurityInformationQualifier", "00"));
                InterchangeControlHeader.Add(new XElement(xnamespace + "ISA04_SecurityInformation", "          "));
                InterchangeControlHeader.Add(new XElement(xnamespace + "ISA05_InterchangeIdQualifier", "ZZ"));
                InterchangeControlHeader.Add(new XElement(xnamespace + "ISA06_InterchangeSenderId", "MMISODJFS".PadRight(15)));
                InterchangeControlHeader.Add(new XElement(xnamespace + "ISA07_InterchangeIdQualifier", "ZZ"));
                InterchangeControlHeader.Add(new XElement(xnamespace + "ISA08_InterchangeReceiverId", (dtTradingPartnerIDDental.Rows[0]["Trading_PartnerID"].ToString().PadRight(15))));
                InterchangeControlHeader.Add(new XElement(xnamespace + "ISA09_InterchangeDate", DateTime.Now.ToString("yyMMdd")));
                InterchangeControlHeader.Add(new XElement(xnamespace + "ISA10_InterchangeTime", DateTime.Now.ToString("HHmm")));
                InterchangeControlHeader.Add(new XElement(xnamespace + "ISA11_RepetitionSeparator", "^"));
                InterchangeControlHeader.Add(new XElement(xnamespace + "ISA12_InterchangeControlVersionNumber", "00501"));
                InterchangeControlHeader.Add(new XElement(xnamespace + "ISA13_InterchangeControlNumber", transaction_result));
                InterchangeControlHeader.Add(new XElement(xnamespace + "ISA14_AcknowledgementRequested", "1"));
                InterchangeControlHeader.Add(new XElement(xnamespace + "ISA15_InterchangeUsageIndicator", "T"));
                InterchangeControlHeader.Add(new XElement(xnamespace + "ISA16_ComponentElementSeparator", ":"));
            }
            // JLB - Remove this optional element without values
            Claim.Add(InterchangeControlHeader);

            XElement FunctionalGroupHeader = new XElement(xnamespace + "FunctionalGroupHeader");
            if (true) // FuncationalGroupController
            {
                FunctionalGroupHeader.Add(new XElement(xnamespace + "GS01_FunctionalIdentifierCode", "HC"));
                FunctionalGroupHeader.Add(new XElement(xnamespace + "GS02_ApplicationSendersCode", "MMISODJFS"));
                FunctionalGroupHeader.Add(new XElement(xnamespace + "GS03_ApplicationReceiversCode", (dtTradingPartnerIDDental.Rows[0]["Trading_PartnerID"].ToString())));
                FunctionalGroupHeader.Add(new XElement(xnamespace + "GS04_Date", DateTime.Now.ToString("yyyyMMdd")));
                FunctionalGroupHeader.Add(new XElement(xnamespace + "GS05_Time", DateTime.Now.ToString("HHmmss")));
                FunctionalGroupHeader.Add(new XElement(xnamespace + "GS06_GroupControlNumber", "000000009"));
                FunctionalGroupHeader.Add(new XElement(xnamespace + "GS07_ResponsibleAgencyCode", "X"));
                FunctionalGroupHeader.Add(new XElement(xnamespace + "GS08_VersionReleaseIndustryIdentifierCode", "005010X224A2"));
            }
            // JLB - Remove this optional element without values
            Claim.Add(FunctionalGroupHeader);

            XElement TransactionSetHeader = new XElement(xnamespace + "TransactionSetHeader");
            if (true) // TransactionSetHeader
            {
                TransactionSetHeader.Add(new XElement(xnamespace + "ST01_TransactionSetIdentifierCode", "837"));
                TransactionSetHeader.Add(new XElement(xnamespace + "ST02_TransactionSetControlNumber", "0001"));
                TransactionSetHeader.Add(new XElement(xnamespace + "ST03_ImplementationConventionReference", "005010X224A2"));
            }
            // JLB - Remove this optional element without values
            Claim.Add(TransactionSetHeader);


            XElement container = new XElement(xnamespace + "BHTContainter");
            if (true) // container BHTContainter
            {
                XElement BeginningOfHierarchicalTransaction = new XElement(xnamespace + "BeginningOfHierarchicalTransaction");
                if (true) // BeginningOfHierarchicalTransaction
                {
                    BeginningOfHierarchicalTransaction.Add(new XElement(xnamespace + "BHT01_HierarchicalStructureCode", "0019"));
                    BeginningOfHierarchicalTransaction.Add(new XElement(xnamespace + "BHT02_TransactionSetPurposeCode", "00"));
                    BeginningOfHierarchicalTransaction.Add(new XElement(xnamespace + "BHT03_ReferenceIdentification", billingmedicaid.PadRight(9, '0')));
                    BeginningOfHierarchicalTransaction.Add(new XElement(xnamespace + "BHT04_Date", DateTime.Now.ToString("yyyyMMdd")));
                    BeginningOfHierarchicalTransaction.Add(new XElement(xnamespace + "BHT05_Time", DateTime.Now.ToString("HHmmss")));
                    BeginningOfHierarchicalTransaction.Add(new XElement(xnamespace + "BHT06_TransactionTypeCode", "CH"));
                }
                // JLB - remove this optional element without values
                container.Add(BeginningOfHierarchicalTransaction);

                XElement SubmitterDetails_1000A = new XElement(xnamespace + "SubmitterDetails_1000A");
                if (true) //SubmitterDetails_1000A
                {
                    XElement SubmitterName_1000A = new XElement(xnamespace + "SubmitterName_1000A");
