    private XDocument BuildProfessionalSoapEnvelope()
    {
        String namespacePrefix = "prof";
        XNamespace xnamespace = prof;
        String claimElementName = "ProfessionalClaim837";

        XDocument soapEnvelopeDocument = new XDocument(
            new XDeclaration("1.0", "utf-8", "yes"));

        XElement Envelope = new XElement(soapenv + "Envelope");
        Envelope.Add(new XAttribute(XNamespace.Xmlns + "soapenv", soapenv.ToString()));
        Envelope.Add(new XAttribute(XNamespace.Xmlns + namespacePrefix, xnamespace.ToString()));
        Envelope.Add(new XAttribute(XNamespace.Xml + "space", "preserve"));

        XElement Header = new XElement(soapenv + "Header");

        int TRANSACTION_TYPE_ID = 1;
        int TRANSACTION_SUB_TYPE_ID = 3;
        long TRANSACTION_CONTROL_ID = 0;

        List<SqlParameter> parameters = new List<SqlParameter>();
        DataSet transaction_control = new DataSet();
        string transaction_result;
        parameters.Add(SqlParms.CreateParameter("TRANSACTION_TYPE_ID", DbType.Int64, TRANSACTION_TYPE_ID, false));
        parameters.Add(SqlParms.CreateParameter("TRANSACTION_SUB_TYPE_ID", DbType.Int64, TRANSACTION_SUB_TYPE_ID, false));
        parameters.Add(SqlParms.CreateParameter("DT_ASSIGNED", DbType.DateTime, DateTime.Now.ToString(), true));
        parameters.Add(SqlParms.CreateParameter("CREATED_ON_DATE_TIME", DbType.DateTime, DateTime.Now.ToString(), true));
        parameters.Add(SqlParms.CreateParameter("CREATED_BY_USER", DbType.Guid, Helper.GetUserId(HttpContext.Current.User.Identity.Name).ToString(), false));
        parameters.Add(SqlParms.CreateParameter("LAST_MODIFIED_DATE_TIME", DbType.DateTime, DateTime.Now.ToString(), true));
        parameters.Add(SqlParms.CreateParameter("LAST_MODIFIED_USER", DbType.Guid, Helper.GetUserId(HttpContext.Current.User.Identity.Name).ToString(), false));
        transaction_control = DataAccess.ExecuteStoredProcedure("usp_InsertSelectTransactionControlData", parameters, "TRANSACTION_CONTROL_ID_VALUE", SqlDbType.Int, out transaction_result, 0);

        if (!string.IsNullOrEmpty(transaction_result))
        {
            TRANSACTION_CONTROL_ID = Convert.ToInt64(transaction_result);

            int leading_zeros = 9 - transaction_result.Length;
            if (leading_zeros > 0)
            {
                transaction_result = transaction_result.PadLeft(9, '0');
            }
        }

        XElement Security = new XElement(wsse + "Security");
        Security.Add(new XAttribute(XNamespace.Xmlns + "wsse", wsse.ToString()));
        Security.Add(new XAttribute(XNamespace.Xmlns + "wsu", wsu.ToString()));

        XElement UsernameToken = new XElement(wsse + "UsernameToken");
        UsernameToken.Add(new XAttribute(wsu + "Id", "SecurityToken-514dc28b-a876-40a4-89d3-17a81724400c"));

        XElement Username = new XElement(wsse + "Username", AppSettings.Get("ClaimsWSUserName"));
        string client_secret = "";
        string secretName = "ClaimsWSPassword_OH_PNM_";
        try
        {
            var secret = new SecretsManager(AppSettings.Get("SecretsRegion"));
            string environmentName = AppSettings.Get("EnvironmentName").Replace("OH_PNM_", "");
            var secretResult = secret.GetSuperSecretPassword(String.Concat(environmentName, "/WebService/DBPassword"));
            secretResult.Wait();

            client_secret = secretResult.Result[String.Concat(secretName, environmentName)];
        }
        catch (Exception ex)
        {
            ThreadId = Guid.NewGuid();
            Logging log = new Logging(ThreadId, "Secret Retrieval");
            client_secret = "NO SECRET CONNECTIVITY";
            client_secret += " ~|~ ";
            client_secret += AppSettings.Get("SecretsRegion");
            client_secret += " ~|~ ";
            client_secret += String.Concat(AppSettings.Get("EnvironmentName").Replace("OH_PNM_", ""), "/WebService/DBPassword");
            client_secret += " ~|~ ";
            client_secret += String.Concat(secretName, AppSettings.Get("EnvironmentName").Replace("OH_PNM_", ""));
            client_secret += " ~|~ ";
            client_secret += ex.Message;
