    private string GetDiagnosisTypeCode(string elementName, string icdVersion, string seq = "")
    {
        string diagnosisTypeCode = string.Empty;
        string tagName = elementName.Substring(elementName.IndexOf("_") + 1);
        if (tagName == "DiagnosisTypeCode" && seq == "01")
        {
            diagnosisTypeCode = (icdVersion.ToUpper() == "ICD 10") ? "ABK" : "BK";
        }
        else if ((tagName.Substring(tagName.IndexOf("_") + 1) == "DiagnosisTypeCode" || tagName.Substring(tagName.IndexOf("_") + 1) == "CodeListQualifierCode") && seq == "01")
        {
            diagnosisTypeCode = (icdVersion.ToUpper() == "ICD 10") ? "ABK" : "BK";
        }
        else
        {
            diagnosisTypeCode = (icdVersion.ToUpper() == "ICD 10") ? "ABF" : "BF";
        }

        return diagnosisTypeCode;
    }

    private void SubmitClaim(string resType)
    {
        Logging log = new Logging(ThreadId, "Submit Cliam Xml Generation");
        log.CreateLogEntry(string.Format("{0} {1}", "Submitgenerating XML  Related claim Id:",
            hdnClaimId.Value.ToString() + "Xml Generation Started"), Logging.LogPriority.Information);
        AddUPdateClaimsRequestResponse claimResponse = new AddUPdateClaimsRequestResponse { ClaimResponse = AddClaimResponse("Success", "Save") };

        XNamespace xnamespace = den;
        XDocument xDocument = new XDocument();

        if (rblClaimType.SelectedItem.Text.Equals("Dental", StringComparison.OrdinalIgnoreCase))
        {
            log.CreateLogEntry(string.Format("{0} {1}", "Submitgenerating XML  Related claim Id:",
            hdnClaimId.Value.ToString() + "Xml Generation Started for Dental AddUpdate"), Logging.LogPriority.Information);
            xnamespace = den;
            xDocument = BuildDentalSoapEnvelope();

        }
        else if (rblClaimType.SelectedItem.Text.Equals("Professional", StringComparison.OrdinalIgnoreCase))
        {
            log.CreateLogEntry(string.Format("{0} {1}", "Submitgenerating XML  Related claim Id:",
            hdnClaimId.Value.ToString() + "Xml Generation Started for BuildProfessionalSoapEnvelope of AddUpdate"), Logging.LogPriority.Information);
            xnamespace = prof;
            xDocument = BuildProfessionalSoapEnvelope();
        }
        else if (rblClaimType.SelectedItem.Text.Equals("Institutional", StringComparison.OrdinalIgnoreCase))
        {
            log.CreateLogEntry(string.Format("{0} {1}", "Submitgenerating XML  Related claim Id:",
            hdnClaimId.Value.ToString() + "Xml Generation Started for BuildInstitutionalSoapEnvelope of AddUpdate"), Logging.LogPriority.Information);
            xnamespace = inst;
            xDocument = BuildInstitutionalSoapEnvelope();
        }
        // OHPNM-7054 remove empty nodes
        xDocument.Descendants()
       .Where(a => a.IsEmpty || String.IsNullOrWhiteSpace(a.Value.Replace("          ", "~~~~~~~~~~")))
       .Remove();

        // WebResponse response = ClaimsServiceAgent.SubmitClaim(xDocument, rblClaimType.SelectedItem.Text);
        String response = null;
        int transactionID = 0;
        try
        {
            response = ClaimsServiceAgent.SubmitClaim(xDocument, rblClaimType.SelectedItem.Text);
            // hard-coded XML AddUpdateResponse goes here
            log.CreateLogEntry(string.Format("{0} {1}", "Submitgenerating XML  Related claim Id:",
           hdnClaimId.Value.ToString() + "Xml Generation done and response get for AddUpdate"), Logging.LogPriority.Information);

            if (response.Contains(@"<soapenv:Envelope"))
            {
                response = response.Substring(response.IndexOf(@"<soapenv:Envelope"));

                XDocument resultEnvelope = XDocument.Parse(response);
                try
                {
                    var RequestorSystem = xDocument.Root.Element(soapenv + "Body").Element(xnamespace + "AddUpdateClaimsRequest").Element(xnamespace + "MessageHeader").Element(xnamespace + "RequestorSystem").Value;
                    var SubscriberSystem = xDocument.Root.Element(soapenv + "Body").Element(xnamespace + "AddUpdateClaimsRequest").Element(xnamespace + "MessageHeader").Element(xnamespace + "SubscriberSystem").Element(xnamespace + "Subscriber").Value;
                    var SITransactionKey = "";
                    var ResponseCode = "";
                    var ResponseType = "";
                    var ResponseMessage = "";
                    var ResponseDetails = "";
                    try
                    {
                        var ModuleTransactionId = ""; //  resultEnvelope.Root.Element(soapenv + "Body").Element(xnamespace + "AddUpdateClaimsResponse").Element(xnamespace + "ResponseHeader").Element(xnamespace + "ModuleTransactionId").Value;
                        var AdditionalModuleTransactionId = ""; // resultEnvelope.Root.Element(soapenv + "Body").Element(xnamespace + "AddUpdateClaimsResponse").Element(xnamespace + "ResponseHeader").Element(xnamespace + "AdditionalModuleTransactionId").Value;
                        if (SubscriberSystem == "EDI")
                        {
                            SITransactionKey = resultEnvelope.Root.Element(soapenv + "Body").Element(xnamespace + "AddUpdateClaimsResponse").Element(xnamespace + "ResponseHeader").Element(xnamespace + "SITransactionKey").Value;
                            ResponseCode = resultEnvelope.Root.Element(soapenv + "Body").Element(xnamespace + "AddUpdateClaimsResponse").Element(xnamespace + "ResponseHeader").Element(xnamespace + "ResponseCode").Value;
                            ResponseType = resultEnvelope.Root.Element(soapenv + "Body").Element(xnamespace + "AddUpdateClaimsResponse").Element(xnamespace + "ResponseHeader").Element(xnamespace + "ResponseType").Value;
                            ResponseMessage = resultEnvelope.Root.Element(soapenv + "Body").Element(xnamespace + "AddUpdateClaimsResponse").Element(xnamespace + "ResponseHeader").Element(xnamespace + "ResponseMessage").Value;
                            ResponseDetails = resultEnvelope.Root.Element(soapenv + "Body").Element(xnamespace + "AddUpdateClaimsResponse").Element(xnamespace + "ResponseHeader").Element(xnamespace + "ResponseDetails").Value;
                        }
                        else
                        {
                            // FI Qualifies the item level namespace, but does not invoke it

                            try
                            {
                                SITransactionKey = resultEnvelope.Root.Element(soapenv + "Body").Element(xnamespace + "AddUpdateClaimsResponse").Element(xnamespace + "ResponseHeader").Element(xnamespace + "SITransactionKey").Value;
                                ResponseCode = resultEnvelope.Root.Element(soapenv + "Body").Element(xnamespace + "AddUpdateClaimsResponse").Element(xnamespace + "ResponseHeader").Element(xnamespace + "ResponseCode").Value;
                                ResponseType = resultEnvelope.Root.Element(soapenv + "Body").Element(xnamespace + "AddUpdateClaimsResponse").Element(xnamespace + "ResponseHeader").Element(xnamespace + "ResponseType").Value;
                                ResponseMessage = resultEnvelope.Root.Element(soapenv + "Body").Element(xnamespace + "AddUpdateClaimsResponse").Element(xnamespace + "ResponseHeader").Element(xnamespace + "ResponseMessage").Value;
