    private void SaveXMLDoc(AddUPdateClaimsRequestResponse claim, string claimType)
    {
        //DENTAL CLAIMS  Header Name
        //string templateActualPath = AppSettings.Get("PDMS_SVC_TemplatesPath", string.Empty);
        string path = templateActualPath + @"\AddUPdateClaimsRequestResponse.xml";
        XmlDocument xdoc = new XmlDocument();
        xdoc.Load(path);
        var root = xdoc.GetElementsByTagName("soapenv:Body")[0];
        if (ViewState["mediclaimId"] == null) // save new claim
        {
            //var root = xdoc.GetElementsByTagName("add:AddUpdateClaimsResponse")[0];
            var node = root.CreateNavigator();
            var _namespace = new XmlSerializerNamespaces(new[] {
                         XmlQualifiedName.Empty
                 });
            //var _namespace = new XmlSerializerNamespaces();
            //_namespace.Add("add", "http://mes.gov/AddUpdateClaimsResponse");

            using (var writer = node.AppendChild())
            {
                var serializer = new XmlSerializer(claim.GetType());
                writer.WriteWhitespace("");
                serializer.Serialize(writer, claim, _namespace);
            }
        }
        else //update claim
        {

            var nodelist = root.ChildNodes;
            int counter = 0;

            AddUPdateClaimsRequestResponse response = null;
            foreach (XmlNode node in nodelist)
            {
                var updateserializer = new XmlSerializer(typeof(AddUPdateClaimsRequestResponse));
                using (var reader = new StringReader(node.OuterXml))
                {
                    var nodeClaimResponse = (AddUPdateClaimsRequestResponse)updateserializer.Deserialize(reader);
                    if (nodeClaimResponse != null && nodeClaimResponse.ClaimResponse != null && nodeClaimResponse.ClaimResponse.ResponseType != null)
                    {
                        var claimResponse = response.ClaimResponse.ResponseType.Split('~');
                        var _claimStatus = claimResponse[0];
                        var _claimType = claimResponse[1];
                        if (_claimType == claimType && nodeClaimResponse.ClaimResponse.SITransactionKey == ViewState["mediclaimId"].ToString())
                        {
                            //select & replace node items
                            XmlDocument newdoc = new XmlDocument();
                            using (var writer = newdoc.CreateNavigator().AppendChild())
                            {
                                var serializer = new XmlSerializer(claim.GetType());
                                var newnodenamespace = new XmlSerializerNamespaces(new[] { XmlQualifiedName.Empty });
                                writer.WriteWhitespace("");
                                serializer.Serialize(writer, claim, newnodenamespace);
                            }
                            root.ReplaceChild(root.OwnerDocument.ImportNode(newdoc.DocumentElement, true), root.ChildNodes[counter]);
                            break;
                        }
                    }
                }
            }
        }
        xdoc.Save(path);
    }

