    private DentalClaimsPDntlDetailDntlDtlKeyClmEntity[] GetDentalClmDetailEntity(string detailId)
    {

        List<AdditionalProvider> providersForDetail = ClaimService.AdditionalProviders.Where(s => s.num_dtl == detailId).ToList();

        List<DentalClaimsPDntlDetailDntlDtlKeyClmEntity> clmEntities = providersForDetail.Select(s => new DentalClaimsPDntlDetailDntlDtlKeyClmEntity
        {
            qlf_entity_type = GetentityType(),
            cde_provider_type = s.cde_provider_type,
            clmEntNmAdr = CreateClmEntNmAdr(s),
        }).ToList();



        return clmEntities.ToArray();
    }

    private DentalClaimsPDntlDetailDntlDtlKeyClmEntityClmEntNmAdr[] CreateClmEntNmAdr(AdditionalProvider provider)
    {
        DentalClaimsPDntlDetailDntlDtlKeyClmEntityClmEntNmAdr[] entNmAdr = new DentalClaimsPDntlDetailDntlDtlKeyClmEntityClmEntNmAdr[1];
        entNmAdr[0] = new DentalClaimsPDntlDetailDntlDtlKeyClmEntityClmEntNmAdr
        {
            qlf_entity_type = GetentityType(),
            clmNameNm1 = new DentalClaimsPDntlDetailDntlDtlKeyClmEntityClmEntNmAdrClmNameNm1
            {
                nam_first = provider.nam_first,
                nam_last = provider.nam_last,
                nam_middle = provider.nam_middle
            },
            partyIdentifier = new DentalClaimsPDntlDetailDntlDtlKeyClmEntityClmEntNmAdrPartyIdentifier
            {
                qlf_id_type = "XX",
                cde_party_id = provider.cde_party_id
            }
        };

        return entNmAdr;
    }


