    private List<diag_xrefModel> GetgvDiagnosissearchSearch()
    {
        List<diag_xrefModel> result = new List<diag_xrefModel>();

        foreach (GridViewRow gr in gvDiagnosisSearch.Rows)
        {
            if (gr.RowType == DataControlRowType.DataRow)
            {
                var cde_diag_seq = gr.Cells[0].Text;
                var qlf_code_list = gr.Cells[1].Text;
                var cde_diag = gr.Cells[2].Text;
                result.Add(new diag_xrefModel
                {
                    cde_diag_seq = cde_diag_seq,
                    cde_diag = cde_diag,
                    qlf_code_list = qlf_code_list
                });
            }


        }
        //result  // bind gridview column values
        return result;
    }
