    private PhysicianClaims GetPhysicianClaims(string claimStatus)
    {
        var physicianClaims = new PhysicianClaims
        {
            clmTrailer = new PhysicianClaimsClmTrailer { icnRegionCode = "" },
            pPhys = GetPhysicianClaimpPhys(claimStatus),

        };
        return physicianClaims;
    }
    private InstitutionalClaims GetInstitutionalClaims(string claimStatus)
    {
        var institutionClaims = new InstitutionalClaims
        {
            clmTrailer = new InstitutionalClaimsClmTrailer { icnRegionCode = "" },

            pUb92 = GetInstitutionClaimpUb92(claimStatus),


        };
        return institutionClaims;
    }



