    protected void cvProviderNotes_validate(object server, ServerValidateEventArgs args)
    {
        if (Regex.IsMatch(args.Value, "^[a-zA-Z0-9]*$"))
        {
            args.IsValid = true;
        }
        else
        {
            args.IsValid = false;
            return;
        }
    }





