    protected void btnOPadd_Click(object sender, EventArgs e)
    {

        ListItem i1 = new ListItem("Refering", "1");
        ListItem i2 = new ListItem("Operating", "2");
        ListItem i3 = new ListItem("New Operating", "3");
        ListItemCollection lic = new ListItemCollection();
        lic.Add(i1);
        lic.Add(i2);
        lic.Add(i3);

        var items1 = ddlOP1.Items;
        var items2 = ddlOP2.Items;
        var items3 = ddlOP3.Items;

        var selected1 = ddlOP1.SelectedValue;
        var selected2 = ddlOP2.SelectedValue;
        var selected3 = ddlOP3.SelectedValue;

        // set 3r dropdown values
        if (DivLine1.Visible && DivLine2.Visible)
        {
            ddlOP3.Items.Clear();
            //if (items1 != null)
            foreach (var item in lic.Cast<ListItem>().Where(x => x.Value != selected1 && x.Value != selected2))
            {
                ddlOP3.Items.Add(item);
            }

            DivLine3.Visible = true;
        }

        // set 2nd dropdown values
        if (DivLine1.Visible && !DivLine2.Visible)
        {
            ddlOP2.Items.Clear();
            //if (items1 != null)
            foreach (var item in lic.Cast<ListItem>().Where(x => x.Value != selected1 && x.Value != selected3))
            {
                ddlOP2.Items.Add(item);
            }
            DivLine2.Visible = true;
        }

        // set 1st dropdown values
        if (!DivLine1.Visible)
        {
            ddlOP1.Items.Clear();
            //if (items1 != null)
            foreach (var item in lic.Cast<ListItem>().Where(x => x.Value != selected2 && x.Value != selected3))
            {
                ddlOP1.Items.Add(item);
            }
            DivLine1.Visible = true;
        }
        if (DivLine1.Visible && DivLine2.Visible && DivLine3.Visible) { btnOPadd.Visible = false; }
    }
