    public void RefreshData()
    {
        string npi = txtHCPCSCode.Text;
        string medicadeId = txtMedicaidid1.Text;
        string firstName = txtFirstName.Text;
        string lastname = txtBusinessLastName.Text;
        DataTable dt = GetData(npi, medicadeId, lastname, firstName);

        if (Helper.HasRows(dt))
        {
            //dt = dt.Select("NPI <> ''").CopyToDataTable();
            gvSubmitClaimSearchPage.DataSource = dt;
            gvSubmitClaimSearchPage.DataBind();
        }
        else
        {
            gvSubmitClaimSearchPage.DataSource = null;
            gvSubmitClaimSearchPage.DataBind();
            ClearSearNpiFields();
        }

    }
