    protected void SaveClaimsNPIDetails(string _txtNPI, string _txtMedicaidId, string _txtFirstName, string _txtLastName, string tableName, int is_Primary, string claimsPanelName)
    {
        Dictionary<string, string> parms = new Dictionary<string, string>();
        DataSet dsIndividualClaims = svc.SelectDentalClaimData(Convert.ToInt32(hdnClaimId.Value), "claims_provider_information", claimsPanelName);
        if (!string.IsNullOrEmpty(hdnClaimId.Value))
        {
            if (Helper.HasRows(dsIndividualClaims) &&
                Convert.ToInt32(dsIndividualClaims.Tables[0].Rows[0]["Claim_ID"]) == Convert.ToInt32(hdnClaimId.Value) &&
                dsIndividualClaims.Tables[0].Rows[0]["Claims_Panel_Name"].ToString() == claimsPanelName)
            {
                parms.Add("NPI", _txtNPI.ToString());
                parms.Add("Medicaid_ID", _txtMedicaidId.ToString());
                parms.Add("First_Name", _txtFirstName.ToString());
                parms.Add("Last_Name", _txtLastName.ToString());
                parms.Add("Claim_ID", hdnClaimId.Value.ToString());
                parms.Add("Is_Primary", is_Primary.ToString());
                parms.Add("Last_Modified_User", Helper.GetUserId(HttpContext.Current.User.Identity.Name).ToString());
                parms.Add("Last_Modified_Date", DateTime.Now.ToString());
                parms.Add("Claims_Panel_Name", claimsPanelName.ToString());
                svc.UpdatePanelsData(tableName, parms);
            }
            else
            {
                parms.Add("NPI", _txtNPI.ToString());
                parms.Add("Medicaid_ID", _txtMedicaidId.ToString());
                parms.Add("First_Name", _txtFirstName.ToString());
                parms.Add("Last_Name", _txtLastName.ToString());
                parms.Add("Claim_ID", hdnClaimId.Value.ToString());
                parms.Add("Is_Primary", is_Primary.ToString());
                parms.Add("Created_By_User", Helper.GetUserId(HttpContext.Current.User.Identity.Name).ToString());
                parms.Add("Created_Date_Time", DateTime.Now.ToString());
                parms.Add("Claims_Panel_Name", claimsPanelName.ToString());
                svc.InsertPanelsData(tableName, parms);
            }
        }
    }

    protected void NPITextChanged(TextBox _txtNPI, TextBox _txtMedicaidId, TextBox _txtproviderName, TextBox _txtFirstName, TextBox _txtLastName, TextBox _txtMi, Label errorLabel)
    {
        errorLabel.Text = "";
        if (!string.IsNullOrEmpty(_txtNPI.Text))
        {
            if (_txtNPI.Text.Trim().Length == 10)
            {
                var isValid = ValidProviderNPI(_txtNPI.Text.Trim());
                if (!isValid)
                {
                    errorLabel.Text = "NPI not found in the system";
                }
                else
                {
                    DataTable dt = GetData(_txtNPI.Text.Trim(), "", "", "");
                    if (dt != null)
                    {

                        dt = dt.Select("NPI <> ''").CopyToDataTable();
                        if (dt.Rows.Count > 0)
                        {
                            DataRow row = dt.Rows[0];
                            if (_txtMedicaidId != null)
                            {
                                _txtMedicaidId.Text = row["MEDICAID_ID"].ToString();
                            }

                            if (_txtproviderName != null)
                            {
                                _txtproviderName.Text = row["FIRST_NAME"].ToString() + " " + row["LAST_OR_BUSINESS_NAME"].ToString();
                            }

                            if (_txtFirstName != null)
                            {
                                _txtFirstName.Text = row["FIRST_NAME"].ToString();
                            }
                            if (_txtLastName != null)
                            {
                                _txtLastName.Text = row["LAST_OR_BUSINESS_NAME"].ToString();
                            }
                        }
                    }
                }
            }
        }
        else
        {
            _txtMedicaidId.Text = string.Empty;
            _txtproviderName.Text = string.Empty;
        }
    }

    private void BindClaimDiagnosis(string code, string icdVersion, string diagnosisDes)
    {
        var result = LookupTableController.GetICDDiagnosisCodeSearchResults(code, icdVersion, diagnosisDes); //, icdVersion.Contains("ICD 10") ? "E" : "D"

        if (result != null && Helper.HasRows(result))
        {
            lblSearchEntryError.Text = String.Empty;
            gvClaimDiagnosisSearch.DataSource = result;
            gvClaimDiagnosisSearch.DataBind();
        }
        else
        {
            lblSearchEntryError.Text = "Search by a valid code or description";
        }
    }

    protected void btnDiagSearch_Click(object sender, EventArgs e)
    {
        this.gvClaimDiagnosisSearch.CurrentPageIndex = 0;
        if (String.IsNullOrEmpty(txtDiagnosisCodeSearch.Text) && String.IsNullOrEmpty(txtDiagnosisCodeDescSearch.Text))
        {
            lblSearchEntryError.Text = "Either diagnosis code or description is required";
            return;
        }
        else
        {
            lblSearchEntryError.Text = String.Empty;
        }
        BindClaimDiagnosis(txtDiagnosisCodeSearch.Text.Trim(), ddlICDVersion.SelectedValue, txtDiagnosisCodeDescSearch.Text.Trim());
    }

