    private void CreateControls(string index)
    {
        Literal ltrow = new Literal();
        ltrow.Text = "<div class='row' style='margin-left:20px;'>";
        pnlSection.Controls.Add(ltrow);
        Literal ltCol1 = new Literal();
        ltCol1.Text = "<div class='col-md-2 text-left'>";
