        DropDownList ddlDiagSequence = new DropDownList();
        ddlDiagSequence.ID = "ddlDiagSequence" + index;

        ddlDiagSequence.DataSource = GetDiagSequences();
        ddlDiagSequence.DataTextField = "PRIOR_AUTH_CLAIM_SEQUENCE_DESC";
        ddlDiagSequence.DataValueField = "PRIOR_AUTH_CLAIM_SEQUENCE_ID";
        ddlDiagSequence.DataBind();
        pnlSection.Controls.Add(ddlDiagSequence);
        Literal ltCol1End = new Literal();
        ltCol1End.Text = "</div>";
        pnlSection.Controls.Add(ltCol1End);
        Literal ltCol2 = new Literal();
        ltCol2.Text = "<div class='col-md-3 text-left'>";
        pnlSection.Controls.Add(ltCol2);
        TextBox txtDiagCode = new TextBox();
        txtDiagCode.ID = "txtDiagCode" + index;
        txtDiagCode.TextChanged += new EventHandler(textbox_TextChanged);
        txtDiagCode.AutoPostBack = true;
        txtDiagCode.EnableViewState = true;
        pnlSection.Controls.Add(txtDiagCode);
        LinkButton lnbtnSearch = new LinkButton();
        lnbtnSearch.Text = "Search";
        lnbtnSearch.ID = "llnbtnSearchSearch" + index;
        pnlSection.Controls.Add(lnbtnSearch);

        Literal ltCol2End = new Literal();
        ltCol2End.Text = "</div>";
        pnlSection.Controls.Add(ltCol2End);
        Literal ltCol3 = new Literal();
        ltCol3.Text = "<div class='col-md-3 text-left'>";
        pnlSection.Controls.Add(ltCol3);
        DropDownList ddlDiagPresentAdmission = new DropDownList();
        ddlDiagPresentAdmission.ID = "ddl" + index;
        if (_spa == null)
        {
            _spa = new PDMSService.PDMSServiceClient();
        }
        DataSet dataSet = _spa.GetPresentAddimission();
        DataTable dt = dataSet.Tables[0];
        ddlDiagPresentAdmission.DataSource = dt;
        ddlDiagPresentAdmission.DataTextField = "PRIOR_AUTH_CLAIM_PresentAddimission_DESC";
        ddlDiagPresentAdmission.DataValueField = "PRIOR_AUTH_CLAIM_PresentAddimission_ID";
        ddlDiagPresentAdmission.DataBind();
        pnlSection.Controls.Add(ddlDiagPresentAdmission);
        Literal ltCol3End = new Literal();
        ltCol3End.Text = "</div>";
        pnlSection.Controls.Add(ltCol3End);
        Literal ltCol4 = new Literal();
