        pnlSection.Controls.Add(txtDiagDes);
        Literal ltCol4End = new Literal();
        ltCol4End.Text = "</div>";
        pnlSection.Controls.Add(ltCol4End);
        Literal ltrowEnd = new Literal();
        ltrowEnd.Text = "</div>";
        pnlSection.Controls.Add(ltrowEnd);
    }
