        ExpandConditionBaseDiagnosisPanels();
        OtherpayerInformationExpand();
        if (rblClaimType.SelectedIndex > -1 && ddlPrimaryDestinationPayer.SelectedIndex > 0 && ddlDestinationPayerResponsibilitySequence.SelectedIndex > 0)
        {


            divallPanels.Visible = true;
            SaveAdjudicationSummaryData();
            if (!string.IsNullOrEmpty(hdnClaimId.Value))
            {
                LoadclaimAdjudicationSummaryStatusScreen();
                //Delete Other Payer Records
                DeleteOtherPayerData();
                //Clear other payer info
                ucOtherPayerInformation.ClearData(ddlDestinationPayerResponsibilitySequence.SelectedValue);
                //Delete Header Other Payer Adjustment Records and refresh grid
                DeleteHeaderOtherPayerAdjustmentData();
                RefreshHeaderOtherPayer();
                //Payer Paid Amount - Service Detail Records
                DeleteOtherPayerPaidAmountData();
                //Delete Other Payer Adjustment Information - Service Detail
                DeleteOtherPayerAdjustmentData();
            }

        }
        else if (string.IsNullOrEmpty(ddlDestinationPayerResponsibilitySequence.SelectedValue))
        {
            DeleteOtherPayerData();
            DeleteHeaderOtherPayerAdjustmentData();
            RefreshHeaderOtherPayer();
            //Payer Paid Amount - Service Detail Records
            DeleteOtherPayerPaidAmountData();
            //Delete Other Payer Adjustment Information - Service Detail
            DeleteOtherPayerAdjustmentData();
            ucOtherPayerInformation.ClearData(ddlDestinationPayerResponsibilitySequence.SelectedValue);
            ucOtherPayerInformation.GetFilteredPayerSequence();
        }
    }

