    private void RefreshHeaderOtherPayer()
    {
        if (rblClaimType.SelectedValue == CON.ClaimsType.Dental)
        {
            List<OtherPayerAdjustmentInfo> listData = new List<OtherPayerAdjustmentInfo>();
            ucSubmitClaimHeaderOtherPayerAdjustmentMapping.SetOtherPayerAdjustmentInfoPanelData(listData, null);
        }
        else if (rblClaimType.SelectedValue == CON.ClaimsType.Professional)
        {
            List<OtherPayerAdjustmentInfo> listData = new List<OtherPayerAdjustmentInfo>();
            ucSubmitClaimHeaderOtherPayerAdjustmentMappingProfessional.SetOtherPayerAdjustmentInfoPanelData(listData, null);
        }
        else if (rblClaimType.SelectedValue == CON.ClaimsType.Institutional)
        {
            List<OtherPayerAdjustmentInfo> listData = new List<OtherPayerAdjustmentInfo>();
            ucSSubmitClaimHeaderOtherPayerAdjustmentMappingInstitutional.SetOtherPayerAdjustmentInfoPanelData(listData, null);
        }
    }
    protected void SaveAdjudicationSummaryData()
    {
        string medicaid = "";
        string providerName = "";
        string npi = "";
        int claim_id = 0;
        Dictionary<string, string> parms = new Dictionary<string, string>();
        parms = new Dictionary<string, string>();
        DataSet ds = LoadProviderInformation(this.WorkflowPage.MedicaidID);
        if (Helper.HasRows(ds))
        {

            medicaid = Helper.GetString("MEDICAID_ID", ds.Tables[0].Rows[0]);
            providerName = Helper.GetString("NAME", ds.Tables[0].Rows[0]);
            npi = Helper.GetString("NPI", ds.Tables[0].Rows[0]);
        }
        parms.Add("Medicaid_id", medicaid);
        parms.Add("Provider_NPI", npi);
        parms.Add("Provider_Name", providerName);
        parms.Add("Claim_Type", rblClaimType.SelectedValue.ToString());
        parms.Add("Destination_Payer_ID", ddlPrimaryDestinationPayer.SelectedValue.ToString());
        hdnDestinationPayerId.Value = ddlDestinationPayerID.SelectedValue.ToString();
        if (!string.IsNullOrWhiteSpace(ddlDestinationPayerID.SelectedValue))
        {
            parms.Add("payer_ID", ddlDestinationPayerID.SelectedValue.ToString());

        }
        else
        {
            parms.Add("payer_ID", hdnDestinationPayerId.Value.ToString());
        }
        parms.Add("Destination_Payer_Res_Seq", ddlDestinationPayerResponsibilitySequence.SelectedValue.ToString());
        parms.Add("LAST_MODIFIED_USER", Helper.GetUserId(HttpContext.Current.User.Identity.Name).ToString());
        parms.Add("Last_modified_date", DateTime.Now.ToString());
        //if (!string.IsNullOrEmpty(txtICN2.Text))
        //{
        //    parms.Add("ICN", txtICN2.Text);
        //}

        if (chkPreDetClaim.Checked == true)
        {
            parms.Add("Predetermination_Claim", "PB");
        }
        else
        {
            parms.Add("Predetermination_Claim", null);
        }
        parms.Add("IS_deleted", "0");
        if (string.IsNullOrEmpty(hdnClaimId.Value.ToString()))
        {
            parms.Add("Created_By_User", Helper.GetUserId(HttpContext.Current.User.Identity.Name).ToString());
            parms.Add("Created_Date_Time", DateTime.Now.ToString());
            claim_id = svc.InsertPanelsData("claim_adjudication_summary_status_screen", parms);
            hdnClaimId.Value = claim_id.ToString();
        }
        else
        {
            parms.Add("Claim_ID", hdnClaimId.Value);
            svc.UpdatePanelsData("claim_adjudication_summary_status_screen", parms);

        }
    }


