    public void LoadclaimAdjudicationSummaryStatusScreen()
    {
        DataSet dsProviderInformation = LoadProviderInformation(this.WorkflowPage.MedicaidID);
        if (Helper.HasRows(dsProviderInformation))
        {
            string medicaid = Helper.GetString("MEDICAID_ID", dsProviderInformation.Tables[0].Rows[0]);
            string providerName = Helper.GetString("NAME", dsProviderInformation.Tables[0].Rows[0]);
            string npi = Helper.GetString("NPI", dsProviderInformation.Tables[0].Rows[0]);
            Dictionary<string, string> parms = new Dictionary<string, string>();
            parms = new Dictionary<string, string>();
            parms.Add("PROVIDERNPI", npi);
            parms.Add("MEDICAIDID", medicaid);
            parms.Add("NAME", providerName);
            parms.Add("Claim_ID", hdnClaimId.Value);



            DataSet dsClaimAdjudicationSummaryStatusScreen = svc.SelectPanelsData("claim_Adjudication_Summary_Status_Screen", parms);
            if (Helper.HasRows(dsClaimAdjudicationSummaryStatusScreen))
            {
                string ClaimStatus = Helper.GetString("Claim_Status", dsClaimAdjudicationSummaryStatusScreen.Tables[0].Rows[0]);
                //if (ClaimStatus != "2")
                //{
                divallPanels.Visible = true;
                string claimType = rblClaimType.SelectedValue = Helper.GetString("Claim_Type", dsClaimAdjudicationSummaryStatusScreen.Tables[0].Rows[0]);
                string payerSequence = ddlDestinationPayerResponsibilitySequence.SelectedValue = Helper.GetString("Destination_Payer_Res_Seq", dsClaimAdjudicationSummaryStatusScreen.Tables[0].Rows[0]);
                // //   if (!string.IsNullOrEmpty(hdnddlDestinationPayerID.Value.ToString()))
                // //  {
                // ddlDestinationPayerID.ClearSelection();
                // LoadDestinatinationPayerID();
                // ddlDestinationPayerID.Items.FindByValue(hdnddlDestinationPayerID.Value.ToString()).Selected = true;
                //// }
                // ddlDestinationPayerID.SelectedItem.Text = hdnddlDestinationPayerID.Value.ToString();

                if (ddlPrimaryDestinationPayer.SelectedIndex > 0 && !string.IsNullOrEmpty(ddlDestinationPayerID.SelectedItem.Text))
                {
                    ddlPrimaryDestinationPayer.SelectedValue = Helper.GetString("Destination_Payer_ID", dsClaimAdjudicationSummaryStatusScreen.Tables[0].Rows[0]);
                    if (string.IsNullOrWhiteSpace(ddlPrimaryDestinationPayer.SelectedValue))
                    {
                        ddlDestinationPayerID.Enabled = false;
                    }
                    else
                    {
                        LoadDestinatinationPayerID();
                    }
                    // ddlDestinationPayerID.SelectedValue = Helper.GetString("payer_ID", dsClaimAdjudicationSummaryStatusScreen.Tables[0].Rows[0]);

                }
                if (!string.IsNullOrEmpty(hdnddlDestinationPayerID.Value.ToString()))
                {
                    if (hdnddlDestinationPayerID.Value.Contains("-"))
                    {
                        ddlDestinationPayerID.SelectedIndex = ddlDestinationPayerID.Items.IndexOf(ddlDestinationPayerID.Items.FindByText(hdnddlDestinationPayerID.Value.ToString()));
                    }
                    else
                    {
                        ddlDestinationPayerID.SelectedIndex = ddlDestinationPayerID.Items.IndexOf(ddlDestinationPayerID.Items.FindByValue(hdnddlDestinationPayerID.Value.ToString()));
                    }

                }
                rblClaimType.Enabled = false;
                string claimId = hdnClaimId.Value = Helper.GetString("Claim_ID", dsClaimAdjudicationSummaryStatusScreen.Tables[0].Rows[0]);
                AssignClaimScreenValuesToUserControls(claimId, claimType, payerSequence);
                ucClaimAttachment.MedicaidId = medicaid;
                ucClaimAttachment.DestinationPayor = payerSequence;
                if (!string.IsNullOrEmpty(npi))
                {
                    ucRenderingProviderInformationPanel.BillingNPI = npi;
                    ucAdditionalProviderInfoPanel.BillingNPI = npi;
                }

            }
            else
            {
                rblClaimType.Enabled = true;
                rblClaimType.ClearSelection();
                ddlDestinationPayerResponsibilitySequence.ClearSelection();
                ddlPrimaryDestinationPayer.ClearSelection();
                ddlDestinationPayerResponsibilitySequence.Enabled = false;
                ddlPrimaryDestinationPayer.Enabled = false;
                hdnClaimId.Value = "";
            }
        }
    }

