    public void AssignClaimScreenValuesToUserControls(string claimID, string claimType, string payersequence)
    {
        ThreadId = Guid.NewGuid();
        Logging log = new Logging(ThreadId, "Reload all  panel data by AssignClaimScreenValuesToUserControls method");
        log.CreateLogEntry(string.Format("{0} {1}", "Assign Claim id and Cliam type: " + claimType + "in all panel's and Destination Payerdat: " + ddlDestinationPayerResponsibilitySequence.SelectedValue.ToString() + "  for cliam id:", hdnClaimId.Value.ToString()), Logging.LogPriority.Information);
        log.CreateLogEntry(string.Format("{0} {1}", "Destination Payerdat: " + ddlDestinationPayerResponsibilitySequence.SelectedValue.ToString() + " for cliam id:", claimID.ToString()), Logging.LogPriority.Information);

        ucServiceInformationInstitutional.ClaimId = claimID;
        ucDiagnosisCodePanel.ClaimID = claimID;
        ucPriorAuthorizationAndReferringPanel.ClaimID = claimID;
        ucOutpatientAdjudicationInformation.ClaimID = claimID;
        ucAdditionalProviderInfoPanel.ClaimID = claimID;
        ucReferringProvider.ClaimId = claimID;
        ucRenderingProviderInformationPanel.ClaimId = claimID;
        ucAssistantSurgeon.ClaimId = claimID;
        ucSupervisingProviderPanel.ClaimId = claimID;
        ucDelaySubmission.ClaimId = claimID;
        ucNDCDetails.ClaimId = claimID;
        ucOtherPayerPaidAmountServiceDetail.ClaimId = claimID;
        ucOtherPayerAdjustmentServiceDetail.ClaimId = claimID;
        ucProviderNotes.ClaimID = claimID;
        ucProviderBillingNotes.ClaimID = claimID;
        ucRecipientInformationPanel.ClaimId = claimID;
        ucAccidentInformation.ClaimId = claimID;
        ucToothQuadrant.ClaimId = claimID;
        ucServiceInformationDental.ClaimId = claimID;
        ucServiceInformationProfessional.ClaimId = claimID;
        ucSubmitClaimHeaderOtherPayerAdjustmentMapping.ClaimId = claimID;
        ucSubmitClaimHeaderOtherPayerAdjustmentMappingProfessional.ClaimId = claimID;
        ucAmbulancePickUpDropOff.ClaimId = claimID;
        ucAmbulanceInformation.ClaimId = claimID;
        ucServiceFacility.ClaimId = claimID;
        ucOtherPayerInformation.ClaimId = claimID;
        log.CreateLogEntry(string.Format("{0} {1}", "Checking  Claim id is null or empty for cliam id:", claimID.ToString()), Logging.LogPriority.Information);

        if (!string.IsNullOrWhiteSpace(hdnClaimId.Value) && (hdnClaimId.Value != claimID))
        {
            hdnClaimId.Value = claimID;
        }
        else if (string.IsNullOrWhiteSpace(hdnClaimId.Value))
        {
            hdnClaimId.Value = claimID;
        }
        log.CreateLogEntry(string.Format("{0} {1}", "Assigning cliam type to all panle for cliam id:", claimID.ToString()), Logging.LogPriority.Information);

        ucReferringProvider.ClaimType = claimType;
        ucRenderingProviderInformationPanel.ClaimType = claimType;
        ucAssistantSurgeon.ClaimType = claimType;
        ucSupervisingProviderPanel.ClaimType = claimType;
        ucDelaySubmission.ClaimType = claimType;
        ucNDCDetails.ClaimType = claimType;
        ucOtherPayerPaidAmountServiceDetail.ClaimType = claimType;
        ucOtherPayerInformation.ClaimType = claimType;
        ucOtherPayerAdjustmentServiceDetail.ClaimType = claimType;
        ucDiagnosisCodePanel.ClaimType = claimType;
        ucProviderNotes.ClaimType = claimType;
        ucProviderBillingNotes.ClaimType = claimType;
        ucRecipientInformationPanel.ClaimType = claimType;
        ucAdditionalProviderInfoPanel.ClaimType = claimType;
        ucServiceInformationProfessional.ClaimType = claimType;
        ucAttendingPhysicianInformation.ClaimType = claimType;
        log.CreateLogEntry(string.Format("{0} {1}", " Again assigning cliam id to all panle for cliam id:", claimID.ToString()), Logging.LogPriority.Information);

        ucSSubmitClaimHeaderOtherPayerAdjustmentMappingInstitutional.ClaimId = claimID;
        ucConditionCodeInformation.ClaimId = claimID;
        ucAttendingPhysicianInformation.ClaimId = claimID;
        ucInPatientAdjudicationInformation.ClaimId = claimID;
        ucServiceDetailsDental.ClaimId = claimID;
        ucOccurenceSpanInformation.ClaimID = claimID;
        ucSubmitClaimICDProcedureCode.ClaimId = claimID;
        ucValueCodeInformation.ClaimId = claimID;
        InstitutionalServiceDetails.ClaimId = claimID;
        ProfessionalServiceLineDetails.ClaimId = claimID;
        log.CreateLogEntry(string.Format("{0} {1}", "Assigning payersequence to all panle for cliam id:", claimID.ToString()), Logging.LogPriority.Information);

        ucOtherPayerInformation.PayerSeq = payersequence;
        //if (ucSubmitClaimOccurrenceInformation1 != null)
        //{
        ucSubmitClaimOccurrenceInformation1.ClaimId = claimID;
        //    ucSubmitClaimOccurrenceInformation1.ShowOccuurenceInforimation = true;
        //}
        //Attachment Panel
        ucClaimAttachment.ClaimId = claimID;
        ucClaimAttachment.ClaimType = claimType;
        log.CreateLogEntry(string.Format("{0} {1}", "Assigning Destination Payer  to dropdown for cliam id:", claimID.ToString()), Logging.LogPriority.Information);
        log.CreateLogEntry(string.Format("{0} {1}", "Destination Payerdat:" + ddlDestinationPayerResponsibilitySequence.SelectedValue.ToString() + " for cliam id:", claimID.ToString()), Logging.LogPriority.Information);
        ucClaimAttachment.DestinationPayor = ddlDestinationPayerResponsibilitySequence.SelectedValue.ToString();
        ucClaimAttachment.ReceiverCode = ddlDestinationPayerResponsibilitySequence.SelectedValue.ToString();



    }
