    private DataSet FetchOtherPayerInformation()
    {
        DataSet dsOtherPayerInfo = new DataSet();
        Dictionary<string, string> parms = new Dictionary<string, string>();
        parms.Add("Claim_ID", hdnClaimId.Value.ToString());
        dsOtherPayerInfo = svc.SelectPanelsData("claims_other_payer_information", parms);
        return dsOtherPayerInfo;
    }
    private DataSet FetchFilteredOtherPayerSequence()
    {
        DataSet ds = new DataSet();
        //return dataSet;
        List<SqlParameter> parameters = new List<SqlParameter>();
        parameters.Add(SqlParms.CreateParameter("Claim_ID", DbType.Int32, hdnClaimId.Value, true));
        parameters.Add(SqlParms.CreateParameter("Payer_Sequence", DbType.String, ddlDestinationPayerResponsibilitySequence.SelectedValue, true));
        ds = DataAccess.ExecuteStoredProcedure("usp_Otherpayer_Sequence_Check", parameters, "Claims_Other_Payer_information");
        return ds;
    }
