    public bool ValidatePayerSequenceOnSubmitAndSave()
    {

        DataSet dsOtherPayerInfo = FetchFilteredOtherPayerSequence();
        List<DataRow> list = dsOtherPayerInfo.Tables[0].AsEnumerable().ToList();

        if (Helper.HasRows(dsOtherPayerInfo))
        {
            if (dsOtherPayerInfo.Tables[0].Rows.Count > 0)
            {
                for (int i = 0; i < dsOtherPayerInfo.Tables[0].Rows.Count; i++)

                    switch (dsOtherPayerInfo.Tables[0].Rows[i]["PRIOR_AUTH_SUBMIT_CLAIM_PAYERSEQUENCE_ID"].ToString())
                    {
                        case "1":
                            ErrorMessage1.Visible = true;
                            ExpandOtherpayerInfo();

                            break;
                        case "2":
                            ErrorMessage2.Visible = true;
                            ExpandOtherpayerInfo();

                            break;
                        case "3":
                            ErrorMessage3.Visible = true;
                            ExpandOtherpayerInfo();

                            break;
                        case "4":
                            ErrorMessage4.Visible = true;
                            ExpandOtherpayerInfo();

                            break;
                        case "5":
                            ErrorMessage5.Visible = true;
                            ExpandOtherpayerInfo();

                            break;
                        case "6":
                            ErrorMessage6.Visible = true;
                            ExpandOtherpayerInfo();

                            break;
                        case "7":
                            ErrorMessage7.Visible = true;
                            ExpandOtherpayerInfo();

                            break;
                        case "8":
                            ErrorMessage8.Visible = true;
                            ExpandOtherpayerInfo();

                            break;
                        case "9":
                            ErrorMessage9.Visible = true;
                            ExpandOtherpayerInfo();

                            break;
                        case "10":
                            ErrorMessage10.Visible = true;
                            ExpandOtherpayerInfo();

                            break;


                        default:
                            // code block
                            break;
                    }
                return false;
            }
            else
            {
                // ClearPayerSequenceErrormessage();
                return true;
            }
        }
        else
        {
            //ClearPayerSequenceErrormessage();

            return true;
        }

    }

    private bool ValidateClaimsData()
    {
        bool returnValue = true;
        if (!checkServiceDetailsGridError())
        {
            returnValue = false;
        }
        else { lblServiceDetailsError.Text = ""; }
        if (!ValidatePayerSequenceOnSubmitAndSave())
        {
            returnValue = false;
        }
        if (!ValidateClaimsInstitutionalServiceDetailGridDate())
        {
            returnValue = false;
        }
        if (!ValidateDiagnosishasData())
        {
            returnValue = false;
        }
        if (!checkOtherPayerAdjustmentGridError())
        {
            returnValue = false;
        }
        else
        {
            lblOtherPayerAdjustmentGridError.Visible = false;
            lblOtherPayerAdjustmentGridError.Text = "";
        }
        if (!checkAdmissionDateServiceInfoGridError())
        {
            returnValue = false;
        }
        else
        {
            lblAdmissionDateServiceInfoGridError.Visible = false;
            lblAdmissionDateServiceInfoGridError.Text = "";
        }
        return returnValue;

    }
    private bool checkOtherPayerAdjustmentGridError()
    {
        bool checkStatus = false;
        lblOtherPayerAdjustmentGridError.Visible = true;
        lblOtherPayerAdjustmentGridError.Text = "";
        DataSet otherPayerInformation = new DataSet();
        // DataSet otherPayerAdjustmentServiceDetail = new DataSet();
        DataSet otherPayerPaidAmountDetail = new DataSet();
        otherPayerInformation = ucOtherPayerInformation.dataSetOtherPayer;
        if (Helper.HasRows(otherPayerInformation))
        {
            // otherPayerAdjustmentServiceDetail = ucOtherPayerAdjustmentServiceDetail.datasetOtherPayerAdjustmentInfo;
            otherPayerPaidAmountDetail = ucOtherPayerPaidAmountServiceDetail.datasetOtherPayerPaidAmount;
            var serviceLines = GetServiceLineNoFromServiceDetailPanel();
            for (int i = 0; i < otherPayerInformation.Tables[0].Rows.Count; i++)
            {
                var level_Desc = otherPayerInformation.Tables[0].Rows[i]["PRIOR_AUTH_SUBMIT_CLAIM_ADJUDICATION_LEVEL_DESC"].ToString();
                if (level_Desc == "Detail")
                {
                    var health_plan_id = otherPayerInformation.Tables[0].Rows[i]["Health_Plan_ID"].ToString();
                    bool isPlanExisted = false;
                    foreach (var serviceLine in serviceLines)
                    {
                        isPlanExisted = false;
                        for (int j = 0; j < otherPayerPaidAmountDetail.Tables[0].Rows.Count; j++)
                        {
                            if (otherPayerPaidAmountDetail.Tables[0].Rows[j]["Health_Plan_ID"].ToString().Equals(health_plan_id) &&
                                otherPayerPaidAmountDetail.Tables[0].Rows[j]["Service_Line"].ToString().Equals(Int32.Parse(serviceLine).ToString()))
                            {
                                isPlanExisted = true;
                            }
                        }
                        if (!isPlanExisted)
                        {
                            lblOtherPayerAdjustmentGridError.Text += "<div><a href='#ctl00_MainContent_uc5SubmitClaim_ucOtherPayerAdjustmentServiceDetail_ddlServiceLine' class='errorlist'>*Other payer payment information in service detail '" + serviceLine + "' for payer ID '" + health_plan_id + "' is required.</a></div>";
                        }
                    }

                }
            }

        }
        if (lblOtherPayerAdjustmentGridError.Text != "")
        {
            return checkStatus = false;
        }

        return checkStatus = true;
    }
    private bool checkAdmissionDateServiceInfoGridError()
    {
        bool checkStatus = false;
        lblAdmissionDateServiceInfoGridError.Visible = true;
        lblAdmissionDateServiceInfoGridError.Text = "";
        if (rblClaimType.SelectedValue == CON.ClaimsType.Institutional)
        {
            var fromDate = ucServiceInformationInstitutional.FromDate;
            var typeofBill = ucServiceInformationInstitutional.TypeofBill;
            var admissionDate = ucServiceInformationInstitutional.AdmissionDate;
            var NFICFTypes = new string[] { "021", "022", "023", "028", "051", "065", "066" };
            bool isNFICF = false;

            if (!string.IsNullOrEmpty(typeofBill) && !string.IsNullOrEmpty(fromDate) && !string.IsNullOrEmpty(admissionDate))
            {
                foreach (string value in NFICFTypes)
                {
                    if (typeofBill.StartsWith(value))
                    {
                        isNFICF = true;
                        break;
                    }
                }
                if (isNFICF && Convert.ToDateTime(admissionDate) > Convert.ToDateTime(fromDate))
                {
                    lblAdmissionDateServiceInfoGridError.Text = "<div><a href='#ctl00_MainContent_uc5SubmitClaim_ucServiceInformationInstitutional_txtAdmissionDate' class='errorlist'>*Admission date cannot be greater than From_date  in the service information.</a></div>";
                    return checkStatus = false;
                }
            }
        }

        return checkStatus = true;
    }
    private List<string> GetServiceLineNoFromServiceDetailPanel()
    {
        List<string> serviceLines = new List<string>();
        List<SqlParameter> param = new List<SqlParameter>();
        DataSet dsServiceLine = new DataSet();
        if (!string.IsNullOrEmpty(hdnClaimId.Value))
        {
            param.Add(SqlParms.CreateParameter("Claim_ID", DbType.Int32, hdnClaimId.Value, true));
            dsServiceLine = DataAccess.ExecuteStoredProcedure("usp_SelectClaims_Service_Details_Data", param, "Claims_Service_Details");
            if (Helper.HasRows(dsServiceLine) &&
                Convert.ToInt32(dsServiceLine.Tables[0].Rows[0]["Claim_ID"]) == Convert.ToInt32(hdnClaimId.Value))
            {
                DataTable dt = dsServiceLine.Tables[0];
                for (int i = 0; i < dt.Rows.Count; i++)
                {
                    var servicLineNo = dt.Rows[i]["Service_Line"].ToString();
                    serviceLines.Add(Int32.Parse(servicLineNo).ToString());
                }
            }
        }
        return serviceLines;
    }
