    private void GetNPIForPopUp()
    {
        if (!string.IsNullOrEmpty(hdnTxtSearchpop.Value))
        {
            string currentNPI = hdnTxtSearchpop.Value.Split('_')[4];
            switch (currentNPI)
            {

                case "txtReferringProviderNPI":
                    if (!string.IsNullOrEmpty(ucReferringProvider.ReferringProviderNPI))
                    { txtNPIpop.Text = ucReferringProvider.ReferringProviderNPI; }
                    break;
                case "txtPrimaryCareProviderNPI":
                    if (!string.IsNullOrEmpty(ucReferringProvider.PrimaryCareProviderNPI))
                    { txtNPIpop.Text = ucReferringProvider.PrimaryCareProviderNPI; }
                    break;
                case "txtProviderNPI":
                    // ucAdditionalProviderInfoPanel.ReferringProvider_Medicaid = hdnMedicaidId.Value;
                    if (!string.IsNullOrEmpty(ucAdditionalProviderInfoPanel.AdditionalProviderNPI))
                    { txtNPIpop.Text = ucAdditionalProviderInfoPanel.AdditionalProviderNPI; }
                    break;
                case "txtRenderingProvNPI": //Rendering
                    if (!string.IsNullOrEmpty(ucRenderingProviderInformationPanel.RenderingProviderNPI))
                    { txtNPIpop.Text = ucRenderingProviderInformationPanel.RenderingProviderNPI; }

                    break;
                case "txtSupervisingProviderNPI": //Supervising
                    if (!string.IsNullOrEmpty(ucSupervisingProviderPanel.SupervisingProviderNPI))
                    { txtNPIpop.Text = ucSupervisingProviderPanel.SupervisingProviderNPI; }
                    break;
                case "txtNPIServiceFacilityLocation": //Service facility
                    if (!string.IsNullOrEmpty(ucServiceFacility.NPIServiceFacilityInformation))
                    { txtNPIpop.Text = ucServiceFacility.NPIServiceFacilityInformation; }
                    break;
                case "txtAssistantSurgeonNPI":
                    if (!string.IsNullOrEmpty(ucAssistantSurgeon.AssistantSurgeonNPI))
                    { txtNPIpop.Text = ucAssistantSurgeon.AssistantSurgeonNPI; }
                    break;
                case "txtAttendingPhysicianNPI":
                    if (!string.IsNullOrEmpty(ucAttendingPhysicianInformation.AttendingPhysicianNPI))
                    { txtNPIpop.Text = ucAttendingPhysicianInformation.AttendingPhysicianNPI; }
                    break;
                default:
                    break;
            }


            if (!string.IsNullOrWhiteSpace(txtNPIpop.Text) ||
                !string.IsNullOrWhiteSpace(txtMedicaididPop.Text)
                || !string.IsNullOrWhiteSpace(txtlNamedPop.Text) ||
                !string.IsNullOrWhiteSpace(txtFNamedPop.Text))
            {
                dvNpiPop.Visible = false;
                SessionVarRetriever.DashBoardPartyIds = SessionVarRetriever.DashBoardRegistrationIds = string.Empty;
                SessionVarRetriever.DashBoardTableId = 0;
                this.gvSubmitClaimSearchPagePop.CurrentPageIndex = 0;
                RefreshDataPoPUP();
            }
            else
            {
                dvNpiPop.Visible = true;
            }
        }
    }

