    //Institutional-service details
    public bool ValidateClaimsInstitutionalServiceDetailGridDate()
    {
        bool status = true;
        DataSet serviceLineDetails = new DataSet();
        List<SqlParameter> parameters = new List<SqlParameter>();
        parameters.Add(SqlParms.CreateParameter("Claim_ID", DbType.Int32, hdnClaimId.Value, true));
        serviceLineDetails = DataAccess.ExecuteStoredProcedure("usp_Selectclaim_Professional_ServiceLine", parameters, "Claims_Service_Details");
        DataTable claimsDataTable = serviceLineDetails != null ? serviceLineDetails.Tables[0] : null;

        if (claimsDataTable != null && claimsDataTable.Rows.Count > 0)
        {
            DataView dv = claimsDataTable.DefaultView;
            dv.Sort = "To_Date_of_Service ASC";
            DataView dvtodate = claimsDataTable.DefaultView;
            dvtodate.Sort = "To_Date_of_Service DESC";
            DataTable dttodate = dvtodate.ToTable();
            DataTable dt = dv.ToTable();
            string fromDateStart = !string.IsNullOrEmpty(claimsDataTable.Rows[0]["Date_of_Service"].ToString()) ? Convert.ToDateTime(claimsDataTable.Rows[0]["Date_of_Service"]).ToString("MM/dd/yyyy") : "";
            string fromDateEnd = !string.IsNullOrEmpty(claimsDataTable.Rows[claimsDataTable.Rows.Count - 1]["Date_of_Service"].ToString()) ? Convert.ToDateTime(claimsDataTable.Rows[claimsDataTable.Rows.Count - 1]["Date_of_Service"]).ToString("MM/dd/yyyy") : "";
            string toDateEnd = !string.IsNullOrEmpty(dt.Rows[0]["To_Date_of_Service"].ToString()) ? Convert.ToDateTime(dt.Rows[0]["To_Date_of_Service"]).ToString("MM/dd/yyyy") : "";
            string toDateStart = !string.IsNullOrEmpty(dt.Rows[dttodate.Rows.Count - 1]["To_Date_of_Service"].ToString()) ? Convert.ToDateTime(dt.Rows[claimsDataTable.Rows.Count - 1]["To_Date_of_Service"]).ToString("MM/dd/yyyy") : "";
            lblServiceInformationErrorToDOS.Text = "";
            lblServiceInformationErrorFromDOS.Text = "";

            if (!string.IsNullOrEmpty(ucServiceInformationInstitutional.FromDate) && !string.IsNullOrEmpty(ucServiceInformationInstitutional.Todate))
            {
                if ((!((Convert.ToDateTime(fromDateStart)) >= (Convert.ToDateTime(ucServiceInformationInstitutional.FromDate)) && (Convert.ToDateTime(fromDateStart)) <= (Convert.ToDateTime(ucServiceInformationInstitutional.Todate))))
                    || (!((Convert.ToDateTime(fromDateEnd)) >= (Convert.ToDateTime(ucServiceInformationInstitutional.FromDate)) && (Convert.ToDateTime(fromDateEnd)) <= (Convert.ToDateTime(ucServiceInformationInstitutional.Todate)))))
                {
                    if ((Convert.ToDateTime(fromDateEnd)) != (Convert.ToDateTime(ucServiceInformationInstitutional.FromDate)) &&
                         (Convert.ToDateTime(fromDateEnd)) != (Convert.ToDateTime(ucServiceInformationInstitutional.Todate)))
                    {
                        lblServiceInformationErrorFromDOS.Text = "<div><a href='#ctl00_MainContent_uc5SubmitClaim_ucServiceInformationInstitutional_txtFromDate' class='errorlist'>*From DOS should be reported be within the statement period</a></div>";
                        //AddPatientControlNumberValidationErrorMessage("<div> *From DOS should be reported be within the statement period </div>");
                        status = false;
                    }
                }

                if (((!string.IsNullOrWhiteSpace(toDateStart)) && !((Convert.ToDateTime(toDateStart)) > (Convert.ToDateTime(ucServiceInformationInstitutional.FromDate)) &&
                    (Convert.ToDateTime(toDateStart)) < (Convert.ToDateTime(ucServiceInformationInstitutional.Todate))))
                    || ((!string.IsNullOrWhiteSpace(toDateEnd)) && !((Convert.ToDateTime(toDateEnd)) >= (Convert.ToDateTime(ucServiceInformationInstitutional.FromDate))
                    && (Convert.ToDateTime(toDateEnd)) < (Convert.ToDateTime(ucServiceInformationInstitutional.Todate)))))
                {
                    if ((!string.IsNullOrWhiteSpace(toDateStart)) && ((Convert.ToDateTime(toDateStart)) != (Convert.ToDateTime(ucServiceInformationInstitutional.FromDate)) &&
                            (Convert.ToDateTime(toDateEnd)) != (Convert.ToDateTime(ucServiceInformationInstitutional.Todate))))
                    {
                        lblServiceInformationErrorToDOS.Text = "<div><a href='#ctl00_MainContent_uc5SubmitClaim_ucServiceInformationInstitutional_txtToDate' class='errorlist'> *To DOS should be reported be within the statement period </a></div>";
                        //AddPatientControlNumberValidationErrorMessage("<div> *To DOS should be reported be within the statement period </div>");
                        status = false;
                    }
                }
            }

        }
        if (status == true)
        {
            status = validateICDCodewithFromDate();
        }
        return status;
    }

    public bool validateRequireFields()
    {
        bool returnValue = true;

        ClearPayerSequenceErrormessage();

        if (string.IsNullOrWhiteSpace(ddlDestinationPayerID.SelectedItem.Text))
        {
            lblDestinationPayerID.Visible = true;
            ddlDestinationPayerID.Enabled = true;
            returnValue = false;
        }
        string txtMedicaidBillingNumber = ucRecipientInformationPanel.MedicaidBillingNumber.ToString();
        if (txtMedicaidBillingNumber == null || txtMedicaidBillingNumber == "")
        {
            medicaidrequiredError.Visible = true;
            Label medicaidrequiredErrora = (Label)ucRecipientInformationPanel.FindControl("medicaidrequiredError");
            medicaidrequiredErrora.Text = "*Medicaid billing number is required";

            TextBox medicaid = (TextBox)ucRecipientInformationPanel.FindControl("txtMedicaidBillingNumber");
            medicaid.Style.Add("background-color", "gold");
            returnValue = false;

        }
        else
        {
            medicaidrequiredError.Visible = false;
            TextBox medicaid = (TextBox)ucRecipientInformationPanel.FindControl("txtMedicaidBillingNumber");
            medicaid.Style.Add("background-color", "white");

            Label medicaidrequiredErrorb = (Label)ucRecipientInformationPanel.FindControl("medicaidrequiredError");
            medicaidrequiredErrorb.Text = "";
            if (txtMedicaidBillingNumber.Length < 12)
            {
                ucRecipientInformationPanel.FindControl("medicaIdNumbers").Visible = true;
                returnValue = false;
            }
            else { ucRecipientInformationPanel.FindControl("medicaIdNumbers").Visible = false; }
        }


        string dateOfBirth = ucRecipientInformationPanel.BirthDate.ToString();


        if (dateOfBirth == null || dateOfBirth == "" || dateOfBirth == "01/01/1900")
        {
            recipientDOB.Visible = true;
            ucRecipientInformationPanel.FindControl("birthDateRequiredError").Visible = true;
            Label birthDateRequiredError = (Label)ucRecipientInformationPanel.FindControl("birthDateRequiredError");
            birthDateRequiredError.Text = "* Missing Recipient date of birth";
            TextBox dob = (TextBox)ucRecipientInformationPanel.FindControl("txtBirthDate");
            dob.Style.Add("background-color", "gold");
            dob.Text = string.Empty;
            returnValue = false;
        }
        else
        {
            recipientDOB.Visible = false;
            ucRecipientInformationPanel.FindControl("birthDateRequiredError").Visible = false;
            Label birthDateRequiredError = (Label)ucRecipientInformationPanel.FindControl("birthDateRequiredError");
            birthDateRequiredError.Text = "";
            TextBox dob = (TextBox)ucRecipientInformationPanel.FindControl("txtBirthDate");
            dob.Style.Add("background-color", "white");
        }
        try
        {
            ucRecipientInformationPanel.ShowRecipeintErrorMessage = string.Empty;
            if ((dateOfBirth != null && dateOfBirth != "" && dateOfBirth != "01/01/1900") && (txtMedicaidBillingNumber != null && txtMedicaidBillingNumber != ""))
            {
                string medicaidID = this.WorkflowPage.MedicaidID;
                Guid userId = Helper.GetUserId(HttpContext.Current.User.Identity.Name.ToString());
                var recipientInfo = ucRecipientInformationPanel.FindRecipient(txtMedicaidBillingNumber, medicaidID, userId, dateOfBirth);
                if (string.IsNullOrEmpty(recipientInfo.FirstName))
                {
                    ucRecipientInformationPanel.ShowRecipeintErrorMessage = "Valid recipient information is required";
                    ucRecipientInformationPanel.ClearAutoPopulatedFields();
                    returnValue = false;
                }
                else if (!string.IsNullOrEmpty(recipientInfo.FirstName))
                {
                    if (recipientInfo.Errors != null && recipientInfo.Errors.Count > 0)
                    {
                        StringBuilder errorMsg = new StringBuilder();
                        foreach (var ed in recipientInfo.Errors)
                        {
                            if (errorMsg.Length > 0)
                            {
                                errorMsg.Append("; ");
                                errorMsg.Append(ed.Code + " : " + ed.Description);
                            }
                            else
                                errorMsg.Append(ed.Code + " : " + ed.Description);
                        }
                        ucRecipientInformationPanel.ShowRecipeintErrorMessage = errorMsg.ToString();
                        ucRecipientInformationPanel.ClearAutoPopulatedFields();
                        returnValue = false;
                    }
                }
                else
                {
                    ucRecipientInformationPanel.ShowRecipeintErrorMessage = string.Empty;
                }
            }
        }

        catch (FaultException ex)
        {
            ucRecipientInformationPanel.ShowRecipeintErrorMessage = "Error: An error occurred while processing the request - " + ex.Message;
            ucRecipientInformationPanel.ClearAutoPopulatedFields();
            returnValue = false;
        }
        catch
        {
            ucRecipientInformationPanel.ShowRecipeintErrorMessage = "Error: An error occurred while processing the request";
            ucRecipientInformationPanel.ClearAutoPopulatedFields();
            returnValue = false;
        }


        string txtPatientControlNumber = ucRecipientInformationPanel.PatientControlNumber.ToString();
        if (txtPatientControlNumber == null || txtPatientControlNumber == "")
        {
            patientControlNoError.Visible = true;

            Label ControlNumberError = (Label)ucRecipientInformationPanel.FindControl("patientControlNumberError");
            ControlNumberError.Text = "*Patient Control Number is required";
            TextBox patientcontrolnumber = (TextBox)ucRecipientInformationPanel.FindControl("txtPatientControlNumber");
            patientcontrolnumber.Style.Add("background-color", "gold");

            returnValue = false;
        }
        else
        {
            patientControlNoError.Visible = false;

            Label ControlNumberError = (Label)ucRecipientInformationPanel.FindControl("patientControlNumberError");
            ControlNumberError.Text = "";
            TextBox patientcontrolnumber = (TextBox)ucRecipientInformationPanel.FindControl("txtPatientControlNumber");
            patientcontrolnumber.Style.Add("background-color", "white");
        }

        if (rblClaimType.SelectedValue == CON.ClaimsType.Institutional)
        {

            // service information panel
            string typeOfBill = ucServiceInformationInstitutional.TypeofBill.ToString();
            if (typeOfBill == null || typeOfBill == "")
            {
                typeOfBillError.Visible = true;
                TextBox typeBill = (TextBox)ucServiceInformationInstitutional.FindControl("txtTypeofBill");
                Label lblInstTypeBill = (Label)ucServiceInformationInstitutional.FindControl("lblInstTypeBill");
                lblInstTypeBill.Text = "* Type of bill is Required";
                typeBill.Style.Add("background-color", "gold");
                returnValue = false;
            }
            else
            {
                typeOfBillError.Visible = false;
                TextBox typeBill = (TextBox)ucServiceInformationInstitutional.FindControl("txtTypeofBill");
                Label lblInstTypeBill = (Label)ucServiceInformationInstitutional.FindControl("lblInstTypeBill");
                lblInstTypeBill.Text = "";
                typeBill.Style.Add("background-color", "white");
            }

            string releaseOfInfo = ucServiceInformationInstitutional.ReleaseofInformation.ToString();
            if (releaseOfInfo == null || releaseOfInfo == "" || releaseOfInfo == "0")
            {
                releaseOfInfoError.Visible = true;

                Label releaseInformationError = (Label)ucServiceInformationInstitutional.FindControl("releaseInformationError");
                releaseInformationError.Text = "* Release of Information is Required";
                DropDownList releaseInfo = (DropDownList)ucServiceInformationInstitutional.FindControl("ddlReleaseOfInfo");
                releaseInfo.Style.Add("background-color", "gold");
                returnValue = false;
            }
            else
            {
                releaseOfInfoError.Visible = false;
                DropDownList releaseInfo = (DropDownList)ucServiceInformationInstitutional.FindControl("ddlReleaseOfInfo");
                releaseInfo.Style.Add("background-color", "white");

                Label releaseInformationError = (Label)ucServiceInformationInstitutional.FindControl("releaseInformationError");
                releaseInformationError.Text = "";
            }

            string fromdate = ucServiceInformationInstitutional.FromDate.ToString();
            if (fromdate == null || fromdate == "")
            {
                fromDateRequiredError.Visible = true;
                Label fromdateError = (Label)ucServiceInformationInstitutional.FindControl("fromDateRequiredError");
                fromdateError.Text = "*From date is required";

                TextBox frmDate = (TextBox)ucServiceInformationInstitutional.FindControl("txtFromDate");
                frmDate.Style.Add("background-color", "gold");
                returnValue = false;
            }
            else
            {
                fromDateRequiredError.Visible = false;
                TextBox frmDate = (TextBox)ucServiceInformationInstitutional.FindControl("txtFromDate");
                frmDate.Style.Add("background-color", "white");
                Label fromdateError = (Label)ucServiceInformationInstitutional.FindControl("fromDateRequiredError");
                fromdateError.Text = "";
                Label fromdateFutureDateError = (Label)ucServiceInformationInstitutional.FindControl("fromDateFutureDateError");
                fromdateFutureDateError.Text = "";

                DateTime dt = DateTime.ParseExact(fromdate, "MM/dd/yyyy", CultureInfo.InvariantCulture);
                if (dt > DateTime.Today)
                {
                    ucServiceInformationInstitutional.FindControl("fromDateFutureDateError").Visible = true;
                    fromdateFutureDateError.Text = "*Future Date not allowed";
                    returnValue = false;
                }
                else { ucServiceInformationInstitutional.FindControl("fromDateFutureDateError").Visible = false; }
            }


            string toDate = ucServiceInformationInstitutional.Todate.ToString();
            if (toDate == null || toDate == "")
            {
                toDateRequiredError.Visible = true;

