    private void SaveToDbOnAdjust()
    {


        if (rblClaimType.SelectedValue == CON.ClaimsType.Dental)
        {
            ucOtherPayerInformation.SaveAdjustData((DataTable)ViewState["otherPayerInformationDataTable"]);
            ucDiagnosisCodePanel.SaveToDbonAdjust((DataTable)ViewState["DiagnosisTableDental"]);
            ucServiceDetailsDental.SaveToDbOnAdjust((DataTable)ViewState["DentalServiceDetailsTable"]);
            ucAdditionalProviderInfoPanel.SaveToDbOnAdjust((DataTable)ViewState["AdditionalProviderInformation"]);
            ucSubmitClaimHeaderOtherPayerAdjustmentMapping.SaveToDBonAdjust((DataTable)ViewState["HeaderOtherPayerAdjustmentInfoDT"]);
            ucOtherPayerPaidAmountServiceDetail.SaveToDBonAdjust((DataTable)ViewState["OtherPayerPaidAmountDataTable"]);
            ucOtherPayerAdjustmentServiceDetail.SaveToDbOnAdjust((DataTable)ViewState["OtherPayerPaidAdjustmentDataTable"]);
            ucProviderNotes.SaveToDbOnAdjustonDental((DataTable)ViewState["ProviderNotesDental"]);
            ucToothQuadrant.SaveToDbonAdjust((DataTable)ViewState["ToothSurfaceAndQuadrantTable"]);
            ucClaimAttachment.Save((DataTable)ViewState["ClaimAttachmentDental"]);
        }

        if (rblClaimType.SelectedValue == CON.ClaimsType.Institutional)
        {
            ucOtherPayerInformation.SaveAdjustData((DataTable)ViewState["OtherPayerInformationInstitutional"]);
            ucNDCDetails.SaveToDbOnAdjust((DataTable)ViewState["NDCInformationInstitutional"]);
            ucSubmitClaimOccurrenceInformation1.SavetoDbOnAdjust((DataTable)ViewState["OccurenceInformationTable"]);
            ucOccurenceSpanInformation.SaveToDbOnAdjust((DataTable)ViewState["OccurenceSpanInformationTable"]);
            ucConditionCodeInformation.SaveToDbOnAdjust((DataTable)ViewState["ConditionCodeInformationTable"]);
            ucValueCodeInformation.SaveToDbOnAdjust((DataTable)ViewState["ValueCodeInformationTableInst"]);
            ucSSubmitClaimHeaderOtherPayerAdjustmentMappingInstitutional.SaveToDBonAdjust((DataTable)ViewState["HeaderOtherPayerAdjustmentInst"]);
            //InstitutionalServiceDetails.SaveToDbOnAdjust((DataTable)ViewState["ServiceLineDetailsInstitutional"]);
            ucSubmitClaimICDProcedureCode.SaveToDbOnAdjust((DataTable)ViewState["ICDProcedureCodeInst"]);
            ucDiagnosisCodePanel.SaveToDbonAdjust((DataTable)ViewState["DiagnosisInformationInstitutional"]);
            InstitutionalServiceDetails.SaveToDbOnAdjust((DataTable)ViewState["ServiceLineDetailsInstitutional"]);
            ucAdditionalProviderInfoPanel.SaveToDbOnAdjust((DataTable)ViewState["AdditionalProviderInformationInstituional"]);
            ucClaimAttachment.Save((DataTable)ViewState["ClaimAttachmentInsti"]);
            ucOtherPayerPaidAmountServiceDetail.SaveToDBonAdjust((DataTable)ViewState["OtherPayerPaidAmountDataTableInsti"]);
            ucOtherPayerAdjustmentServiceDetail.SaveToDbOnAdjust((DataTable)ViewState["OtherPayerPaidAdjustmentDataTableInsti"]);
            ucProviderNotes.SaveToDbOnAdjustonDental((DataTable)ViewState["ProviderNotesInstitutional"]);
            ucProviderBillingNotes.SaveToDbOnAdjustonDental((DataTable)ViewState["ProviderBillingNotesInstitutional"]);
        }
        if (rblClaimType.SelectedValue == CON.ClaimsType.Professional)
