    private string GetNDCUnitOfMeasureCode(string value)
    {
        string code = string.Empty;
        switch (value)
        {
            case "International Unit":
                code = "F2";
                break;
            case "Gram":
                code = "GR";
                break;
            case "Milligram":
                code = "ME";
                break;
            case "Milliliter":
                code = "ML";
                break;
            case "Unit":
                code = "UN";
                break;
            default:
                code = string.Empty;
                break;
        }
        return code;
    }
    private bool ICDValidation()
    {
        bool isValid = true;
        if (Helper.HasRows(ucSubmitClaimICDProcedureCode.dataSetICDProdureCodeInfo))
        {
            DataView dataView = ucSubmitClaimICDProcedureCode.dataSetICDProdureCodeInfo.Tables[0].DefaultView;
            dataView.Sort = "ICD_Date DESC";
            DataTable dataTable = dataView.ToTable();
            string currentICDVersion = !string.IsNullOrEmpty(dataTable.Rows[0]["ICD_Version"].ToString()) ? dataTable.Rows[0]["ICD_Version"].ToString() : "";
            if (!string.IsNullOrEmpty(currentICDVersion) && !string.IsNullOrEmpty(ucServiceInformationInstitutional.Todate))
            {
                if ((currentICDVersion == "ICD 9") && (Convert.ToDateTime(ucServiceInformationInstitutional.Todate) >= Convert.ToDateTime("10/01/2015")))
                {
                    lblServiceDetailICDProcedureError.Text = "<div><a href='#ctl00_MainContent_uc5SubmitClaim_ucServiceInformationInstitutional_txtToDate' class='errorlist'> *ICD Version is invalid for given statement period. </a></div>";
                    isValid = false;
                }

                else if ((currentICDVersion == "ICD 10") && (Convert.ToDateTime(ucServiceInformationInstitutional.Todate) < Convert.ToDateTime("10/01/2015")))
                {
                    lblServiceDetailICDProcedureError.Text = "<div><a href='#ctl00_MainContent_uc5SubmitClaim_ucServiceInformationInstitutional_txtToDate' class='errorlist'> *ICD Version is invalid for given statement period. </a></div>";
                    isValid = false;
                }
            }

            // checking for Principal exists
            var count = dataTable.AsEnumerable().Where(r => r.Field<string>("Sequence_No") == CON.Sequences.Principal).Count();

            if (count.ToString() == "0")
            {
                lblServiceDetailICDProcedureError.Text = "<div><a href='#ctl00_MainContent_uc5SubmitClaim_ucServiceInformationInstitutional_txtToDate' class='errorlist'> *  Principal procedure code is required. </a></div>";
                isValid = false;
            }


        }
        return isValid;
    }


    private bool validateICDCodewithFromDate()
    {
        bool isValid = true;
        lblServiceDetailICDError.Text = "";
        lblServiceDetailICDProcedureError.Text = "";

        if (rblClaimType.SelectedValue == CON.ClaimsType.Institutional)
        {
            if (Helper.HasRows(ucDiagnosisCodePanel.dataSetDiagnosisCode))
            {
                //var ICD_versions = dsDiagnosisCodes.Tables[0].AsEnumerable().Select(row => row.Field<string>("ICDVersion"));
                DataView dv = ucDiagnosisCodePanel.dataSetDiagnosisCode.Tables[0].DefaultView;
                dv.Sort = "Last_Modified_Date DESC";
                DataTable dtlastdate = dv.ToTable();
                string currentICDVersion = !string.IsNullOrEmpty(dtlastdate.Rows[0]["ICDVersion"].ToString()) ? dtlastdate.Rows[0]["ICDVersion"].ToString() : "";
                if (!string.IsNullOrEmpty(currentICDVersion) && !string.IsNullOrEmpty(ucServiceInformationInstitutional.Todate))
                {
                    if ((currentICDVersion == "ICD 9") && (Convert.ToDateTime(ucServiceInformationInstitutional.Todate) >= Convert.ToDateTime("10/01/2015")))
                    {
                        lblServiceDetailICDError.Text = "<div><a href='#ctl00_MainContent_uc5SubmitClaim_ucServiceInformationInstitutional_txtToDate' class='errorlist'> *ICD Version is invalid for given statement period. </a></div>";
                        isValid = false;
                    }

                    else if ((currentICDVersion == "ICD 10") && (Convert.ToDateTime(ucServiceInformationInstitutional.Todate) < Convert.ToDateTime("10/01/2015")))
                    {
                        lblServiceDetailICDError.Text = "<div><a href='#ctl00_MainContent_uc5SubmitClaim_ucServiceInformationInstitutional_txtToDate' class='errorlist'> *ICD Version is invalid for given statement period. </a></div>";
                        isValid = false;
                    }
                }
            }
            isValid = ICDValidation();
        }
        else if (rblClaimType.SelectedValue == CON.ClaimsType.Dental)
        {
            if (Helper.HasRows(ucDiagnosisCodePanel.dataSetDiagnosisCode))
            {
                //var ICD_versions = dsDiagnosisCodes.Tables[0].AsEnumerable().Select(row => row.Field<string>("ICDVersion"));
                DataView dv = ucDiagnosisCodePanel.dataSetDiagnosisCode.Tables[0].DefaultView;
                dv.Sort = "Last_Modified_Date DESC";
                DataTable dtlastdate = dv.ToTable();
                DataView dvDentalService = ucServiceDetailsDental.dataSetServiceDetails.Tables[0].DefaultView;
                dvDentalService.Sort = "ServiceDate DESC";
                DataTable dtDentalService = dvDentalService.ToTable();
                string currentICDVersion = !string.IsNullOrEmpty(dtlastdate.Rows[0]["ICDVersion"].ToString()) ? dtlastdate.Rows[0]["ICDVersion"].ToString() : "";
                if (Helper.HasRows(dtDentalService))
                {
                    string dateofServiceDental = !string.IsNullOrEmpty(dtDentalService.Rows[0]["ServiceDate"].ToString()) ? Convert.ToDateTime(dtDentalService.Rows[0]["ServiceDate"]).ToString("MM/dd/yyyy") : "";
                    if (!string.IsNullOrEmpty(currentICDVersion))
                    {
                        if ((currentICDVersion == "ICD 9") && (Convert.ToDateTime(dateofServiceDental) >= Convert.ToDateTime("10/01/2015")))
                        {
                            lblServiceDetailICDError.Text = "<div><a href='#ctl00_MainContent_uc5SubmitClaim_ucServiceDetailsDental_txtdateofserviceDental' class='errorlist'> *ICD Version is invalid for given Date of Service. </a></div>";
                            isValid = false;
                        }

                        else if ((currentICDVersion == "ICD 10") && (Convert.ToDateTime(dateofServiceDental) < Convert.ToDateTime("10/01/2015")))
                        {
                            lblServiceDetailICDError.Text = "<div><a href='#ctl00_MainContent_uc5SubmitClaim_ucServiceDetailsDental_txtdateofserviceDental' class='errorlist'> *ICD Version is invalid for given Date of Service. </a></div>";
                            isValid = false;
                        }
                    }
                }
            }
        }
        else if (rblClaimType.SelectedValue == CON.ClaimsType.Professional)
        {
            if (Helper.HasRows(ucDiagnosisCodePanel.dataSetDiagnosisCode))
            {
                //var ICD_versions = dsDiagnosisCodes.Tables[0].AsEnumerable().Select(row => row.Field<string>("ICDVersion"));
                DataView dv = ucDiagnosisCodePanel.dataSetDiagnosisCode.Tables[0].DefaultView;
                dv.Sort = "Last_Modified_Date DESC";
                DataTable dtlastdate = dv.ToTable();
                DataTable dateofserce = ProfessionalServiceLineDetails.dataSetServiceDetails.Tables[0];
                if (dateofserce.Columns.Contains("ServiceDate"))
                {
                    dateofserce.Columns["ServiceDate"].ColumnName = "Date_of_Service";

                    dateofserce.AcceptChanges();
                }
                DataView dvProfessionalService = dateofserce.DefaultView;
                dvProfessionalService.Sort = "Date_of_Service DESC";
                DataTable dtProfessionalService = dvProfessionalService.ToTable();
                string currentICDVersion = !string.IsNullOrEmpty(dtlastdate.Rows[0]["ICDVersion"].ToString()) ? dtlastdate.Rows[0]["ICDVersion"].ToString() : "";
                if (Helper.HasRows(dtProfessionalService))
                {
                    if (!string.IsNullOrEmpty(dtProfessionalService.Rows[0]["Date_of_Service"].ToString()))
                    {
                        string dateofServiceProfessional = !string.IsNullOrEmpty(dtProfessionalService.Rows[0]["Date_of_Service"].ToString()) ? Convert.ToDateTime(dtProfessionalService.Rows[0]["Date_of_Service"]).ToString("MM/dd/yyyy") : "";
                        if (!string.IsNullOrEmpty(currentICDVersion))
                        {
                            if ((currentICDVersion == "ICD 9") && (Convert.ToDateTime(dateofServiceProfessional) >= Convert.ToDateTime("10/01/2015")))
                            {
                                lblServiceDetailICDError.Text = "<div><a href='#ctl00_MainContent_uc5SubmitClaim_ProfessionalServiceLineDetails_txtProffdateofservice' class='errorlist'> *ICD Version is invalid for given Date of Service. </a></div>";
                                isValid = false;
                            }

                            else if ((currentICDVersion == "ICD 10") && (Convert.ToDateTime(dateofServiceProfessional) < Convert.ToDateTime("10/01/2015")))
                            {
                                lblServiceDetailICDError.Text = "<div><a href='#ctl00_MainContent_uc5SubmitClaim_ProfessionalServiceLineDetails_txtProffdateofservice' class='errorlist'> *ICD Version is invalid for given Date of Service. </a></div>";
                                isValid = false;
                            }
                        }
                    }
                }
            }
        }
        return isValid;
    }
