    private string Truncate(string elementValue, string elementName)
    {
        string returnName = "";
        int maxLength = 256;

        if (elementName == "NM103_SubmitterLastOrOrganizationName")
        {
            maxLength = 60;
        }
        else if (elementName == "NM104_SubmitterFirstName")
        {
            maxLength = 35;
        }
        else if (elementName == "NM105_SubmitterMiddleName")
        {
            maxLength = 25;
        }
        else if (elementName == "PER02_SubmitterContactName")
        {
            maxLength = 60;
        }
        returnName = elementValue;

        return returnName.Length <= maxLength ? returnName : returnName.Substring(0, maxLength);
    }

    private string lookupProviderMedicaidID(string NPI, string lastOrOrgName, string firstName)
    {
        DataSet dsProviderDS;
        List<SqlParameter> parameters = new List<SqlParameter>();
        parameters.Add(SqlParms.CreateParameter("NPI", DbType.String, NPI, true));
        parameters.Add(SqlParms.CreateParameter("LAST_NAME", DbType.String, lastOrOrgName, true));
        parameters.Add(SqlParms.CreateParameter("FIRST_NAME", DbType.String, firstName, true));
        dsProviderDS = DataAccess.ExecuteStoredProcedure("usp_Claims_Lookup_Provider_Medicaid_ID", parameters, "Provider_Details");
        if (Helper.HasRows(dsProviderDS))
        {
            return dsProviderDS.Tables[0].Rows[0][0].ToString();
        }
        else
        {
            return string.Empty;
        }
    }
